/* chronicle data chunk: cn-05 | 元明 1276–1643 | 拆分自 cn-05（原片 352KB 超 320KB 上限），切点 1644 年 | 生成于 2026-09-21 */
window.__CHRONICLE_CHUNK = window.__CHRONICLE_CHUNK || {};
window.__CHRONICLE_CHUNK["cn-05"] = [
  { id: "cn--1276--s01", track: "cn", year: 1276, yearApprox: false, dim: "science", weight: 3, title: "郭守敬制成简仪", summary: "革浑仪之繁，创独立赤道装置，测影精度大进。", detail: { background: "旧浑仪环圈重叠，遮挡视线、读数不便。元初议改历，须先精仪器。", process: "1276年前后，郭守敬大都创简仪，把浑仪拆为赤道装置与立运仪两组，以窥管代游环，并用滚珠轴承式构造减少摩擦；同期作仰仪、景符、窥几等。", impact: "简仪使赤道坐标观测独立可行，为《授时历》提供数据；现存南京紫金山天文台明代铜仪为其改制。", figures: ["郭守敬","王恂"], place: "大都（今北京）", state: "元", sources: ["《元史》卷一六四《郭守敬传》","《元史·历志》","李迪《中国科学技术史·天文卷》"], tags: ["天文仪器","历法改革"] }, related: [] },
  { id: "cn--1276--s02", track: "cn", year: 1276, yearApprox: false, dim: "science", weight: 3, title: "元诏改治新历", summary: "设太史局改订新历，启动全国性实测工程。", detail: { background: "金《大明历》行用已久，朔蚀渐差；1271年蒙古改国号大元后欲以正朔立制。", process: "1276年元世祖诏许衡领太史院事，王恂治算历、郭守敬治仪器与观测，自1279年起组织二十七处「测验」，北至西伯利亚南部，南至琼州。", impact: "此次改历成为中国古代最大规模的实测天文学行动，成果即1280年《授时历》。", figures: ["许衡","王恂","郭守敬","忽必烈"], place: "大都及全国二十七观测点", state: "元", sources: ["《元史·历志五》","《元史·郭守敬传》"], tags: ["历法","实测"] }, related: ["cn--1276--s01"] },
  { id: "cn--1277--e01", track: "cn", year: 1277, yearApprox: false, dim: "economy", weight: 3, title: "元立泉州市舶司", summary: "元初设市舶司抽解蕃货，海上贸易税制成型。", detail: { background: "宋已在广州、泉州、明州置市舶司；元取浙闽后沿其法以充军国之用。", process: "1277年（至元十四年）元于泉州、庆元、上海、澉浦设市舶司，后增广州、杭州，行抽分制，粗货十五分取一、细货十分取一，并官买香药珍宝。", impact: "泉州成为当时世界最大港口之一，市舶之利成为元财政重要来源。", figures: ["蒲寿庚"], place: "泉州（今福建泉州）", state: "元", sources: ["《元史·世祖本纪》","《元典章·工部》","《泉州府志》"], tags: ["海外贸易","市舶司"] }, related: [] },
  { id: "cn--1279--m01", track: "cn", year: 1279, yearApprox: false, dim: "military", weight: 4, title: "崖山海战宋水军覆灭", summary: "元将张弘范断水围攻，陆秀夫负帝昺投海。", detail: { background: "1276年元取临安后，益王、卫王被陈宜中、陆秀夫、张世杰拥立，转走闽粤，1278年帝昺移驻崖山，聚舟千余为行朝。", process: "1279年正月张弘范、李恒军至崖山，先绝宋军汲水樵采之道，二月由南向北总攻。宋军巨舰铁索相连不能机动，自辰至午大溃，张世杰夺船出走溺死，陆秀夫负九岁帝昺投海，从死者号称十余万。", impact: "南宋军事力量就此终结，元完成对南方的征服。", figures: ["张弘范","陆秀夫","张世杰","赵昺"], place: "崖山（今广东江门新会南）", state: "元／南宋", sources: ["《宋史》卷四六《瀛国公纪》","《元史》卷一六二《张弘范传》"], tags: ["宋元之际","海战"] }, related: [] },
  { id: "cn--1279--p01", track: "cn", year: 1279, yearApprox: false, dim: "politics", weight: 5, title: "元并南宋成大一统", summary: "宋亡后元有全域，结束十世纪以来分裂格局。", detail: { background: "自880年代藩镇割据起，中国历五代、辽宋夏金长期并立；蒙古1234灭金、1273拔襄阳，至1279灭宋。", process: "崖山之役后，元朝版图北逾漠北、南尽南海，江南分设行省，大都为首都，兼行汉法与草原旧制，并以色目人、蒙古人参掌民政。", impact: "首次由北方游牧族群完成全域统一，奠定明清疆域与省制轮廓。", figures: ["忽必烈","伯颜","文天祥"], place: "大都／临安／崖山", state: "元", sources: ["《元史·世祖本纪》","《剑桥中国史》第6卷"], tags: ["大一统","政权更替"] }, related: ["cn--1279--m01"] },
  { id: "cn--1280--a01", track: "cn", year: 1280, yearApprox: true, dim: "art", weight: 3, title: "关汉卿杂剧名动大都", summary: "《窦娥冤》《救风尘》等成元杂剧典范。", detail: { background: "金元之际诸宫调、院本与歌舞戏合流，大都、平阳成为杂剧演出与刊刻中心。", process: "约1280年前后，关汉卿在大都创作搬演，钟嗣成《录鬼簿》录其目六十七种，今存《窦娥冤》《救风尘》《鲁斋郎》等十八种。", impact: "其写法与悲剧结构为元杂剧立范，后世列为元曲四大家之一。", figures: ["关汉卿","钟嗣成"], place: "大都（今北京）", state: "元", sources: ["《录鬼簿》卷上","《元曲选》","王国维《宋元戏曲史》"], tags: ["元杂剧","戏曲"] }, related: [] },
  { id: "cn--1280--i01", track: "cn", year: 1280, yearApprox: false, dim: "institution", weight: 4, title: "元行省制渐成定制", summary: "行中书省掌地方军政钱粮，为后世省制之源。", detail: { background: "金末元初「行省」本为尚书省出临地方的临时建制；灭宋前后为镇抚江南逐步固定。", process: "1280年前后，江浙、湖广、江西、福建、四川、云南等行省陆续置定，以丞相、平章政事、右左丞、参知政事为长官，统兵甲、钱粮、漕运；「腹里」直隶中书省。", impact: "省自此成为中国地方最高政区，明清布政使司与今省界多由此演化。", figures: ["忽必烈","史天泽","安童"], place: "大都及诸行省", state: "元", sources: ["《元史·百官志》","《元典章》","周振鹤《中国地方行政制度史》"], tags: ["地方制度","行省"] }, related: [] },
  { id: "cn--1280--s01", track: "cn", year: 1280, yearApprox: false, dim: "science", weight: 5, title: "《授时历》修成", summary: "定岁实365.2425日，行用逾四百年。", detail: { background: "1276年起许衡、王恂、郭守敬改历，经全国二十四点实测与三年推算。", process: "1280年新历成，定一回归年为365.2425日，距现代测定仅差26秒，并废除沿用千年的上元积年，以至元十八年（1281）为历元，次年正月颁行。", impact: "《授时历》为中国古代历法顶峰，明《大统历》即其沿用本，比欧洲格里高利历早三百年采用同一岁实。", figures: ["郭守敬","王恂","许衡"], place: "大都", state: "元", sources: ["《元史·历志五》","《授时历草》","李迪《中国科学技术史》"], tags: ["历法","天文学"] }, related: ["cn--1276--s02"] },
  { id: "cn--1281--m01", track: "cn", year: 1281, yearApprox: false, dim: "military", weight: 4, title: "元二次东征遇台风溃", summary: "四叶山战役十万舟师遇飓风覆没。", detail: { background: "1274年元第一次征日本未克；忽必烈屡遣使日本无报，1281年再举大军。", process: "1281年四月东路军、江南军分道东渡，会于壹岐、对马；闰七月在鹰岛博多湾一带遭台风两日，舟楫相碰覆溺，十万之众生还者不足二三。", impact: "此役使元放弃东征，日本以「神风」叙事强化镰仓幕府权威；征日苛敛亦成江南民变远因。", figures: ["忽必烈","范文虎","忻都"], place: "日本博多湾、鹰岛", state: "元", sources: ["《元史》卷二一〇《日本传》","《高丽史》","《八幡愚童训》"], tags: ["元日战争","台风"] }, related: ["world--1281--m01"] },
  { id: "cn--1283--e01", track: "cn", year: 1283, yearApprox: false, dim: "economy", weight: 4, title: "元开行海运漕粮", summary: "张瑄朱清以沙船由刘家港运粮京师。", detail: { background: "隋唐宋运河旧道淤浅，陆运脚费百倍，灭宋后江南米粮须北济大都。", process: "1283年（至元二十年）伯颜用宋降将张瑄、朱清，率沙船自平江刘家港出海，运粮四万六千石抵直沽；此后岁增，至1292年达八十二万八千余石。", impact: "海运成为元大都生命线，也促成江南造船与航海技术的高峰。", figures: ["伯颜","张瑄","朱清"], place: "刘家港至直沽（今苏州—天津）", state: "元", sources: ["《元史·食货志》","《元史·伯颜传》","《大元海运志》"], tags: ["漕运","海运"] }, related: [] },
  { id: "cn--1283--f01", track: "cn", year: 1283, yearApprox: false, dim: "figure", weight: 4, title: "文天祥就义大都", summary: "被拘三年的南宋丞相柴市从容赴死。", detail: { background: "1278年12月文天祥在广东海丰五坡岭被俘，次年过崖山拒写招降书，解送燕京。", process: "被拘近四年，元廷屡遣降臣劝诱，忽必烈许以中书左丞；1283年十二月（至元二十年）请便赐死，至柴市南向再拜就义，遗《正气歌》《过零丁洋》。", impact: "其诗文与死节成为后世气节叙事的核心文本。", figures: ["文天祥","忽必烈"], place: "大都柴市（今北京东城）", state: "元／南宋遗臣", sources: ["《宋史》卷四一八《文天祥传》","《文山先生全集》"], tags: ["气节","宋元之际"] }, related: ["cn--1279--m01"] },
  { id: "cn--1285--m01", track: "cn", year: 1285, yearApprox: false, dim: "military", weight: 3, title: "元军入越南大败", summary: "元军一度入升龙，被陈朝水陆游击击退。", detail: { background: "元以陈朝不朝为辞，1284年令唆都自占城、脱欢自广西两道南进。", process: "1285年元军一度入升龙（河内），陈兴道率水陆游击，于含关、章阳渡口截击，唆都战死、脱欢收兵北还。", impact: "元在南征战受挫，越南陈朝保住独立，此役亦耗元国力。", figures: ["陈兴道","脱欢","唆都"], place: "升龙（今越南河内）", state: "元／陈朝", sources: ["《元史·外国传》","《大越史记全书》卷五"], tags: ["元越战争","热带作战"] }, related: [] },
  { id: "cn--1287--e01", track: "cn", year: 1287, yearApprox: false, dim: "economy", weight: 4, title: "元发行至元通行宝钞", summary: "以银为本位行钞法，禁金银铜钱流通。", detail: { background: "元初用中统钞，因宋季铜钱内运、物价腾长而钞法渐坏。", process: "1287年（至元二十四年）尚书省奏行至元钞，一两折五贯，与中统钞并行，同时禁止民间金银私易、限铜钱不行。", impact: "元成为中国史上第一个纯纸币流通的王朝，也为后来恶性通胀埋下伏笔。", figures: ["桑哥","忽必烈"], place: "大都及各行省", state: "元", sources: ["《元史·食货志·钞法》","《至元颁行条格》"], tags: ["纸币","财政"] }, related: [] },
  { id: "cn--1288--i01", track: "cn", year: 1288, yearApprox: false, dim: "institution", weight: 4, title: "元更宣政院掌吐蕃", summary: "总制院改宣政院，统释教与西藏军政。", detail: { background: "1264元设总制院领天下释教，兼治吐蕃；八思巴以帝师主其事。", process: "1288年（至元二十五年）因唐制吐蕃来朝见宣政殿之义，改总制院为宣政院，以帝师领院事，置宣慰司、元帅府于乌思藏，行千户、驿站与户口清查。", impact: "西藏自此纳入中央政权专职机构管辖，政教合一制度由此定型。", figures: ["八思巴","忽必烈"], place: "大都／乌思藏", state: "元", sources: ["《元史·百官志》","《汉藏史集》","《元以来西藏地方与中央政府关系档案史料汇编》"], tags: ["西藏","宗教管理"] }, related: [] },
  { id: "cn--1288--m01", track: "cn", year: 1288, yearApprox: false, dim: "military", weight: 4, title: "白藤江之战元水军覆", summary: "陈兴道设木桩伏战，乌马儿被擒。", detail: { background: "1287年元以三道人越运粮，被陈军截断；1288年春乌马儿水军退走。", process: "1288年4月，陈兴道在白藤江（今越南广宁—海阳一带）预先植木桩于江心，趁潮落诱元舟入浅，伏兵火攻上下流，擒乌马儿、斩杀略尽。", impact: "元彻底放弃征服越南，东亚海上用兵格局由此固定。", figures: ["陈兴道","乌马儿","陈日烜"], place: "白藤江（今越南广宁省）", state: "元／陈朝", sources: ["《元史》卷二〇九《安南传》","《大越史记全书》卷六"], tags: ["白藤江","水战"] }, related: ["cn--1285--m01"] },
  { id: "cn--1289--s01", track: "cn", year: 1289, yearApprox: false, dim: "science", weight: 4, title: "会通河开成", summary: "安山至临清二百五十里河成，置闸三十一。", detail: { background: "1282年寿张县尹李伟建议开河，1283年济州河南接泗水、北接御河先成。", process: "1289年（至元二十六年）正月发山东民夫十七万开安山至临清段二百五十余里，六月河成，置闸三十一以节水，世祖赐名会通河。", impact: "自此江南漕舟可经泗、卫直达京师，大运河线东移，鲁西城镇因河而兴。", figures: ["李伟","忽必烈","张孔孙"], place: "安山至临清（今山东东平—临清）", state: "元", sources: ["《元史·河渠志三》","《会通河志》"], tags: ["运河","水利工程"] }, related: [] },
  { id: "cn--1290--i02", track: "cn", year: 1290, yearApprox: false, dim: "institution", weight: 3, title: "元整饬各路学校", summary: "立学官考课与学田制，儒学官学化。", detail: { background: "元初各路孔庙、学校多因兵毁；儒户虽有免役之令而学政松弛。", process: "1290年前后（至元二十七、二十八年）元廷申令各路设教授、学正、山长，给学田赡士，以《四书》《小学》课试升降学官。", impact: "官学与科举、贡举制度衔接，儒学体制在异族政权下延续下来。", figures: ["许衡","程钜夫"], place: "大都／各路府州县学", state: "元", sources: ["《元史·选举志》","《元典章·礼部》"], tags: ["教育","儒学"] }, related: [] },
  { id: "cn--1291--x01", track: "cn", year: 1291, yearApprox: true, dim: "explore", weight: 3, title: "马可·波罗离泉州归欧", summary: "随护送公主船队自海道返回威尼斯。", detail: { background: "马可·波罗1275年后在上都、大都任职，云游中国十七年；1291年伊儿汗国遣使迎阔阔真妃。", process: "约1291—1292年，他随使团自泉州乘海船，历占城、爪哇、苏门答腊、印度海岸，绕霍尔木兹陆路，1295年回到威尼斯。", impact: "其行程成为中世纪欧洲认识中国、印度洋航线的第一手坐标。", figures: ["马可·波罗","阔阔真","阿鲁浑"], place: "泉州—印度洋—威尼斯", state: "元", sources: ["《马可·波罗行纪》","《元史·诸王传》"], tags: ["中西交通","海路"] }, related: [] },
  { id: "cn--1293--s01", track: "cn", year: 1293, yearApprox: false, dim: "science", weight: 4, title: "通惠河成漕舟抵大都", summary: "郭守敬引白浮泉，二十里置闸十一。", detail: { background: "大都漕运至通州后仍需陆运，脚费浩大；郭守敬勘测北山水源。", process: "1293年（至元三十年）通惠河成，引昌平白浮泉诸水南汇瓮山泊，入大都城为积水潭，置闸十一以时启闭，长一百六十四里。", impact: "江南漕舟自此直入城中积水潭，大都成为水陆枢纽，也为北京城市水源立本。", figures: ["郭守敬","忽必烈"], place: "大都至通州（今北京）", state: "元", sources: ["《元史·河渠志》","《析津志辑校》"], tags: ["运河","城市水利"] }, related: ["cn--1289--s01"] },
  { id: "cn--1294--p01", track: "cn", year: 1294, yearApprox: false, dim: "politics", weight: 3, title: "忽必烈崩铁穆耳嗣位", summary: "元世祖去世，成宗立而停止对外征伐。", detail: { background: "1285年皇太子真金忧卒后储位久虚，诸王分镇漠北西北。", process: "1294年正月忽必烈崩于大都，四月皇孙铁穆耳（元成宗）在上都即位数日后即位，改元元贞，停止对外征伐、多所宽大。", impact: "元由扩张转内向，此后帝位更迭频繁、权臣迭起。", figures: ["忽必烈","铁穆耳","伯颜"], place: "大都／上都", state: "元", sources: ["《元史·成宗本纪》","《元史·世祖本纪》"], tags: ["皇位继承","元中期"] }, related: [] },
  { id: "cn--1295--s01", track: "cn", year: 1295, yearApprox: true, dim: "science", weight: 4, title: "黄道婆传棉纺于松江", summary: "自崖州归来授礅弹纺织法，江南棉业骤兴。", detail: { background: "宋代棉花（吉贝）种植已在闽广普及，而江南纺绩工具粗陋。元贞元年（1295）前后，松江乌泥泾人黄道婆自海南崖州归乡。", process: "她带去黎族错纱配色、综线挈花的织作技术，改制擀、弹、纺车，去籽用礅、弹棉用大弓，教一乡人，所织「乌泥泾被」行销浙直。", impact: "松江由此成棉布之冠，明代言「买不尽松江布」；棉布在14—15世纪取代麻成为主要衣料。", figures: ["黄道婆"], place: "松江府乌泥泾（今上海徐汇华泾）", state: "元", sources: ["陶宗仪《南村辍耕录》卷二四","《松江府志》","徐新我《中国棉纺织史稿》"], tags: ["棉纺织","技术传播"] }, related: [] },
  { id: "cn--1298--c01", track: "cn", year: 1298, yearApprox: false, dim: "culture", weight: 3, title: "《马可·波罗行纪》成书", summary: "热那亚狱中口述，欧洲始有系统华记。", detail: { background: "马可·波罗1298年于热那亚俘虏营中口述东方见闻。", process: "比萨公证人鲁斯蒂谦笔录成法语文本《叙述诸域之书》（Il Milione），述大都制度、纸币、驿站、煤炭与南方诸省。", impact: "该书成为近代早期欧洲地理学与对华认知的母题，哥伦布亦携其拉丁摘要本。", figures: ["马可·波罗","鲁斯蒂谦"], place: "热那亚监狱", state: "元／欧洲", sources: ["《马可·波罗行纪》","沙海昂注本"], tags: ["中西交通","地理知识"] }, related: ["cn--1291--x01"] },
  { id: "cn--1298--s01", track: "cn", year: 1298, yearApprox: false, dim: "science", weight: 4, title: "王祯造木活字印书", summary: "旌德县尹造木刻活字，一月印成县志。", detail: { background: "毕昇泥活字之后，元大德间王祯在地方官任上试用木活字并改进排印工艺。", process: "1298年（大德二年）王祯任温州瑞安、徽州旌德县尹时，命匠人造木活字三万有余，以轮盘排字、按韵号贮字，印《旌德县志》六千册，不及一月而完；原刻本不传，其《造活字印书法》全文载于《农书》。", impact: "这是世界印刷史上最早的木活字印本记录之一，其转轮排字法显著提高拣字效率。", figures: ["王祯"], place: "旌德（今安徽宣城旌德县）", state: "元", sources: ["王祯《农书·造活字印书法》","张秀民《中国印刷术的发明及其影响》"], tags: ["活字印刷","书籍"] }, related: [] },
  { id: "cn--1300--a01", track: "cn", year: 1300, yearApprox: true, dim: "art", weight: 3, title: "元杂剧全盛期", summary: "《录鬼簿》所载作家九十余，北曲甲天下。", detail: { background: "大德、至元间大都、真定、平阳、南京（开封）戏场林立，勾栏瓦舍商业化演出成形。", process: "约1300年前后，马致远、纪君祥、王实甫、白朴等名作并行；钟嗣成1330年成《录鬼簿》，录杂剧作家九十余、剧目四百余种。", impact: "元杂剧成为中国戏曲成熟的标志，其剧本结构、曲牌联套为后世典范。", figures: ["马致远","王实甫","白朴","钟嗣成"], place: "大都／平阳／真定", state: "元", sources: ["《录鬼簿》","王国维《宋元戏曲史》"], tags: ["元曲","戏曲"] }, related: ["cn--1280--a01"] },
  { id: "cn--1303--d01", track: "cn", year: 1303, yearApprox: false, dim: "disaster", weight: 3, title: "山西洪洞大地震", summary: "大德七年八月平阳太原地震极烈。", detail: { background: "山西临汾—洪洞一带位于汾河地堑，历史上多次强震。", process: "1303年9月17日（大德七年八月初五）平阳、太原路地震，估计震级8.0，洪洞赵城一带「城郭尽倾」，官府庐舍并圮，太原平晋县汾水涌出改道，死亡数十万（《元史》语，现代学者按人口重推为十余万至数十万不等）。", impact: "为华北有记录最强地震之一，灾后蠲免与赈济成元代财政负担。", figures: ["铁穆耳"], place: "平阳路赵城、洪洞（今山西临汾市）", state: "元", sources: ["《元史》卷二八《武宗本纪》、《五行志》","《大德河北志》","《中国历史强震目录》"], tags: ["地震","山西"] }, related: [] },
  { id: "cn--1305--i01", track: "cn", year: 1305, yearApprox: false, dim: "institution", weight: 3, title: "元站赤制度入于周详", summary: "陆水驿站遍布，铺马圣旨与牌面凭验。", detail: { background: "蒙古灭金、宋过程即以驿站（站赤）传命；统一后需维系大都至上都、各行省与漠北的联络。", process: "13世纪末至1305年前后（至元、大德间）屡颁站赤条画，全国设站约一千四百余处（不含诸王藩府），有水站、狗站，以铺马、驿券、牌面验给，站户免役而负担沉重。", impact: "驿站网使元能在辽阔疆域内调兵、运粮、传命，是世界前近代最庞大的邮传系统之一。", figures: ["铁穆耳"], place: "大都及各行省站赤", state: "元", sources: ["《元史·兵志·站赤》","《元典章·兵部》","《经世大典·站赤》"], tags: ["驿站","交通"] }, related: [] },
  { id: "cn--1307--p01", track: "cn", year: 1307, yearApprox: false, dim: "politics", weight: 3, title: "海山夺位为元武宗", summary: "安西王阿难答争位败，怀宁王立。", detail: { background: "1307年成宗崩，皇后卜鲁罕与安西王阿难答谋立幼帝。", process: "怀宁王海山自漠北南来，与母弟爱育黎拔力八达（仁宗）先据大都，1307年五月海山即位于上都，改至大，赐死阿难答。", impact: "开启武仁兄弟交替与至大变政，元代财政与帝位之争进入激化期。", figures: ["海山","爱育黎拔力八达","卜鲁罕"], place: "大都／上都", state: "元", sources: ["《元史·武宗本纪》","《元史·仁宗本纪》"], tags: ["帝位之争","元中期"] }, related: [] },
  { id: "cn--1309--e01", track: "cn", year: 1309, yearApprox: false, dim: "economy", weight: 3, title: "元至大改钞币制大乱", summary: "造至大银钞，钱钞并行而物价腾踊。", detail: { background: "武宗朝赏赐诸王、建中都、立稻田提举司，国用不继，钞法日敝。", process: "1309—1310年（至大二、三年）行至大银钞，一两折至大铜钱贯，收回至元钞，同时铸至大通宝、蒙古文大元通宝。", impact: "改币未能止住通胀，反而加剧物价混乱，仁宗即位后旋即罢之。", figures: ["海山","章闾"], place: "大都", state: "元", sources: ["《元史·食货志·钞法》","《元史·武宗本纪》"], tags: ["纸币","财政危机"] }, related: ["cn--1287--e01"] },
  { id: "cn--1310--a01", track: "cn", year: 1310, yearApprox: true, dim: "art", weight: 2, title: "《西厢记》杂剧流传", summary: "王实甫改写董西厢，成为北曲压卷。", detail: { background: "元稹《莺莺传》、董解元《西厢记诸宫调》为前本，元代大都、真定艺人搬演。", process: "约13—14世纪之交，王实甫作五本二十一折《崔莺莺待月西厢记》，「愿天下有情的都成了眷属」；明刻本据元本重编。", impact: "其体制突破一人主唱的杂剧常格，成为后世戏曲与小说的爱情叙事范本。", figures: ["王实甫","董解元"], place: "大都／真定", state: "元", sources: ["《录鬼簿》卷下","王季思《西厢记校注》"], tags: ["元杂剧","爱情叙事"] }, related: ["cn--1300--a01"] },
  { id: "cn--1312--e01", track: "cn", year: 1312, yearApprox: false, dim: "economy", weight: 2, title: "元代海运漕粮达峰值", summary: "皇庆间岁运三百余万石赡京师。", detail: { background: "至元以来海运岁增，船户由张瑄、朱清系统领，航线自刘家港经崇明、直沽。", process: "1312年（皇庆元年）前后岁运米约二百七十万石以上，至天历间一度达三百余万石，海船为六橹、九桅沙船，载重千石左右。", impact: "元代京师粮储几乎全赖江南海运，也促成造船与航海技术的成熟。", figures: ["爱育黎拔力八达"], place: "刘家港—直沽海路", state: "元", sources: ["《元史·食货志·海运》","《大元海运记》"], tags: ["漕运","海运"] }, related: ["cn--1283--e01"] },
  { id: "cn--1313--c01", track: "cn", year: 1313, yearApprox: false, dim: "culture", weight: 4, title: "元定程朱学为官学", summary: "国子监以朱熹《四书集注》课士。", detail: { background: "许衡在北方传朱子学，仁宗与李孟倡以经术取人。", process: "1313年（皇庆二年）诏以朱熹《四书章句集注》、《诗》传、《书》传、《易》程传《本义》诸书立国子监学，并诏置孔庙祀典。", impact: "程朱理学自此成为官方标准解释，影响元、明、清三代科场。", figures: ["爱育黎拔力八达","李孟","许衡"], place: "大都国子监", state: "元", sources: ["《元史·选举志》","《元史·李孟传》"], tags: ["理学","官学"] }, related: [] },
  { id: "cn--1313--s01", track: "cn", year: 1313, yearApprox: false, dim: "science", weight: 4, title: "王祯《农书》成书", summary: "兼论南北农业，绘农器图谱三百余种。", detail: { background: "王祯历任县尹，劝农课桑，集南北农学旧文与其经验。", process: "1313年（皇庆二年）《农书》成，三十七卷，分《农事纲领》《百谷之制》《耕织之宜》与《利用图谱》，收农器三百余种，含灌溉、纺车、犁、水转连磨、活字印法等。", impact: "中国古代首部兼论南北农业的综合性农书，其《农器图谱》保存了大量已佚机械。", figures: ["王祯"], place: "徽州旌德／杭州", state: "元", sources: ["王祯《农书》自序","《四库全书总目》农家类"], tags: ["农学","农具"] }, related: ["cn--1298--s01"] },
  { id: "cn--1315--i01", track: "cn", year: 1315, yearApprox: false, dim: "institution", weight: 5, title: "元延祐复科取士", summary: "罢废四十年的科举重开，分左右榜。", detail: { background: "金亡后北方长期无科举，元初以吏员、宿卫、荐举入仕，儒士沉抑。", process: "1313年议定科场程式，1315年（延祐二年）三月举行会试，七月殿试，蒙古、色目右榜、汉人南人左榜试经义、策论；1316年进士榜出，会试此后三岁一举。", impact: "儒士入仕通道重开并确立八股式经义考试范式，明、清科举实承其制。", figures: ["爱育黎拔力八达","李孟","许有壬"], place: "大都／上都", state: "元", sources: ["《元史·选举志一》","《延祐四明志》","《剑桥中国史》第6卷"], tags: ["科举","延祐复科"] }, related: ["cn--1313--c01"] },
  { id: "cn--1322--f01", track: "cn", year: 1322, yearApprox: false, dim: "figure", weight: 2, title: "赵孟頫卒于吴兴", summary: "宋宗室而入仕元朝，书画一代宗师。", detail: { background: "赵孟頫（1254—1322）为宋宗室之后，1286年程钜夫荐入朝，历官翰林学士承旨。", process: "1322年（至治二年）六月卒于故乡吴兴（今浙江湖州），追封魏国公，谥文敏；其楷书《胆巴碑》、行书《洛神赋》与《鹊华秋色图》传世。", impact: "以「复古」主张扭转南宋末书风，其文人画理论影响元四家及明清画史。", figures: ["赵孟頫","管道升","程钜夫"], place: "吴兴（今浙江湖州）", state: "元", sources: ["《元史》卷一七二《赵孟頫传》","《松雪斋集》"], tags: ["书法","文人画"] }, related: [] },
  { id: "cn--1323--p01", track: "cn", year: 1323, yearApprox: false, dim: "politics", weight: 4, title: "南坡之变英宗遇弑", summary: "铁失等弑帝于南店坡，改革骤停。", detail: { background: "英宗硕德八剌倚拜住推行「以儒治国」，清核冒滥田土、裁抑权贵，触怒铁失诸人。", process: "1323年（至治三年）八月，铁失等御史与晋王怯薛官联合，于上都以南三十里南坡店行帐中弑英宗及丞相拜住。", impact: "元代唯一一次较彻底的吏治改革中断，此后权臣、内战迭出。", figures: ["硕德八剌","拜住","铁失","也速迭儿"], place: "上都南坡（今内蒙古正蓝旗）", state: "元", sources: ["《元史·英宗本纪》","《元史·奸臣传》"], tags: ["政变","元中期"] }, related: [] },
  { id: "cn--1328--p01", track: "cn", year: 1328, yearApprox: false, dim: "politics", weight: 3, title: "元代两都之战", summary: "大都与上都各立帝，内战历时经年。", detail: { background: "1328年泰定帝崩于上都，佥枢密院事燕铁木儿在大都迎立图帖睦尔。", process: "八月上都立阿速吉八，大都军由燕铁木儿将，战于居庸、紫荆关，辽东与陕西诸王相继起兵，1329年大都军克上都，两帝皆死。", impact: "皇权受制于权臣与诸王，元中后期政局长期不稳。", figures: ["图帖睦尔","燕铁木儿","也孙铁木儿"], place: "大都—上都—陕西", state: "元", sources: ["《元史·文宗本纪》","《元史·泰定帝本纪》"], tags: ["内战","权臣"] }, related: [] },
  { id: "cn--1329--c01", track: "cn", year: 1329, yearApprox: false, dim: "culture", weight: 3, title: "元设奎章阁学士院", summary: "文宗立艺文机构，掌鉴藏与经筵。", detail: { background: "两都战后，文宗图帖睦尔欲以文治自饰。", process: "1329年（天历二年）置奎章阁学士院于大都，位正三品，以翰林儒臣进讲经史，掌宫廷书画鉴藏，柯九思、虞集、欧阳玄等任职。", impact: "成为元代宫廷书画与文献整理的中枢，传世名迹多钤其玺印。", figures: ["图帖睦尔","虞集","柯九思","欧阳玄"], place: "大都兴圣宫", state: "元", sources: ["《元史·文宗本纪》","《奎章阁记》"], tags: ["宫廷文化","书画鉴藏"] }, related: [] },
  { id: "cn--1330--e01", track: "cn", year: 1330, yearApprox: false, dim: "economy", weight: 3, title: "元厘定江南田粮科则", summary: "定江浙等地税粮等第，包税制渐兴。", detail: { background: "元取江南后沿用宋两税，籍没宋朝官田为重租田，江南赋重甲于各行省。", process: "1329—1330年（天历二、三年）屡诏减免江浙、江西重租，核定田亩科则，同时封爵诸王、寺院赐田拨给增多。", impact: "重租田问题成为元明之际江南赋税之争的核心，直接延续到明初。", figures: ["图帖睦尔"], place: "江浙行省（今苏南浙北）", state: "元", sources: ["《元史·食货志》","《续资治通鉴》元纪"], tags: ["赋税","江南"] }, related: [] },
  { id: "cn--1333--p01", track: "cn", year: 1333, yearApprox: false, dim: "politics", weight: 2, title: "妥懽帖睦尔即位", summary: "元顺帝立，权臣伯颜继燕铁木儿专政。", detail: { background: "1328—1333年间元廷帝位屡更，燕铁木儿、伯颜相继秉政。", process: "1333年（元统元年）十月初四，妥懽帖睦尔即位于大都，年十三，伯颜独秉国钧，杀高丽皇后奇氏之谋、诛让王阿拉特纳实里，至1340年脱脱始逐伯颜。", impact: "顺帝在位三十六年而元亡于明，前期权臣政治使中枢控制力持续下降。", figures: ["妥懽帖睦尔","伯颜","脱脱"], place: "大都", state: "元", sources: ["《元史·顺帝本纪》","《新元史·伯颜传》"], tags: ["权臣","元末"] }, related: [] },
  { id: "cn--1336--i01", track: "cn", year: 1336, yearApprox: false, dim: "institution", weight: 2, title: "元伯颜议罢科举", summary: "以科场为「虚文」，至元二年停科举。", detail: { background: "延祐复科后，取士数额少而汉人南人竞争烈；权臣伯颜抑儒士。", process: "1336年（至元二年）二月，中书省以科举「有妨选法」奏罢，各路取士停止，儒户学田多被夺。", impact: "士人失去正途，成为元末江南士人转投张士诚、朱元璋阵营的制度背景。", figures: ["伯颜","妥懽帖睦尔"], place: "大都／各行省", state: "元", sources: ["《元史·顺帝本纪》","《元史·选举志》"], tags: ["科举","元末政治"] }, related: ["cn--1315--i01"] },
  { id: "cn--1340--i02", track: "cn", year: 1340, yearApprox: false, dim: "institution", weight: 1, title: "元诏复科举", summary: "脱脱秉政后恢复延祐科举之制。", detail: { background: "1340年（至元六年）十月，台臣劾伯颜，其侄脱脱发动罢黜。", process: "十二月下诏复行科举，仍依延祐程式，三岁一举，至1344年重开会试、1345年殿试。", impact: "儒士入仕之门重开，但元末乱局已使取士规模与实效大减。", figures: ["脱脱","妥懽帖睦尔"], place: "大都", state: "元", sources: ["《元史·顺帝本纪》","《元史·脱脱传》"], tags: ["科举复行","元末"] }, related: [] },
  { id: "cn--1344--d01", track: "cn", year: 1344, yearApprox: false, dim: "disaster", weight: 4, title: "黄河白茅决口", summary: "河决曹州，北溃御河会通河，漕运受阻。", detail: { background: "12世纪末黄河改道北流后，河道摆动频繁；元末河防废弛。", process: "1344年（至正四年）五月，黄河决曹州白茅堤（今山东菏泽北），北溃御河以与会通河相接，山东河南北数千里皆成巨浸，漕运被迫完全改走海运，丁村、曹单一带大饥民疫。", impact: "河患持续十余年未治，成为红巾军起事与元财政崩溃的直接诱因。", figures: ["妥懽帖睦尔","贾鲁"], place: "曹州白茅（今山东菏泽）", state: "元", sources: ["《元史·河渠志》","《元史·五行志》","《至正河防记》"], tags: ["黄河","河患"] }, related: [] },
  { id: "cn--1345--c01", track: "cn", year: 1345, yearApprox: false, dim: "culture", weight: 3, title: "《辽》《金》《宋》三史成", summary: "脱脱主修三史，各与正统。", detail: { background: "元初以来屡议修三史，因「正统」之辨（以宋为正抑以金为正）争论数十年。", process: "1343年设局，1345年（至正五年）先后成《辽史》一百一十五卷、《金史》一百三十五卷、《宋史》四百九十六卷，右丞相脱脱都总裁，以「各与正统」解决体统之争。", impact: "《宋史》为二十四史卷帙最大者，保存大量宋人史料；三史至今为断代史基本文本。", figures: ["脱脱","欧阳玄","揭傒斯"], place: "大都翰林国史院", state: "元", sources: ["《辽史》《金史》《宋史》进表","《元史·脱脱传》"], tags: ["史学","官修史"] }, related: [] },
  { id: "cn--1348--d02", track: "cn", year: 1348, yearApprox: false, dim: "disaster", weight: 3, title: "元末江南大疫", summary: "至正八年至十二年间江浙死亡枕藉。", detail: { background: "1340年代后期黑死病向欧亚传播，元顺帝至正年间江南诸路频报大疫。", process: "1348年（至正八年）起，建德、绍兴、衢州、平江等地「死者十六七」「一巷百家死者八九十」，方志多载至1351年疫势稍息而户口凋耗。", impact: "人口损失加剧江南粮役崩溃与盐徒、灶户起事，学界对疫病因（鼠疫或霍乱）尚有争论。", figures: ["陶宗仪"], place: "江浙行省（今浙北苏南）", state: "元", sources: ["《至正四明续志》","《元史·五行志》","余新忠《中国历史上的疫病》"], tags: ["瘟疫","元末"] }, related: ["cn--1344--d01"] },
  { id: "cn--1350--e01", track: "cn", year: 1350, yearApprox: false, dim: "economy", weight: 3, title: "元至正变钞物价腾踊", summary: "铸至正通宝行交钞，米价十倍。", detail: { background: "黄河之役、军费与赏赐使元财政枯竭，至元钞法久坏。", process: "1350年（至正十年）二月，脱脱用吕思诚、崔敬议，铸「至正通宝」钱与历代钱并行，另造「至正交钞」十文当贯；行之数月，物价暴涨十倍，民间以钞为废纸。", impact: "币制崩溃使元廷丧失财政动员能力，同时激化江南社会矛盾，两年后红巾军起。", figures: ["脱脱","贾鲁"], place: "大都／江南诸路", state: "元", sources: ["《元史·食货志·钞法》","《南村辍耕录》"], tags: ["通货膨胀","纸币"] }, related: ["cn--1287--e01"] },
  { id: "cn--1351--a01", track: "cn", year: 1351, yearApprox: false, dim: "art", weight: 2, title: "至正型青花瓷断代", summary: "至正十一年对瓶成为元青花标准器。", detail: { background: "景德镇元代青花在14世纪前期成熟，钴料来自波斯（苏麻离青）。", process: "至正十一年（1351）造的「青花云龙纹象耳瓶」一对，颈题「信州路玉山县顺城乡德教里荆堂社……弟子张文进舍入」，现藏大英博物馆，成为元青花分期标准。", impact: "由此可定元青花年代序列，其外销使中东、东南亚宫廷大量收藏。", figures: ["张文进"], place: "景德镇（今江西景德镇）", state: "元", sources: ["大维德基金会藏至正十一年青花瓶铭文","冯先铭《中国陶瓷》","《江西省志·陶瓷志》"], tags: ["青花瓷","景德镇"] }, related: [] },
  { id: "cn--1351--m01", track: "cn", year: 1351, yearApprox: false, dim: "military", weight: 4, title: "颍州红巾军兵起", summary: "韩山童刘福通以弥勒、明王起兵。", detail: { background: "河工征夫怨叛，白莲会「弥勒下生」「明王出世」之说在汝颍流民中流传。", process: "1351年五月，韩山童、刘福通在颍州（今安徽阜阳）聚众，凿一足石人于一河，书「石人一只眼，挑动黄河天下反」，寻起兵杀元官，众至数万，皆巾红布为号。", impact: "红巾军之起拉开元末群雄割据，徐寿辉、郭子兴、彭莹玉相继响应。", figures: ["韩山童","刘福通","彭莹玉"], place: "颍州（今安徽阜阳）", state: "元", sources: ["《元史·顺帝本纪》","《新元史》韩林儿传","《庚申外史》"], tags: ["红巾军","白莲教"] }, related: ["cn--1351--s01"] },
  { id: "cn--1351--s01", track: "cn", year: 1351, yearApprox: false, dim: "science", weight: 3, title: "贾鲁堵白茅疏河道", summary: "十五万夫合龙白茅，河复故道。", detail: { background: "白茅决口七年不塞，都水监贾鲁上治河三策，1351年受命。", process: "1351年四月起，发河南诸路民夫十五万、军士供役（《元史》载合计十七万有奇），先疏濬故道二百八十里，至黄陵冈（今河南兰考）以船沉石法堵口，十一月河复故道北行。", impact: "工程虽成，然征发苛急直接引发颍州兵起；《至正河防记》是中国最早的治河专著。", figures: ["贾鲁","脱脱"], place: "黄陵冈—白茅（今河南兰考—山东菏泽）", state: "元", sources: ["《至正河防记》","《元史·贾鲁传》","《元史·河渠志》"], tags: ["治河","堤防工程"] }, related: ["cn--1344--d01"] },
  { id: "cn--1352--f01", track: "cn", year: 1352, yearApprox: false, dim: "figure", weight: 3, title: "朱元璋投濠州红巾军", summary: "二十五岁的和尚做了郭子兴亲兵。", detail: { background: "朱元璋（1328年生）少为皇觉寺僧、游食淮西，1352年濠州郭子兴起兵应颍州。", process: "1352年（至正十二年）二月，朱元璋入郭子兴军为亲兵九夫长，寻以李氏女为妻（后来的马皇后），年内升总管，1353年回乡募兵七百。", impact: "由是奠定其基本军事班底（徐达、汤和等淮西旧部），十五年后取天下。", figures: ["朱元璋","郭子兴","汤和"], place: "濠州（今安徽凤阳）", state: "元", sources: ["《明太祖实录》卷一","《皇陵碑》"], tags: ["明太祖","元末群雄"] }, related: ["cn--1351--m01"] },
  { id: "cn--1353--m02", track: "cn", year: 1353, yearApprox: false, dim: "military", weight: 2, title: "张士诚高邮起兵", summary: "白驹场盐丁杀弓兵，据有淮东。", detail: { background: "泰州白驹场盐丁苦于吏役盘剥，运盐生活朝不保夕。", process: "1353年（至正十三年）正月，张士诚与士义等十八条笼盐夫起，杀元弓兵，取泰州、兴化、高邮，1354年于高邮称诚王，国号大周，年号天祐。", impact: "张士诚据苏杭富地十余年，成为元末最富庶的割据政权，亦为朱元璋最后强敌。", figures: ["张士诚"], place: "白驹场—高邮（今江苏大丰—高邮）", state: "元", sources: ["《元史·顺帝本纪》","《明史》卷九七《张士诚传》"], tags: ["盐丁起事","元末群雄"] }, related: [] },
  { id: "cn--1354--p01", track: "cn", year: 1354, yearApprox: false, dim: "politics", weight: 2, title: "方国珍据浙东海上", summary: "世以贩盐浮海为业，三降三起。", detail: { background: "黄岩方国珍兄弟因贩盐被仇家告发，1348年起兵海上。", process: "1354年前后其势力已据台州、温州、庆元，反复接受元招降官职而又自立；以海舟通日本、高丽，劫漕船并贩盐。", impact: "打开了元末东南海上割据与对日贸易的通路，明初被迫迁海禁商。", figures: ["方国珍"], place: "黄岩、庆元（今浙江台州—宁波）", state: "元", sources: ["《新元史》卷二二五《方国珍传》","《明史》卷一二三"], tags: ["海商","割据"] }, related: [] },
  { id: "cn--1355--p02", track: "cn", year: 1355, yearApprox: false, dim: "politics", weight: 2, title: "韩林儿称帝亳州", summary: "小明王宋政权立，龙凤年号。", detail: { background: "韩山童死后，刘福通于1355年寻得其子。", process: "1355年二月迎韩林儿至亳州即皇帝位，号「小明王」，国号大宋，年龙凤，设中书省、行省，成为北方红巾军共主。", impact: "该政权牵制元军主力多年，朱元璋名义上长期奉龙凤正朔以自保。", figures: ["韩林儿","刘福通"], place: "亳州（今安徽亳州）", state: "宋（红巾军政权）", sources: ["《元史·顺帝本纪》","《明史·韩林儿传》"], tags: ["红巾军","政权并立"] }, related: ["cn--1351--m01"] },
  { id: "cn--1356--a02", track: "cn", year: 1356, yearApprox: true, dim: "art", weight: 3, title: "《琵琶记》成于至正间", summary: "高明作南戏，后世推为南戏之祖。", detail: { background: "南戏在温州形成，元末士人参与创作；高明（字则诚）中1345年进士后寓居宁波、温州。", process: "约1356年前后成《琵琶记》四十二出，写蔡伯喈、赵五娘，以「子孝妻贤」立旨，曲辞文雅。", impact: "被后世称为「南戏之祖」，标志南戏从俚俗向文人传奇的提升。", figures: ["高明"], place: "温州／宁波（今浙江）", state: "元", sources: ["《琵琶记》首出开宗明义","钱南扬《琵琶记校注》","《录鬼簿续编》"], tags: ["南戏","戏曲"] }, related: [] },
  { id: "cn--1356--m01", track: "cn", year: 1356, yearApprox: false, dim: "military", weight: 4, title: "朱元璋下集庆取应天", summary: "三攻集庆克之，改应天府为根本。", detail: { background: "1355年朱元璋渡江克太平，采「高筑墙、广积粮、缓称王」之策，志在建康。", process: "1356年（至正十六年）三月破集庆，得军民五十余万，改集庆路为应天府，置江南行中书省自为大元帅，李善长、徐达等分任。", impact: "据有建康使朱元璋得长江下游形胜与粮赋，为其称帝建明之基。", figures: ["朱元璋","徐达","李善长","常遇春"], place: "集庆（今江苏南京）", state: "元／吴", sources: ["《明太祖实录》卷四","《明史·太祖本纪》"], tags: ["应天府","元末群雄"] }, related: ["cn--1352--f01"] },
  { id: "cn--1358--m01", track: "cn", year: 1358, yearApprox: false, dim: "military", weight: 2, title: "毛贵北伐至直沽", summary: "红巾军东路入山东，兵锋抵京畿。", detail: { background: "1357年刘福通发兵三路北伐，毛贵率东路自淮北入山东。", process: "1358年（龙凤四年）二月克济南，进至清州、直沽（今天津一带），置宾兴科差、屯田；不久毛贵为赵君用所杀，诸将继相攻杀，北伐军遂退。", impact: "北伐动摇元廷根本但功败垂成，红巾军精锐损耗巨大。", figures: ["毛贵","刘福通","赵君用"], place: "山东—直沽（今济南—天津）", state: "宋（红巾军）", sources: ["《元史·顺帝本纪》","《新元史》毛贵传"], tags: ["红巾军北伐","元末"] }, related: ["cn--1355--p02"] },
  { id: "cn--1359--m02", track: "cn", year: 1359, yearApprox: false, dim: "military", weight: 1, title: "红巾军焚毁元上都", summary: "关先生破开平，宫阙焚毁。", detail: { background: "北伐西路、中路失败后，关铎、潘诚率部北趋辽东。", process: "1359年（至正十九年）七月，红巾军攻入上都开平（今内蒙古正蓝旗），焚毁宫阙后北入高丽。", impact: "元两都体制受创，此后元廷对上都的营建与巡幸大为衰落。", figures: ["关铎","潘诚"], place: "上都开平（今内蒙古正蓝旗）", state: "元", sources: ["《元史·顺帝本纪》","《高丽史》恭愍王世家"], tags: ["红巾军","上都"] }, related: [] },
  { id: "cn--1360--p01", track: "cn", year: 1360, yearApprox: false, dim: "politics", weight: 2, title: "陈友谅杀徐寿辉自立", summary: "采石兵变，国号大汉。", detail: { background: "徐寿辉1351年蕲水起兵称帝，陈友谅随倪文俊，1357年杀倪。", process: "1360年闰五月，陈友谅于采石（今安徽马鞍山）杀徐寿辉，自立为帝，国号大汉，年大义，以江西、湖广为辖区，众号六十万。", impact: "汉、吴两大政权在长江中游决战不可避免，1363年鄱阳湖之战遂起。", figures: ["陈友谅","徐寿辉"], place: "采石—江州（今安徽—江西九江）", state: "汉（陈友谅）", sources: ["《明史》卷一二三《陈友谅传》","《元史·顺帝本纪》"], tags: ["元末群雄","弑主"] }, related: [] },
  { id: "cn--1363--m01", track: "cn", year: 1363, yearApprox: false, dim: "military", weight: 4, title: "鄱阳湖大战陈友谅败死", summary: "三十六日湖水火攻，汉帝中流矢。", detail: { background: "1363年四月陈友谅围南昌（洪都）八十五日，朱元璋率舟师二万救援。", process: "七月至十月会战于鄱阳湖康郎山、鞋山一带，陈军巨舰连锁，朱军以火筏乘风纵击，友谅自窗中中流矢贯脑死，其子陈理退守武昌。", impact: "此役为中国古代最大规模湖水决战，朱元璋自此据有长江中游，元明易代的胜负已定。", figures: ["朱元璋","陈友谅","常遇春","徐达"], place: "鄱阳湖（今江西都昌—星子）", state: "吴／汉", sources: ["《明太祖实录》卷一一","《明史》卷一二三《陈友谅传》"], tags: ["鄱阳湖","水战"] }, related: ["cn--1360--p01"] },
  { id: "cn--1364--p01", track: "cn", year: 1364, yearApprox: false, dim: "politics", weight: 2, title: "朱元璋称吴王", summary: "应天称吴王，仍奉龙凤正朔。", detail: { background: "1363年底朱元璋自洪都还应天，刘基劝其称王以令将帅。", process: "1364年（至正二十四年）正月，朱元璋称吴王于应天，置百官而仍用韩林儿龙凤年号，1366年灭方国珍、1367年灭张士诚。", impact: "吴政权成为争夺正统的政治平台，两年后即位建明。", figures: ["朱元璋","李善长","刘基"], place: "应天府（今江苏南京）", state: "吴", sources: ["《明太祖实录》卷一四","《明史·太祖本纪》"], tags: ["称王","元末"] }, related: ["cn--1363--m01"] },
  { id: "cn--1366--p02", track: "cn", year: 1366, yearApprox: false, dim: "politics", weight: 1, title: "小明王沉舟瓜步", summary: "廖永忠迎韩林儿，溺于长江。", detail: { background: "龙凤政权已成名义，安丰之役后韩林儿、刘福通被朱元璋安置于滁州。", process: "1366年（吴二年）十二月，廖永忠奉命自滁州迎韩林儿至应天，行至瓜步（今江苏六合长江北岸）沉其舟，韩林儿死。", impact: "元末红巾军法统断绝，朱元璋不再有任何上位者，次年即平张士诚。", figures: ["韩林儿","廖永忠","刘福通"], place: "瓜步（今江苏六合）", state: "吴", sources: ["《明史·韩林儿传》","《国榷》卷三"], tags: ["皇位法统","元末"] }, related: ["cn--1355--p02"] },
  { id: "cn--1367--m01", track: "cn", year: 1367, yearApprox: false, dim: "military", weight: 3, title: "徐达围平江灭张士诚", summary: "十个月围城飞砲环击，城中粮尽。", detail: { background: "1366年秋朱元璋下书数张士诚八罪，命徐达、常遇春取浙西。", process: "1366年十二月—1367年（吴元年）九月围平江，筑长围、架飞砲百八十座环城轰击，城内粮尽人相食；九月十六日张士诚出降，旋缢死。", impact: "江南全境归吴，苏州富室被强制迁徙，明初江南重赋由此埋下根由。", figures: ["徐达","常遇春","张士诚"], place: "平江（今江苏苏州）", state: "吴", sources: ["《明太祖实录》卷二六","《明史·张士诚传》","《吴中纪事》"], tags: ["围城","元末"] }, related: ["cn--1353--m02"] },
  { id: "cn--1368--e01", track: "cn", year: 1368, yearApprox: false, dim: "economy", weight: 2, title: "明初迁江南富民实濠梁", summary: "苏州、松江富民被强制北迁。", detail: { background: "张士诚据苏州十三年，吴地士民多附之；明太祖欲削其根本。", process: "1368年前后（吴元年至洪武初）徙苏州、松江等地富民及旧臣于濠州、南京，籍没张士诚、方国珍部将田产为官田，江南重租田由此形成。", impact: "人口与地产的强制再分配造成明初江南经济凋弊，亦为洪武朝「苏松重赋」之因。", figures: ["朱元璋"], place: "苏州—濠州—南京", state: "明", sources: ["《明史·食货志》","《明太祖实录》","《苏州府志》"], tags: ["移民","江南赋税"] }, related: ["cn--1330--e01"] },
  { id: "cn--1368--m01", track: "cn", year: 1368, yearApprox: false, dim: "military", weight: 4, title: "明军入大都元北走", summary: "八月二元主北遁，徐达入齐化门。", detail: { background: "1368年七月朱元璋命中道北伐，一路下汴梁、潼关，元将扩廓帖木儿与李思齐内斗。", process: "闰七月元顺帝下诏罪己后北走，八月初二（1368年9月14日）徐达军自齐化门入大都，封府库图籍，改大都为北平，元朝在全国的统治结束。", impact: "元廷退居漠北称北元，华北由战乱转入明初重建，北边军事对峙开启。", figures: ["徐达","常遇春","妥懽帖睦尔","扩廓帖木儿"], place: "大都（今北京）", state: "明／元", sources: ["《明史·徐达传》","《元史·顺帝本纪》","《庚申外史》"], tags: ["北伐","元明易代"] }, related: ["cn--1368--p01"] },
  { id: "cn--1368--p01", track: "cn", year: 1368, yearApprox: false, dim: "politics", weight: 5, title: "明建国于应天府", summary: "正月即皇帝位，国号大明，建元洪武。", detail: { background: "1367年冬吴政权已据江南、浙江、湖广，定策北伐，宋濂拟即位仪注。", process: "1368年（戊申）正月四日，朱元璋即皇帝位南郊，定有天下之号曰大明，建元洪武，立妃马氏为皇后、世子标为皇太子，封功臣徐达、李善长等；二月以徐达为征虏大将军、常遇春为副，分道北伐。", impact: "明代自此开始，应天为南京，此后二百七十六年的制度与疆域格局在此奠定。", figures: ["朱元璋","马皇后","徐达","李善长"], place: "应天府（今江苏南京）", state: "明", sources: ["《明太祖实录》卷二九","《明史·太祖本纪》","《大明集礼》"], tags: ["开国","洪武"] }, related: ["cn--1367--m01"] },
  { id: "cn--1370--i01", track: "cn", year: 1370, yearApprox: false, dim: "institution", weight: 4, title: "卫所军制立为永业", summary: "五千六百人设一卫，军户世袭且屯且守。", detail: { background: "明初以诸将统兵为私属，须有常备兵制与养兵之财。", process: "1370年（洪武三年）前后定制：5600人为指挥使司（卫），千户所1120人、百户所112人，总旗管50、小旗管10；军籍世袭，另隶都督府与兵部，边地守城、内地屯田。", impact: "卫所与里甲并立构成明代军、民两套编户，其衰败直接决定明中后期的募兵与饷银财政。", figures: ["朱元璋","刘基"], place: "两京及各都司（治所在应天）", state: "明", sources: ["《明史·兵志》","《明太祖实录》卷五五","《明代卫所制度研究》"], tags: ["卫所","军制"] }, related: [] },
  { id: "cn--1370--p01", track: "cn", year: 1370, yearApprox: false, dim: "politics", weight: 2, title: "元顺帝崩于应昌", summary: "北元政权延续，爱猷识理达腊嗣立。", detail: { background: "1368年北走后的元廷仍保有官僚系统与帝号，控制漠南漠北。", process: "1370年（洪武三年）四月，元顺帝妥懽帖睦尔崩于应昌（今内蒙古克什克腾旗），太子爱猷识理达腊即位，据碑刻与蒙汉文史料仍称「大元」、建元宣光，继续与明对峙。", impact: "北元成为明初百年北边主要威胁，明代的九边、卫所与迁都之策皆由此生。", figures: ["妥懽帖睦尔","爱猷识理达腊"], place: "应昌（今内蒙古赤峰克什克腾旗）", state: "北元", sources: ["《明太祖实录》卷五一","《元史·顺帝本纪》","《蒙古源流》"], tags: ["北元","明初边政"] }, related: ["cn--1368--m01"] },
  { id: "cn--1371--c01", track: "cn", year: 1371, yearApprox: false, dim: "culture", weight: 2, title: "诏天下立社学", summary: "每五十家立社学，农闲教子弟。", detail: { background: "元末江南多有蒙学废弛；明初以教化与户役相维。", process: "1371年（洪武四年）十月，诏有司立社学，民间每五十家设学一所，延熟儒师，农闲令子弟读《孝经》、《小学》、《大学》，官司不得侵扰。", impact: "社学与里甲相配，构成明初基层教化网络，也为明代中后期蒙学与宗族教育奠基。", figures: ["朱元璋"], place: "应天及府州县乡村", state: "明", sources: ["《明太祖实录》卷六八","《明会典·学校》"], tags: ["教育","基层教化"] }, related: [] },
  { id: "cn--1371--e01", track: "cn", year: 1371, yearApprox: false, dim: "economy", weight: 3, title: "明初申严海禁", summary: "缘海民户不得擅造三桅大船通番。", detail: { background: "张士诚、方国珍残部遁入海上，与日本、琉球商船相结；太祖欲隔绝其资。", process: "1371年（洪武四年）十二月，诏吴中、浙江、福建、广东缘海民户原有四桅五桅大船并须改毁，不得私载货物下海番国贸易，违者重治。", impact: "海禁成为明代长期国策，东南私贩与倭寇问题由此而起，官方贸易改由朝贡勘合承担。", figures: ["朱元璋","汤和"], place: "东南沿海诸卫", state: "明", sources: ["《明太祖实录》卷七〇","《明史·海禁》","《大明律·公式》"], tags: ["海禁","朝贡贸易"] }, related: ["cn--1374--e01"] },
  { id: "cn--1371--i01", track: "cn", year: 1371, yearApprox: false, dim: "institution", weight: 3, title: "洪武始开科举取士", summary: "三年一贡，首科会试取士一百二十人。", detail: { background: "明初官制草创，功臣、吏员与荐举并行为仕进之途；太祖欲复儒治理。", process: "1371年（洪武三年）二月定科举程式，八月顺天、开封乡试开考，次年三月首科会试，取士一百二十名，以经义、论策分卷，并颁「科举作程式」。", impact: "科举成为明清两代官僚再生产的主渠道，八股程式自此定型。", figures: ["朱元璋","刘基","詹同"], place: "应天、开封（今南京—开封）", state: "明", sources: ["《明太祖实录》卷五〇","《明史·选举志》"], tags: ["科举","洪武"] }, related: ["cn--1315--i01"] },
  { id: "cn--1372--x01", track: "cn", year: 1372, yearApprox: false, dim: "explore", weight: 2, title: "明使日本却而不纳", summary: "杨载、吴用奉使日本，被留三年。", detail: { background: "明初倭寇扰浙闽沿海，太祖欲以诏谕止之。", process: "1372年（洪武五年）正月遣杨载、吴用等持书使日本（怀良亲王镇西），被留三年始还；日本分裂的南北朝与九州势力未接受明之封贡。", impact: "对日关系受阻，促使明强化海禁与沿海卫所，倭患与朝贡之争贯穿明代。", figures: ["杨载","怀良亲王","朱元璋"], place: "应天—博多（日本九州）", state: "明", sources: ["《明太祖实录》卷七二","《明史·日本传》","《苑园遗事》"], tags: ["中日关系","使节"] }, related: ["cn--1371--e01"] },
  { id: "cn--1373--i02", track: "cn", year: 1373, yearApprox: false, dim: "institution", weight: 2, title: "洪武罢科举行荐举", summary: "以所取多后生，停科举专用荐贤。", detail: { background: "首科取士多年轻士子，太祖认为不通吏务，更信「贤才须试」。", process: "1373年（洪武六年）二月诏停科举，命有司荐「贤良方正、经明行修」诸科，士人以荐牍入仕，1370—1380年代荐举与吏员出职为主流。", impact: "明初选官一度回归察举式路径，1384年复科举后始成定制，反映太祖对制度的实验性调整。", figures: ["朱元璋"], place: "应天府及各行省", state: "明", sources: ["《明太祖实录》卷七九","《明史·选举志》"], tags: ["选官","科举"] }, related: ["cn--1371--i01"] },
  { id: "cn--1374--e01", track: "cn", year: 1374, yearApprox: false, dim: "economy", weight: 2, title: "明罢三市舶司", summary: "泉州、明州、广州市舶司停废。", detail: { background: "海禁申严之下，宋元以来管理蕃舶的市舶机构失去职能。", process: "1374年（洪武七年）九月，罢泉州、明州、广州市舶司，蕃使朝贡归礼部主客司，民间海外贸易转入走私与番商私易。", impact: "官方海上贸易机关消失近二百年，东南海商集团（如漳泉海商）遂成明中叶倭乱的社会基础。", figures: ["朱元璋"], place: "泉州／明州／广州", state: "明", sources: ["《明太祖实录》卷九三","《明史·食货志》"], tags: ["市舶司","海禁"] }, related: ["cn--1277--e01"] },
  { id: "cn--1375--e01", track: "cn", year: 1375, yearApprox: false, dim: "economy", weight: 3, title: "发行大明通行宝钞", summary: "定钞贯准银一两，钱钞并行而禁私易。", detail: { background: "明初铜钱不足，军国支用浩大，太祖仿元钞法。", process: "1375年（洪武八年）三月造大明通行宝钞，每贯准铜钱一千文、白银一两，四贯准黄金一两，与「洪武通宝」钱并行，并禁民间以金银物货私相交易。", impact: "宝钞无准备金、只发不收，至明中叶几同废纸，实际货币遂白银化。", figures: ["朱元璋"], place: "应天及各行省", state: "明", sources: ["《明史·食货志·钱币》","《明太祖实录》卷九八"], tags: ["纸币","洪武财政"] }, related: ["cn--1287--e01"] },
  { id: "cn--1375--s01", track: "cn", year: 1375, yearApprox: false, dim: "science", weight: 2, title: "罢建凤阳中都", summary: "役军匠数万人，以「华靡」罢役。", detail: { background: "1372年（洪武五年）以临濠（凤阳）为帝乡，诏营中都，役工匠、军士、民夫数十万。", process: "1375年（洪武八年）六月，太祖以「工巧华靡，罢营造」下诏停建中都，改完南京城垣；中都遗址今存城墙与午门台基。", impact: "一次大规模都城工程骤停，反映明初财政与民力的紧张，凤阳地区长期负担徭役。", figures: ["朱元璋","李善长","刘基"], place: "临濠（今安徽凤阳）", state: "明", sources: ["《明太祖实录》卷一〇〇","《凤阳新书》"], tags: ["都城营建","徭役"] }, related: ["cn--1393--s01"] },
  { id: "cn--1376--i01", track: "cn", year: 1376, yearApprox: false, dim: "institution", weight: 4, title: "废行省设三司", summary: "承宣布政、都指挥、按察三权分立。", detail: { background: "元代行省权力过重，明初行中书省仍总揽钱粮兵刑。", process: "1376年（洪武九年）六月，改浙江、江西、湖广、山东、北平诸行中书省为承宣布政使司，掌民政财赋；与都指挥使司（军政）、提刑按察使司（刑名监察）分立，合称三司。", impact: "地方权分而皆直属朝廷，成为明代省制的定型形态，清代督抚制由此演化。", figures: ["朱元璋"], place: "两京十三布政使司", state: "明", sources: ["《明史·职官志》","《明太祖实录》卷一〇六","《明会典》"], tags: ["地方制度","三司"] }, related: ["cn--1280--i01"] },
  { id: "cn--1380--p01", track: "cn", year: 1380, yearApprox: false, dim: "politics", weight: 5, title: "胡惟庸案与废丞相", summary: "诛丞相、罢中书省，六部直接承旨。", detail: { background: "太祖疑胡惟庸专权结党；1380年正月以谋反罪诛之，此后屡兴党狱。", process: "1380年（洪武十三年）正月，杀丞相胡惟庸，罢中书省，升六部秩正二品，分大都督府为五军都督府；《明太祖实录》载其后株连三万余人，并诏后世不得议复丞相。", impact: "延续千年的宰相制度终结，皇权专制达到新阶段，明代中后期内阁由此空隙而生。", figures: ["朱元璋","胡惟庸","李善长","汪广洋"], place: "应天府", state: "明", sources: ["《明史》卷三〇八《胡惟庸传》","《明太祖实录》卷一二七","《昭示奸党录》"], tags: ["废丞相","皇权集中"] }, related: ["cn--1402--p01"] },
  { id: "cn--1381--i01", track: "cn", year: 1381, yearApprox: false, dim: "institution", weight: 4, title: "推行里甲赋役之制", summary: "一百一十户为一里，十甲轮年应役。", detail: { background: "明初户籍紊乱，赋役不均；须以基层编户控制丁粮。", process: "1381年（洪武十四年）正月，诏天下编赋役黄册，以一百一十户为一里，推丁粮多者十户为里长，余百户为十甲，甲首一人，岁一里长、十甲首相轮；城市曰坊、乡村曰里。", impact: "里甲成为明清基层治安、赋役、教化之基本单元，与保甲、乡约并行为地方控制体系。", figures: ["朱元璋"], place: "两京诸府州县", state: "明", sources: ["《明史·食货志》","《明太祖实录》卷一三一","《后湖志》"], tags: ["里甲","赋役"] }, related: ["cn--1391--i01"] },
  { id: "cn--1382--c01", track: "cn", year: 1382, yearApprox: false, dim: "culture", weight: 3, title: "南京国子监落成", summary: "鸡鸣山下新学成，监生历事六部。", detail: { background: "明初官学以集庆路学为国学，不足供给官僚；1381年营新学于鸡鸣山。", process: "1382年（洪武十五年）二月改国子学为国子监，祭酒宋讷立严规，堂舍数百间、光启门等具，监生最多时八千余人，遣历事于六部、都察院。", impact: "国子监成为洪武、永乐朝官僚主要来源，「监生历事」是明代特有的实习任官制。", figures: ["宋讷","朱元璋"], place: "南京鸡鸣山（今南京国学遗址）", state: "明", sources: ["《明史·选举志》","《南雍志》"], tags: ["官学","国子监"] }, related: ["cn--1371--c01"] },
  { id: "cn--1382--i01", track: "cn", year: 1382, yearApprox: false, dim: "institution", weight: 4, title: "设立锦衣卫", summary: "改仪鸾司为亲军，掌侍卫侦缉诏狱。", detail: { background: "废丞相后太祖需有直属皇帝的侦缉力量；胡蓝大狱需要独立司法。", process: "1382年（洪武十五年）四月，改仪鸾司为锦衣卫，设经历司、镇抚司，掌直驾侍卫、巡察缉捕，置诏狱，不受三法司节制；建文帝曾罢之，成祖复置并分设南、北镇抚司。", impact: "锦衣卫与后来的东厂、西厂合称厂卫，构成明代特务司法体制，为明代政治一大特征。", figures: ["朱元璋"], place: "应天府（后分北镇抚司）", state: "明", sources: ["《明史·刑法志》","《明会典·锦衣卫》","《明太祖实录》卷一四二"], tags: ["厂卫","特务政治"] }, related: ["cn--1380--p01"] },
  { id: "cn--1382--m01", track: "cn", year: 1382, yearApprox: false, dim: "military", weight: 3, title: "明军平定云南", summary: "傅友德、沐英三十万取大理、洱海。", detail: { background: "元梁王把匝剌瓦尔密据云南不附明；1381年秋明命征师。", process: "1381年十二月克昆明，梁王走死；1382年（洪武十五年）三月取大理、金齿，设云南都指挥使司与云南布政使司，沐英世镇其地，军屯、卫所遍布。", impact: "云南自此稳固纳入中央直辖，明代汉人移民与屯田改变了西南民族格局。", figures: ["傅友德","蓝玉","沐英","朱元璋"], place: "昆明／大理（今云南）", state: "明", sources: ["《明史》卷一二五《沐英传》","《明太祖实录》卷一四五","《滇考》"], tags: ["云南","屯卫"] }, related: [] },
  { id: "cn--1385--c01", track: "cn", year: 1385, yearApprox: false, dim: "culture", weight: 3, title: "颁行《御制大诰》", summary: "亲编判例峻令，全国家传人习。", detail: { background: "太祖以「胡元君暗臣弊」致乱，欲以峻法训民；1385年起辑在案重典。", process: "1385年（洪武十八年）十一月成《大诰》，1386、1387年续成《大诰续编》《大诰三编》，列凌迟、枭令、断手、阉刑诸例，颁国子监、社学，科举试以诰意，犯笞杖者遇诰加重。", impact: "法律与皇帝谕令合一，成为明代法外重刑之据；宣德后渐成具文而禁私传。", figures: ["朱元璋"], place: "应天府颁行天下", state: "明", sources: ["《御制大诰》序","《明史·刑法志》","《明太祖实录》卷一七五"], tags: ["明初法制","重典"] }, related: ["cn--1382--i01"] },
  { id: "cn--1385--p01", track: "cn", year: 1385, yearApprox: true, dim: "politics", weight: 3, title: "空印案重惩有司", summary: "持空印文册赴京者，主印者死。", detail: { background: "地方计吏岁赴京报钱粮，因册牍须与户部核对相符，习惯预持盖印空册。", process: "约1376—1385年间（洪武中期，具体年份史料记载分歧），太祖以空印为奸利之端，下令主印官员处死、佐贰官杖一百充军，株连数千百人。", impact: "此案与胡惟庸、蓝玉、郭桓四案并称洪武四大案，显示明初以重典绳吏治的取向。", figures: ["朱元璋"], place: "应天府及各布政司", state: "明", sources: ["《明史·刑法志》","赵翼《廿二史札记》卷三二「空印案」","《明太祖实录》"], tags: ["洪武四大案","吏治"] }, related: ["cn--1380--p01"] },
  { id: "cn--1387--i01", track: "cn", year: 1387, yearApprox: false, dim: "institution", weight: 3, title: "鱼鳞图册编定", summary: "核天下田亩，四至绘如鱼鳞。", detail: { background: "元明之际田土隐匿严重，赋役不均，须有可稽的地籍。", process: "1387年（洪武二十年）命国子监生分校天下田亩，丈核四至、丘段、肥瘠，绘为鱼鳞图册，与黄册互为表里，藏于户部及布政司、府县。", impact: "地籍与户籍并立，构成明初赋役征派的两大档案系统，为此后五百年田赋清丈之范式。", figures: ["朱元璋"], place: "天下州县（以直隶、浙江先行）", state: "明", sources: ["《明史·食货志》","《明太祖实录》卷一八三"], tags: ["地籍","赋役"] }, related: ["cn--1381--i01"] },
  { id: "cn--1388--m01", track: "cn", year: 1388, yearApprox: false, dim: "military", weight: 4, title: "捕鱼儿海之役破北元", summary: "蓝玉十五万出塞，掩其牙帐获众七万。", detail: { background: "北元脱古思帖木儿据哈拉哈河、捕鱼儿海一带，屡扰边；太祖命蓝玉为征虏大将军。", process: "1388年（洪武二十一年）四月，明军出庆都，兼程至捕鱼儿海（今中蒙边界贝尔湖），乘风沙大破元主营帐，获其次子地保奴、后妃诸王官属数千人、男女七万七千余；元主北遁，寻为也速迭儿所杀。", impact: "北元的官僚系统与人口根基被摧毁，蒙古退回部族分立状态，明北方暂安。", figures: ["蓝玉","脱古思帖木儿","朱元璋"], place: "捕鱼儿海（今贝尔湖）", state: "明／北元", sources: ["《明太祖实录》卷一八九","《明史·蓝玉传》","《蒙古源流》"], tags: ["北征","明蒙关系"] }, related: ["cn--1370--p01"] },
  { id: "cn--1391--i01", track: "cn", year: 1391, yearApprox: false, dim: "institution", weight: 3, title: "后湖黄册库成", summary: "天下赋役黄册汇总，十年一大造。", detail: { background: "1381年诏编黄册，诸司册籍散在地方，需有中央总库。", process: "1391年（洪武二十四年）天下郡县黄册修完，贮于南京后湖（今玄武湖）洲上册库，监官专职，其后每十年一大造，全盛时藏册数十万本。", impact: "国家以档案控制户口与赋役，黄册制度成为明代财政运作的基础，明中后期渐失真。", figures: ["朱元璋"], place: "南京后湖皇册库", state: "明", sources: ["《后湖志》","《明史·食货志》","《明会典·户部》"], tags: ["黄册","档案制度"] }, related: ["cn--1381--i01"] },
  { id: "cn--1393--e01", track: "cn", year: 1393, yearApprox: false, dim: "economy", weight: 3, title: "洪武二十六年户口田土账", summary: "户一千六十五万，口五千九百八十七万。", detail: { background: "明初经过战乱，太祖奖励垦荒、屯田与迁移，户口数自洪武元年起持续回升。", process: "1393年（洪武二十六年）户部统计载户一千六十五万二千八百七十、口五千九百八十七万三千三百、田土八百五十万七千六百二十三顷。", impact: "此为明代官方户口峰值记录之一；现代学者多认为实际人口高于册载，学界据以讨论明初复甦幅度。", figures: ["朱元璋"], place: "两京十二布政司", state: "明", sources: ["《明史·食货志》","《诸司职掌·户部》","何炳棣《中国人口研究》"], tags: ["人口统计","明初经济"] }, related: ["cn--1381--i01"] },
  { id: "cn--1393--p01", track: "cn", year: 1393, yearApprox: false, dim: "politics", weight: 4, title: "蓝玉案族诛功臣", summary: "凉国公以谋反罪死，株连万五千人。", detail: { background: "1393年前后太祖晚年储君幼弱，猜忌宿将；蓝玉恃功横暴、蓄庄奴。", process: "1393年（洪武二十六年）二月，锦衣卫指挥蒋瓛告蓝玉谋反，族诛，夷三族，坐党死者一万五千余人，元勋宿将相继尽；同年七月颁《逆臣录》。", impact: "与胡惟庸案合称胡蓝之狱，开国军事贵族被清洗，军权尽归皇帝，亦使靖难时建文帝无人可用。", figures: ["蓝玉","蒋瓛","朱元璋"], place: "应天府", state: "明", sources: ["《明史》卷一三二《蓝玉传》","《逆臣录》","《明太祖实录》卷二二六"], tags: ["洪武四大案","功臣"] }, related: ["cn--1380--p01"] },
  { id: "cn--1393--p02", track: "cn", year: 1393, yearApprox: false, dim: "politics", weight: 2, title: "明赐朝鲜国号", summary: "李成桂代高丽，太祖定其国名。", detail: { background: "1388年李成桂于威化岛（今鸭绿江中）回军夺权，1392年七月废恭让王自立，遣使请命。", process: "1392—1393年间，太祖取「朝日鲜明」之义，钦定国号为朝鲜，册封李成桂为国王，行明年号奉明正朔，定都汉阳。", impact: "奠定明与朝鲜二百余年宗藩关系，朝鲜成为明代最稳定的属国。", figures: ["李成桂","朱元璋"], place: "汉阳（今韩国首尔）", state: "明／朝鲜", sources: ["《明太祖实录》卷二二九","《朝鲜王朝实录·太祖实录》","《明史·朝鲜传》"], tags: ["宗藩关系","朝鲜"] }, related: [] },
  { id: "cn--1393--s01", track: "cn", year: 1393, yearApprox: false, dim: "science", weight: 3, title: "南京城垣工程竣成", summary: "周长九十六里，砖城为世界巨制。", detail: { background: "1366年起筑应天府新城，动用军夫、民夫数十万，烧砖由长江中下游诸府承担。", process: "1393年前后（洪武二十六年前）南京城完工，周长九十六里、实测约三十五公里，城高一四至二六米，设十三门，外砌巨砖、内夯黄土，并筑外郭。", impact: "现存南京明城墙为其遗构，是当时世界规模最大的砖石城垣工程之一。", figures: ["朱元璋"], place: "应天府（今南京）", state: "明", sources: ["《明太祖实录》","《洪武京城图志》","《南京城墙志》"], tags: ["城垣工程","南京"] }, related: ["cn--1375--s01"] },
  { id: "cn--1398--p01", track: "cn", year: 1398, yearApprox: false, dim: "politics", weight: 4, title: "太祖崩皇太孙嗣位", summary: "洪武三十一年闰五月帝崩，建文立。", detail: { background: "太子朱标1392年卒，太祖立皇孙朱允炆为皇太孙，诸王年长于帝而握兵边塞。", process: "1398年（洪武三十一年）闰五月初十太祖崩，二十日皇太孙即位，遗诏诸王临国中、无得至京，次年正月改元建文，以齐泰、黄子澄参预国事谋削藩。", impact: "削藩与藩王冲突迅速激化，两年后燕王起兵，明代皇位继承出现第一次内战。", figures: ["朱元璋","朱允炆","齐泰","黄子澄"], place: "应天府", state: "明", sources: ["《明史·恭闵帝纪》","《明太祖实录》卷二五七"], tags: ["皇位继承","建文"] }, related: ["cn--1393--p01"] },
  { id: "cn--1399--m01", track: "cn", year: 1399, yearApprox: false, dim: "military", weight: 4, title: "燕王以靖难起兵", summary: "朱棣杀谢贵据北平，称靖难之师。", detail: { background: "建文元年削夺周、齐、湘、代、岷五王，湘王自焚；燕王装病佯狂，密铸铁兵。", process: "1399年（建文元年）六月，谢贵、张昺奉逮命入府，被朱棣伏杀；七月燕王以「清君侧、靖国难」誓师起兵，张玉、朱能率八百勇士夺北平九门。", impact: "四年内战使华北残破，最终导致永乐朝对建文旧臣的血洗与迁都北平。", figures: ["朱棣","张玉","朱能","齐泰"], place: "北平（今北京）", state: "明", sources: ["《明史·成祖本纪》","《奉天靖难记》","《明史纪事本末》卷一六"], tags: ["靖难之役","内战"] }, related: ["cn--1398--p01"] },
  { id: "cn--1402--m01", track: "cn", year: 1402, yearApprox: false, dim: "military", weight: 3, title: "金川门之变京师陷", summary: "李景隆开门，宫中举火帝失踪。", detail: { background: "1401—1402年燕军直趋扬州、滁州，朝廷兵将多叛降；六月围京师。", process: "1402年（建文四年）六月十三日，谷王橞与李景隆开金川门纳燕军，宫中火起，建文帝一说自焚、一说由地道出亡，下落不明，成明代一大悬案。", impact: "明成祖以非常之获取位，其即位合法性问题影响永乐朝政治与下西洋的宣威动机。", figures: ["朱棣","李景隆","朱允炆","盛庸"], place: "应天府金川门", state: "明", sources: ["《明史·恭闵帝纪》","《明史纪事本末》卷一七","《致身录》（存疑）"], tags: ["靖难之役","建文帝下落"] }, related: ["cn--1399--m01"] },
  { id: "cn--1402--p01", track: "cn", year: 1402, yearApprox: false, dim: "politics", weight: 4, title: "成祖即位诛建文诸臣", summary: "方孝孺、齐黄等被族诛，革除党禁。", detail: { background: "1402年六月十七日朱棣即皇帝位，以建文之政为弊政，诏「复洪武之旧」。", process: "七月族诛方孝孺（坐死者八百七十三人，俗称「诛十族」）、齐泰、黄子澄、铁铉等，削夺建文年号谓之「革除」，同时改北平为北京、设东厂。", impact: "士风受重创，明初政治由儒术转向武功与特务监督，永乐集权达到新高峰。", figures: ["朱棣","方孝孺","姚广孝"], place: "应天府", state: "明", sources: ["《明史·成祖本纪》","《明史·方孝孺传》","《绝命词》"], tags: ["永乐","政治清洗"] }, related: ["cn--1402--m01"] },
  { id: "cn--1403--p01", track: "cn", year: 1403, yearApprox: false, dim: "politics", weight: 3, title: "改北平为北京", summary: "升其地为行在，建六部衙署。", detail: { background: "燕王旧藩在北，北边用兵与控扼蒙古须有北方政治中心。", process: "1403年（永乐元年）正月，诏改北平府为北京，二月设行在六部、都察院，徙南京及浙江诸富民、工匠万人实之，1406年六月诏建宫殿。", impact: "北京自此成为明代政治中心，「天子守边」的格局决定了此后五百年的中国都城分布。", figures: ["朱棣"], place: "北平／北京（今北京）", state: "明", sources: ["《明太宗实录》卷一〇","《明史·地理志》"], tags: ["迁都","北京"] }, related: ["cn--1421--p01"] },
  { id: "cn--1405--x01", track: "cn", year: 1405, yearApprox: false, dim: "explore", weight: 5, title: "郑和首次下西洋", summary: "六十二船、二万七千八百人出海。", detail: { background: "成祖欲宣威海外、探建文下落，并开拓朝贡贸易；时任内官监太监的郑和（马和，云南昆阳人）领命。", process: "1405年（永乐三年）六月，郑和、王景弘率舟师二万七千八百余、大船六十二号自苏州刘家港出海，历占城、爪哇、满剌加、锡兰、古里，1407年七月还。", impact: "开十五世纪世界规模最大的远洋航行，印度洋朝贡网络与中国海上贸易圈被打通。", figures: ["郑和","王景弘","朱棣"], place: "刘家港—占城—古里（印度卡利卡特）", state: "明", sources: ["《明史·郑和传》","《娄东刘家港天妃宫石刻通番事迹记》","《瀛涯胜览》"], tags: ["大航海","下西洋"] }, related: ["cn--1407--c01"] },
  { id: "cn--1406--m01", track: "cn", year: 1406, yearApprox: false, dim: "military", weight: 3, title: "明军八路征安南", summary: "张辅、沐晟八十万深入，俘胡氏。", detail: { background: "1400年黎季犛夺陈氏位、杀使臣，并侵澜沧、占城；成祖遣使谕责无应。", process: "1406年（永乐四年）七月命成国公朱能率师，能道卒，新城侯张辅继为前锋，与沐晟分道，号步骑八十万，十二月入其境，1407年五月俘黎季犛、胡苍至京师。", impact: "安南被并入明版图二十余年，其后用兵与财政负担成为永乐朝的重大消耗。", figures: ["张辅","沐晟","黎季犛","朱棣"], place: "安南（今越南北部）", state: "明／胡朝", sources: ["《明史·安南传》","《明太宗实录》卷五八","《大越史记全书》"], tags: ["安南用兵","永乐"] }, related: [] },
  { id: "cn--1407--c01", track: "cn", year: 1407, yearApprox: false, dim: "culture", weight: 5, title: "《永乐大典》编纂成书", summary: "二万二千八百七十七卷，一万一千余册。", detail: { background: "1403年七月命解缙等纂《文献大成》，1404年所进未善，成祖命姚广孝重纂。", process: "1407年（永乐五年）五月书成，依「用韵以统字、因字以系事」，收二万二千八百七十七卷、目录六十卷、一万一千零九十五册，约三亿七千万字，凡图书七八千种。", impact: "为世界最早、规模最大的百科全书式类书，后世辑佚赖此保存大量宋元文献。", figures: ["姚广孝","解缙","杨士奇","朱棣"], place: "应天府文渊阁", state: "明", sources: ["《明太宗实录》卷六六","《永乐大典·凡例》","张忱石《永乐大典史话》"], tags: ["类书","文献"] }, related: ["cn--1405--x01"] },
  { id: "cn--1407--i01", track: "cn", year: 1407, yearApprox: false, dim: "institution", weight: 3, title: "置交址承宣布政使司", summary: "郡县其地，设十七府四十九州。", detail: { background: "俘胡氏后，张辅等以安南本汉唐郡县，建议就地设官。", process: "1407年（永乐五年）六月置交址承宣布政使司、都指挥使司、提刑按察司，领十七府、四十九州、一百八十余县，编户置驿，征其香犀、开采金银。", impact: "越南史上第一次被纳入中国郡县二十余年，激起后黎朝起兵与明的永久退兵。", figures: ["张辅","朱棣"], place: "交址（今越南北部）", state: "明", sources: ["《明太宗实录》卷六七","《明史·地理志》","《大越史记全书·外纪》"], tags: ["郡县","安南"] }, related: ["cn--1406--m01"] },
  { id: "cn--1411--m01", track: "cn", year: 1411, yearApprox: false, dim: "military", weight: 3, title: "郑和生擒锡兰山王", summary: "以二千兵夜袭其国，俘亚烈苦奈儿。", detail: { background: "第三次下西洋（1409—1411）途中，锡兰山王亚烈苦奈儿发甲兵五万截杀明使、阻商路。", process: "1411年（永乐九年）七月，郑和识破其诈，率随从二千人迂回夜袭其城，破象兵、俘王及家属，解京师；成祖释而遣之，另立其国。", impact: "确立明在印度洋的武备威慑与朝贡秩序，锡兰、古里诸国随后入贡。", figures: ["郑和","亚烈苦奈儿"], place: "锡兰山（今斯里兰卡科特）", state: "明", sources: ["《明史·外国传·锡兰山》","《瀛涯胜览》","《明太宗实录》卷一一五"], tags: ["印度洋","下西洋"] }, related: ["cn--1405--x01"] },
  { id: "cn--1411--s01", track: "cn", year: 1411, yearApprox: false, dim: "science", weight: 4, title: "宋礼重开会通河", summary: "十六万夫疏河，南旺分水济运。", detail: { background: "元末会通河淤塞，漕运全赖海运，风险与脚费俱高。", process: "1411年（永乐九年）三月，命工部尚书宋礼发山东及徐州应天民夫十六万疏河，用汶上老人白英策，筑戴村坝遏汶水至南旺「水脊」，北济临清、南出徐州。", impact: "大运河全线复航，明廷得以免海运而长维持北京漕运，鲁西运河城镇随之繁荣。", figures: ["宋礼","白英","朱棣"], place: "南旺—临清（今山东济宁—临清）", state: "明", sources: ["《明史·河渠志》","《明太宗实录》卷一一一","《行水金鉴》"], tags: ["运河","水利工程"] }, related: ["cn--1289--s01"] },
  { id: "cn--1413--x01", track: "cn", year: 1413, yearApprox: false, dim: "explore", weight: 2, title: "陈诚出使西域", summary: "三使哈密哈烈，撰《西域番国志》。", detail: { background: "帖木儿帝国东向扩张，明须探察中路草原与西域诸国动向。", process: "1413年（永乐十一年）陈诚、李暹奉使哈密、鲁陈、火州、撒马尔罕（哈烈），凡三次往返（1413—1420），撰《西域番国志》《西域土地人物志》。", impact: "为明代陆上丝路交往与地理知识的代表作，也是研究中亚帖木儿朝的第一手汉文资料。", figures: ["陈诚","李暹","沙哈鲁"], place: "哈密—撒马尔罕", state: "明", sources: ["《西域番国志》","《明太宗实录》卷一四一","《殊域周咨录》"], tags: ["西域","陆上丝路"] }, related: [] },
  { id: "cn--1415--s01", track: "cn", year: 1415, yearApprox: false, dim: "science", weight: 3, title: "陈瑄疏清江浦漕渠", summary: "淮扬段河成，河运代海运与陆运。", detail: { background: "会通河虽通，淮南运河（邗沟、清江口）淤浅，须转般陆运。", process: "1415年（永乐十三年）平江伯陈瑄疏淮安清江浦河，置四闸以时泄蓄，通淮、泗，漕舟自江南直达北京，海运于是罢。", impact: "大运河全线贯通使淮安、清江浦成为明代漕运与造船中心，江南经济命脉北系。", figures: ["陈瑄"], place: "清江浦（今江苏淮安）", state: "明", sources: ["《明史·陈瑄传》","《明史·河渠志》","《行水金鉴》"], tags: ["漕运","运河"] }, related: ["cn--1411--s01"] },
  { id: "cn--1417--x01", track: "cn", year: 1417, yearApprox: false, dim: "explore", weight: 3, title: "郑和第五次下西洋", summary: "抵忽鲁谟斯，诸国遣使随行。", detail: { background: "前四次航程已通东南亚与印度海岸，成祖欲远驶波斯湾、阿拉伯。", process: "1417年（永乐十五年）冬，郑和率船队再下西洋，历占城、满剌加、锡兰山、柯枝、古里、忽鲁谟斯、阿丹、木骨都束、卜剌哇，1419年七月还京，随行各国使臣来贡。", impact: "明朝的朝贡网络延伸至波斯湾与东非海岸，长颈鹿（麒麟）等异域贡物进入中国记录。", figures: ["郑和","朱棣"], place: "忽鲁谟斯（今霍尔木兹）—东非", state: "明", sources: ["《瀛涯胜览》","《明史·外国传》","《星槎胜览》"], tags: ["下西洋","朝贡贸易"] }, related: ["cn--1405--x01"] },
  { id: "cn--1420--a01", track: "cn", year: 1420, yearApprox: false, dim: "art", weight: 4, title: "北京紫禁城落成", summary: "役工数十万，八千七百余间房舍落成。", detail: { background: "1406年六月诏建北京宫殿，湖广、蜀、黔采大木，苏州烧砖，役工匠军士数十万。", process: "1420年（永乐十八年）十二月紫禁城基本落成，占地约七十二万平方米，殿宇七百八十余座、房八千七百余间，以奉天、华盖、谨身三大殿为核心。", impact: "成为此后五百年中国皇权的空间象征，今故宫为世界现存最大木构宫殿建筑群。", figures: ["朱棣","蒯祥","蔡信"], place: "北京（今故宫博物院）", state: "明", sources: ["《明太宗实录》卷二三〇","《日下旧闻考》卷三四","单士元《故宫史话》"], tags: ["建筑","紫禁城"] }, related: ["cn--1403--p01"] },
  { id: "cn--1421--d01", track: "cn", year: 1421, yearApprox: false, dim: "disaster", weight: 2, title: "北京三大殿雷火", summary: "新宫三月被焚，迁都之议重起。", detail: { background: "迁都甫成，朝臣多有「宫阙未宜速就」之论，北方民力疲于役。", process: "1421年（永乐十九年）四月，奉天、华盖、谨身三殿灾于雷火，焚毁殆尽；秘书郎萧仪以言迁都非便下狱死，帝寻自为文痛省。", impact: "工程与财政被迫收缩，仁宗即位后一度停北京营造并议还都南京。", figures: ["萧仪","朱棣"], place: "北京奉天殿", state: "明", sources: ["《明史·五行志》","《明太宗实录》卷二三六","《明史·仁宗本纪》"], tags: ["火灾","营建争议"] }, related: ["cn--1421--p01"] },
  { id: "cn--1421--p01", track: "cn", year: 1421, yearApprox: false, dim: "politics", weight: 5, title: "明正式迁都北京", summary: "正月御奉天殿诏告，南京为留都。", detail: { background: "1403年升北京、1406年营宫殿、1411年通会通河，迁都已备条件。", process: "1421年（永乐十九年）正月，成祖御新成奉天殿，诏告天下以北京为京师，南京为留都，仍设六部、都察院与国子监，设顺天府。", impact: "中国政治中心自此固定于华北，江南财赋与北方军政的南北格局延续至今。", figures: ["朱棣"], place: "北京／南京", state: "明", sources: ["《明太宗实录》卷二三三","《明史·成祖本纪》"], tags: ["迁都","北京"] }, related: ["cn--1420--a01"] },
  { id: "cn--1424--p01", track: "cn", year: 1424, yearApprox: false, dim: "politics", weight: 3, title: "成祖崩于榆木川", summary: "第七次北征返师途中帝崩，秘不发丧。", detail: { background: "永乐二十年以后三次亲征漠北（1422、1423、1424），北元阿鲁台部屡扰边。", process: "1424年（永乐二十二年）七月，成祖班师途中崩于榆木川（今内蒙古多伦西北），张辅、金幼孜等秘不发丧，七日还京，八月太子高炽即位。", impact: "永乐扩张路线终结，仁宣之际转为守成，下西洋与北方征伐同时停止。", figures: ["朱棣","张辅","杨荣","朱高炽"], place: "榆木川—北京", state: "明", sources: ["《明仁宗实录》卷一","《明史·成祖本纪》","金幼孜《北征记》"], tags: ["永乐","皇位继承"] }, related: ["cn--1421--p01"] },
  { id: "cn--1425--p01", track: "cn", year: 1425, yearApprox: false, dim: "politics", weight: 3, title: "仁宗短促之治", summary: "在位十个月，罢采办议还南京。", detail: { background: "永乐末民力已困，太子高炽长期监国南京，倚杨士奇、杨荣。", process: "1424年八月至1425年五月仁宗在位，罢下西洋宝船采办、停云南金银场课税，赦建文旧臣家属，议还都南京，因疾暴崩而止。", impact: "开「仁宣之治」的收缩性治理，北京迁都格局由此定型（宣宗放弃南归）。", figures: ["朱高炽","杨士奇","杨荣"], place: "北京", state: "明", sources: ["《明仁宗实录》","《明史·仁宗本纪》"], tags: ["仁宣之治","政策收缩"] }, related: ["cn--1421--d01"] },
  { id: "cn--1426--m01", track: "cn", year: 1426, yearApprox: false, dim: "military", weight: 2, title: "汉王高煦乐安起兵", summary: "宣宗亲征乐安，一月而擒。", detail: { background: "高煦为成祖次子，永乐十三年就藩乐安，蓄兵万人、屡违礼制。", process: "1426年（宣德元年）八月，高煦反于乐安州，袭陷青州，遣人召京中张辅等为内应未成；宣宗亲率大军围之，十月高煦出降，寻被煨杀。", impact: "明代藩王之乱至此告终，宣宗得以专心内政与江南财赋整理。", figures: ["朱瞻基","朱高煦","张辅"], place: "乐安州（今山东惠民—广饶）", state: "明", sources: ["《明史·诸王传》","《明宣宗实录》卷二二","《明史纪事本末》卷二七"], tags: ["藩王之乱","宣德"] }, related: ["cn--1425--p01"] },
  { id: "cn--1427--m01", track: "cn", year: 1427, yearApprox: false, dim: "military", weight: 3, title: "明军昌江之败", summary: "柳升阵亡，王通弃地议和。", detail: { background: "1418年起黎利据蓝山起兵，交址明军困守城池，粮道屡绝。", process: "1427年（宣德二年）十月，明将柳升率军号十万救交址，在支棱—昌江（今越南谅山至河内郊外）中伏，柳升阵亡、所部覆没；王通退保东关，与黎利盟和，十二月明廷决计撤兵。", impact: "明朝失去安南，也放弃了以武力南扩的路线，此后专注北边与内政。", figures: ["柳升","黎利","王通","朱瞻基"], place: "昌江—东关（今河内）", state: "明／后黎", sources: ["《明史·安南传》","《大越史记全书·黎太祖实录》","《明宣宗实录》卷三四"], tags: ["安南","撤军"] }, related: ["cn--1407--i01"] },
  { id: "cn--1428--p01", track: "cn", year: 1428, yearApprox: false, dim: "politics", weight: 3, title: "明封黎利为安南国王", summary: "罢交址布政司，承认其自立。", detail: { background: "黎利立陈暠为傀儡而请和，明廷以抚代剿，杨士奇、杨荣主弃地。", process: "1428年（宣德三年）黎利夺位自立，1431—1433年明遣使册封权署安南国事，正式罢交址布政使司，恢复朝贡关系。", impact: "明朝疆域退至今广西云南一线，中越宗藩而不郡县的格局延续至19世纪。", figures: ["黎利","杨士奇","朱瞻基"], place: "东关（今河内）—北京", state: "明／安南", sources: ["《明史·安南传》","《明宣宗实录》","《大越史记全书》"], tags: ["宗藩","撤制"] }, related: ["cn--1427--m01"] },
  { id: "cn--1430--x01", track: "cn", year: 1430, yearApprox: false, dim: "explore", weight: 3, title: "郑和第七次下西洋", summary: "宣德六年开洋，遍历二十余国。", detail: { background: "宣宗以西洋诸国多有未附者，命已六十余岁的郑和复使。", process: "1430年（宣德五年）六月命郑和、王景弘率官校将士二万七千五百余、船六十三号，1431年正月自太仓刘家港开洋，历占城、满剌加、锡兰、古里、忽鲁谟斯、阿丹、天方诸国。", impact: "这是明代大规模官方远洋行动的最后一次，此后官方海船退出印度洋。", figures: ["郑和","王景弘","朱瞻基"], place: "刘家港—天方（麦加）", state: "明", sources: ["《明史·郑和传》","《瀛涯胜览》","《西洋朝贡典录》"], tags: ["下西洋","航海"] }, related: ["cn--1405--x01"] },
  { id: "cn--1432--x01", track: "cn", year: 1432, yearApprox: false, dim: "explore", weight: 2, title: "亦失哈再巡奴儿干", summary: "率船入黑龙江，永宁寺立碑宣抚。", detail: { background: "明在黑龙江下游设奴儿干都司，需以宣慰使巡抚女真、吉里迷诸部。", process: "1432年（宣德七年）亦失哈奉敕再至特林（黑龙江下游），重修永宁寺，次年立《重建永宁寺记》碑，招抚苦夷（库页岛）诸部贡貂。", impact: "永宁寺二碑是明代经略黑龙江下游与库页岛的重要实物证据。", figures: ["亦失哈"], place: "特林（黑龙江下游）", state: "明", sources: ["《敕修永宁寺记》《重建永宁寺记》碑","《明宣宗实录》卷九〇"], tags: ["东北","奴儿干都司"] }, related: [] },
  { id: "cn--1433--x02", track: "cn", year: 1433, yearApprox: true, dim: "explore", weight: 2, title: "郑和卒于归程", summary: "第七次返航途中病逝，南京有衣冠冢。", detail: { background: "第七次远航历三年余，船队于1433年夏自古里（今印度卡利卡特）返航。", process: "郑和约1433年（宣德八年）卒，明人记其终处一说在古里海上；南京牛首山现存其后世认定的墓与衣冠冢，其事迹多凭碑刻与地方文献。", impact: "郑和之死标志官方下西洋时代结束，成化间刘大夏毁档之说成为后世长期议论的话题。", figures: ["郑和"], place: "古里—南京", state: "明", sources: ["《通番事迹之记》碑","《明史·郑和传》","郑一钧《论郑和下西洋》"], tags: ["下西洋","人物"] }, related: ["cn--1430--x01"] },
  { id: "cn--1435--p01", track: "cn", year: 1435, yearApprox: false, dim: "politics", weight: 3, title: "英宗嗣位太皇太后听政", summary: "九岁登极，三杨与张太后维系朝局。", detail: { background: "宣德十年正月宣宗崩，皇太子朱祁镇九岁即位。", process: "1435年正月英宗即位，尊皇太后孙氏、张氏，张太后倚重杨士奇、杨荣、杨溥「三杨」，王振以教官侍内廷渐用事。", impact: "永乐—宣德积累的改革期结束，宦官与勋贵开始侵夺文官体制。", figures: ["朱祁镇","张太后","杨士奇","王振"], place: "北京", state: "明", sources: ["《明英宗实录》卷一二","《明史·英宗前纪》","《明史·杨士奇传》"], tags: ["幼主","三杨"] }, related: [] },
  { id: "cn--1439--p01", track: "cn", year: 1439, yearApprox: false, dim: "politics", weight: 2, title: "也先继长瓦剌", summary: "袭父位兼并诸部，贡使数千人入京。", detail: { background: "马哈木、脱欢父子先后受明封宁顺王、贤义王；1439年脱欢死。", process: "1439年（正统四年）也先承袭父位，先攻杀阿鲁台、立脱脱不花为可汗而自掌实权，控有漠西，屡遣数千人之贡使入京师求赏。", impact: "瓦剌成为明北边最大威胁，1449年土木堡之变即由此而起。", figures: ["也先","脱欢","脱脱不花"], place: "漠西瓦剌（今新疆北部—蒙古西部）", state: "明／瓦剌", sources: ["《明英宗实录》卷五六","《明史·瓦剌传》","《蒙古源流》"], tags: ["瓦剌","北边"] }, related: [] },
  { id: "cn--1444--i01", track: "cn", year: 1444, yearApprox: false, dim: "institution", weight: 2, title: "明设十二团营", summary: "选三大营精兵十万，合营训练。", detail: { background: "京军五军、三千、神机三大营久无战事，番上杂役、士不习战。", process: "1444年（正统九年）选三大营精兵十万，分为十二团建置，称「团营」，由石亨、于谦等提督操练，遇警则合营出战。", impact: "京营兵制为之一变，土木之败后团营损失惨重，于谦重建兵制即在此基础上。", figures: ["石亨","于谦","朱祁镇"], place: "北京诸营", state: "明", sources: ["《明史·兵志》","《明英宗实录》卷一二二","《于谦集》"], tags: ["军制","京营"] }, related: [] },
  { id: "cn--1449--m01", track: "cn", year: 1449, yearApprox: false, dim: "military", weight: 5, title: "土木堡之变英宗被俘", summary: "亲征瓦剌全军覆没，帝陷也先营。", detail: { background: "1449年七月也先分路大举入寇，王振劝帝亲征，命英国公张辅等从，仓促集兵号五十万。", process: "八月至宣府、大同，明军疲惫回撤，十三日被围于土木堡（今河北怀来东），绝水两日；十五日也先纵骑冲阵，张辅、邝埜、王佐等死难，英宗被俘，王振死于军中。", impact: "明初积累的京军精锐与勋贵集团一战俱尽，北守南防格局由此确立，明代战略由攻势转守。", figures: ["朱祁镇","也先","王振","张辅","邝埜"], place: "土木堡（今河北怀来）", state: "明／瓦剌", sources: ["《明史·英宗前纪》","《明史纪事本末》卷二九","《北征事迹》"], tags: ["土木之变","明蒙战争"] }, related: ["cn--1449--m02"] },
  { id: "cn--1449--m02", track: "cn", year: 1449, yearApprox: false, dim: "military", weight: 4, title: "于谦守北京德胜门", summary: "列阵九门之外，火器击杀也先弟。", detail: { background: "土木败后京师兵不满十万，朝议南迁，兵部侍郎于谦力主固守，迎郕王即位。", process: "1449年十月十一，也先挟上皇至北京，明军列阵九门之外而闭门，于谦总五军；德胜门以神机营伏空房发火器，杀其弟孛罗、平章卯那孩，也先退，十五日撤围北走。", impact: "北京得保使明朝免于南迁命运，火器与城防体系的价值被制度化，勋贵文官格局重排。", figures: ["于谦","石亨","也先","朱祁钰"], place: "北京九门（德胜门）", state: "明", sources: ["《明史·于谦传》","《明英宗实录》卷一八七","《忠节录》"], tags: ["北京保卫战","火器"] }, related: ["cn--1449--m01"] },
  { id: "cn--1449--p01", track: "cn", year: 1449, yearApprox: false, dim: "politics", weight: 3, title: "郕王即位改元景泰", summary: "九月立景泰帝，尊上皇为太上皇。", detail: { background: "国不可一日无君，太后从于谦等议，八月二十九郕王监国。", process: "1449年九月六日朱祁钰即皇帝位，以子见济为皇太子；上皇英宗在瓦剌营中被礼待而未遣归。", impact: "明代出现两位皇帝并存的非常局面，为1457年夺门之变埋下伏笔。", figures: ["朱祁钰","孙太后","于谦"], place: "北京", state: "明", sources: ["《明史·景帝纪》","《明英宗实录》附《景泰实录》"], tags: ["景泰","皇位继承"] }, related: ["cn--1449--m01"] },
  { id: "cn--1450--p01", track: "cn", year: 1450, yearApprox: false, dim: "politics", weight: 3, title: "上皇还京幽居南宫", summary: "也先释归，景泰帝锁南宫门。", detail: { background: "也先以奇货无利可居、明守御已固且互市受阻，乃议释还。", process: "1450年（景泰元年）八月，英宗自紫荆关还京，见于东安门，遂幽居南宫，锦衣卫监察出入、熔铁固锁其门；景泰三年废汪皇后，更立子见济为太子。", impact: "南宫幽禁七年成为1457年夺门之变的政治资本，明代皇室内斗再度爆发。", figures: ["朱祁镇","朱祁钰","汪氏"], place: "北京南宫", state: "明", sources: ["《明英宗实录》卷二二九","《明史·英宗后纪》","《朝鲜王朝实录》"], tags: ["南宫幽禁","皇位之争"] }, related: ["cn--1449--p01"] },
  { id: "cn--1457--p01", track: "cn", year: 1457, yearApprox: false, dim: "politics", weight: 4, title: "夺门之变与于谦之死", summary: "石亨等复英宗位，于谦弃市。", detail: { background: "1457正月景帝病重，石亨、徐有贞、曹吉祥与内官密谋迎上皇复位。", process: "1457年（景泰八年）正月十七日夜破南宫门，英宗登奉天殿复辟，改元天顺；以「迎立外藩」罪下于谦、范广于狱，二月二十一日于谦弃市，籍其家。", impact: "北京保卫战的功臣被杀，朝廷赏罚与军功评价标准扭曲，文官集团元气大伤。", figures: ["朱祁镇","石亨","徐有贞","于谦","曹吉祥"], place: "北京", state: "明", sources: ["《明史·于谦传》","《明英宗实录》卷二七一","《明史纪事本末》卷三八"], tags: ["夺门之变","政治清洗"] }, related: ["cn--1449--m02"] },
  { id: "cn--1461--m01", track: "cn", year: 1461, yearApprox: false, dim: "military", weight: 1, title: "曹钦之乱", summary: "达官将领夜起，劫大臣攻宫门。", detail: { background: "夺门功臣曹吉祥与族子曹钦典掌京营，英宗渐削其权并清核夺门冒功者。", process: "1461年（天顺五年）七月，曹钦率所部达官夜起，劫大学士李贤不遂，其党杀参将杨青于朝房，攻东安门、长安门，京师戒严；事败曹钦投井死，曹吉祥凌迟。", impact: "蒙古达官军事集团自此退出京营中枢，武勋与宦官干政的形态转入新阶段。", figures: ["曹钦","曹吉祥","朱祁镇"], place: "北京东安门", state: "明", sources: ["《明史·曹吉祥传》","《明英宗实录》卷六七八"], tags: ["京营兵变","天顺"] }, related: ["cn--1457--p01"] },
  { id: "cn--1464--p01", track: "cn", year: 1464, yearApprox: false, dim: "politics", weight: 2, title: "宪宗即位与近习用事", summary: "英宗崩，帝宠僧道方士，传奉官骤增。", detail: { background: "1464年二月英宗崩，遗诏罢妃嫔殉葬；皇太子朱见深即位。", process: "1464年（天顺八年）九月宪宗即位，以万贵妃、太监梁芳、僧继晓等近习用事，传奉官不经吏部铨选而授职者日增。", impact: "明代「传奉升授」与幸进之弊自宪宗朝开始，成为成化朝财政与吏治痼疾。", figures: ["朱见深","万贵妃","梁芳"], place: "北京", state: "明", sources: ["《明史·宪宗本纪》","《明宪宗实录》卷一","《万历野获编》"], tags: ["成化","近幸"] }, related: [] },
  { id: "cn--1465--m01", track: "cn", year: 1465, yearApprox: false, dim: "military", weight: 3, title: "刘通起事荆襄山内", summary: "流民拥汉王，建元德盛。", detail: { background: "正统以来川、湖、陕流民入荆襄山区棚居垦种，官府封禁而依者不绝，搜遣之际怨声载道。", process: "1465年（成化元年）三月，盐徒刘通（刘千斤）与石和尚（石龙）率流民起于襄阳府房县，称汉王、建元德盛，众数万，陷大城、竹山、上津等地。", impact: "荆襄流民问题成为明代中期人口流动与山地开发的集中爆发点，兵事延续至1476年。", figures: ["刘通","石龙","朱见深"], place: "房县、竹山（今湖北十堰—襄阳西部）", state: "明", sources: ["《明宪宗实录》卷二六","《明史纪事本末》卷三八","《明史·项忠传》"], tags: ["荆襄流民","棚民"] }, related: ["cn--1476--i01"] },
  { id: "cn--1467--m01", track: "cn", year: 1467, yearApprox: false, dim: "military", weight: 3, title: "明与朝鲜合击建州", summary: "董山被诛，李满住死于乱军。", detail: { background: "建州女真内迁后屡与辽东摩擦，1466年明招建州左卫董山入朝，中途处死之，诸部愤而入寇。", process: "1467年（成化三年）九月，明命朱永、王浚率军，与朝鲜军会攻建州，破其寨，杀首领李满住父子，焚其庐舍；1468、1479年明军再入搜剿。", impact: "建州女真元气大伤但未被消灭，一百五十年后其后裔以同一地区建立后金。", figures: ["董山","李满住","朱永"], place: "建州（今辽宁新宾—桓仁一带）", state: "明／建州女真", sources: ["《明宪宗实录》卷四七","《朝鲜王朝实录·睿宗实录》","《满洲实录》卷一"], tags: ["建州女真","辽东"] }, related: [] },
  { id: "cn--1471--e01", track: "cn", year: 1471, yearApprox: false, dim: "economy", weight: 2, title: "项忠再平流民与遣返", summary: "剿抚并用，遣返六十二万口。", detail: { background: "1470年刘通被俘遇害，1471年其党李胡子等复起，襄阳一带流民聚众不已。", process: "1471年（成化七年）项忠以左都御史总督军务进剿，并强制遣返；明奏报遣还流民六十二万三千余口，道死相枕，而入山者仍不止。", impact: "强制遣返未能解决山地人口压力，为1476年设郧阳府抚治铺路，是明代流民政策的转折点。", figures: ["项忠","李胡子"], place: "郧阳、襄阳（今湖北十堰—襄阳）", state: "明", sources: ["《明史·项忠传》","《明宪宗实录》卷一〇二"], tags: ["流民","遣返"] }, related: ["cn--1465--m01"] },
  { id: "cn--1476--i01", track: "cn", year: 1476, yearApprox: false, dim: "institution", weight: 3, title: "设郧阳府抚治流民", summary: "原杰安辑山地，许附籍并设巡抚。", detail: { background: "荆襄山地区流民聚众且封禁无效，明廷遣左都御史原杰往勘。", process: "1476年（成化十二年）置郧阳府，领竹山、郧西等县，并设湖广郧阳巡抚与行都司，听流民附籍；据原杰奏报安辑得户十二万九千有奇。", impact: "由「封禁」改「附籍」，标志明代对流民与山地开发的政策转向，山区经济随之成型。", figures: ["原杰","朱见深"], place: "郧阳（今湖北十堰郧阳区）", state: "明", sources: ["《明史·原杰传》","《明宪宗实录》卷一六〇","《郧阳府志》"], tags: ["流民附籍","行政区划"] }, related: ["cn--1465--m01"] },
  { id: "cn--1477--i01", track: "cn", year: 1477, yearApprox: false, dim: "institution", weight: 3, title: "设西厂命汪直提督", summary: "校尉四出，京师民间斗殴皆被缉。", detail: { background: "1477年正月有妖言惑众、夜叩宫门之事，宪宗恶之，欲广耳目。", process: "1477年（成化十三年）二月设西厂于西安门内，以太监汪直提督，校尉由数百增至数千人，逻事京师及各省，与东厂、锦衣卫并立。", impact: "明代特务机构叠床架屋达到顶点，士大夫与地方的紧张气氛从此制度化。", figures: ["汪直","朱见深"], place: "北京西安门内", state: "明", sources: ["《明史·汪直传》","《明宪宗实录》卷一六〇","《西园闻见录》"], tags: ["厂卫","特务"] }, related: ["cn--1382--i01"] },
  { id: "cn--1482--p01", track: "cn", year: 1482, yearApprox: false, dim: "politics", weight: 1, title: "罢西厂斥汪直", summary: "科道交劾，宪宗两难而终罢之。", detail: { background: "汪直屡兴大狱、出镇大同，边军与士夫怨声日积，项忠、马文升等相继论劾。", process: "1482年（成化十八年）三月罢西厂，汪直降奉御、寻发南京孝陵卫，其党王越等去职。", impact: "罢西厂是成化朝士大夫有限度约束特务权力的成功案例，但厂卫体制未受根本触动。", figures: ["汪直","项忠","朱见深"], place: "北京", state: "明", sources: ["《明史·汪直传》","《明宪宗实录》卷二二六"], tags: ["西厂","言官"] }, related: ["cn--1477--i01"] },
  { id: "cn--1487--c01", track: "cn", year: 1487, yearApprox: true, dim: "culture", weight: 3, title: "八股程式于成化间定型", summary: "破题、起股、束股结构固定为常格。", detail: { background: "明初经义取士以偶语、散文并用；成化后士子渐尚排偶。", process: "约15世纪70—80年代（成化、弘治间），乡会试经义题形成破题、承题、起讲、起股、中股、后股、束股的定格，答题须「代圣贤立言」。", impact: "八股定型使科举考试可标准化，也深刻塑造了明清士人的思维方式与文体。", figures: ["丘濬"], place: "北京及两京贡院", state: "明", sources: ["《明史·选举志》","梁章钜《制义科琐记》","商衍鎏《清代科举考试述录》"], tags: ["科举","八股文"] }, related: ["cn--1487--c02"] },
  { id: "cn--1487--c02", track: "cn", year: 1487, yearApprox: false, dim: "culture", weight: 2, title: "丘濬成《大学衍义补》", summary: "以经世之学论财用与币制。", detail: { background: "丘濬（1421—1495），广东琼山人，官至文渊阁大学士，以经世实用自任。", process: "1487年（成化二十三年）上《大学衍义补》一百六十二卷，补真德秀《大学衍义》之缺，详论「丰财」「资国用」，主张以银为币、听民铸钱。", impact: "明代中期最具系统性的经世文献，其货币论被后世视为中国早期白银货币化理论。", figures: ["丘濬"], place: "北京", state: "明", sources: ["《大学衍义补》卷一二—一三","《明史·丘濬传》","《琼山县志》"], tags: ["经世之学","货币理论"] }, related: ["cn--1490--e01"] },
  { id: "cn--1487--p01", track: "cn", year: 1487, yearApprox: false, dim: "politics", weight: 3, title: "孝宗嗣位弘治更化", summary: "罢传奉官、斥方士，召用正人。", detail: { background: "1487年八月宪宗崩，九月皇太子朱祐樘即位，是为孝宗。", process: "1487—1488年间，罢传奉升授官数百人，遣僧继晓等伏诛，任用徐溥、刘健、谢迁，命刘大夏等清理军籍，开经筵日讲。", impact: "史称「弘治中兴」，明中叶吏治与财政一度好转；亦被视为明代最接近儒家理想之治世。", figures: ["朱祐樘","刘健","徐溥","李东阳"], place: "北京", state: "明", sources: ["《明史·孝宗本纪》","《明孝宗实录》卷一","《弘治实录》"], tags: ["弘治中兴","吏治"] }, related: ["cn--1464--p01"] },
  { id: "cn--1488--c01", track: "cn", year: 1488, yearApprox: true, dim: "culture", weight: 3, title: "陈献章创江门之学", summary: "以自然为宗，主静坐体认本心。", detail: { background: "陈献章（白沙，1428—1500）师事吴与弼于江西崇仁，归而尽弃书本，静坐十年。", process: "约1480年代（成化间）其学在广东新会白沙、江门成熟，主张「静中养出端倪」「以自然为宗」，湛若水、张诩等从游；1487年前后授翰林检讨旋即辞归。", impact: "上承陆九渊、下启王阳明，标志明代心学思潮在南方兴起。", figures: ["陈献章","湛若水","吴与弼"], place: "新会白沙（今广东江门）", state: "明", sources: ["《陈献章集》","《明儒学案》卷五《白沙学案》","《明史·儒林传》"], tags: ["心学","理学"] }, related: ["cn--1508--c01"] },
  { id: "cn--1490--e01", track: "cn", year: 1490, yearApprox: true, dim: "economy", weight: 3, title: "宝钞废弛白银货币化", summary: "钞贯不值钱，赋役与物价折银。", detail: { background: "明初禁用金银、强推宝钞，无发无收，至成化、弘治间一贯钞市价不足数钱。", process: "约15世纪末（弘治间）朝廷默认钱钞不行，民间交易以银为主，田赋、均徭、里甲折银渐成定制，铜钱退处次要地位。", impact: "白银货币化重构明代财政与社会经济，使中国高度依赖日本与美洲白银输入。", figures: ["丘濬","朱祐樘"], place: "东南诸省与京师", state: "明", sources: ["《明史·食货志》","《大明会典·钞法》","万明《明代白银货币化研究》"], tags: ["白银","财政"] }, related: ["cn--1375--e01"] },
  { id: "cn--1493--s01", track: "cn", year: 1493, yearApprox: false, dim: "science", weight: 3, title: "刘大夏塞张秋决河", summary: "开月河分水，北流复归于南。", detail: { background: "1489年（弘治二年）黄河决张秋金丝山，北冲会通河、运道受阻。", process: "1491年起命刘大夏治河，役夫数万，先开月河七十里以分杀水势，1493年（弘治六年）六月决口全塞，河复东趋徐、邳入淮。", impact: "张秋之役保住漕运命脉，其「北堤南分」思路成为明代黄河治理的重要实践。", figures: ["刘大夏","朱祐樘"], place: "张秋（今山东阳谷张秋镇）", state: "明", sources: ["《明史·刘大夏传》","《明史·河渠志》","《问水集》"], tags: ["黄河","治河工程"] }, related: ["cn--1344--d01"] },
  { id: "cn--1499--f01", track: "cn", year: 1499, yearApprox: false, dim: "figure", weight: 2, title: "王守仁成进士入仕", summary: "二十八岁登第，观政工部。", detail: { background: "王守仁（1472年生，余姚人）少从娄谅问学，1492年中河南乡试。", process: "1499年（弘治十二年）举进士，观政工部，参与营建威烈侯庙之役；1504年主山东乡试，次年任兵部主事。", impact: "此后十余年他由辞章、出入佛老转向内在之学，1508年遂有龙场悟道。", figures: ["王守仁","娄谅","王华"], place: "京师／余姚（今浙江余姚）", state: "明", sources: ["《王阳明全集·年谱一》","《明史·王守仁传》"], tags: ["王阳明","科第"] }, related: ["cn--1508--c01"] },
  { id: "cn--1500--e01", track: "cn", year: 1500, yearApprox: true, dim: "economy", weight: 3, title: "江南专业市镇兴起", summary: "盛泽以绸、黄溪以绫，市肆倍于县。", detail: { background: "明中叶江南丝织、棉纺、冶铸与粮米贸易扩张，乡村聚落向专业化市镇转化。", process: "约15—16世纪，吴江盛泽镇「绫绸之聚亦且数倍于吴江一县」，黄溪、王江泾、硖石、南翔等镇各有专业市场，牙行包卖与包买商出现。", impact: "市镇网络构成江南市场体系，也为20世纪50—80年代学界关于「资本主义萌芽」的长期论争提供核心史料。", figures: ["张瀚"], place: "苏州府、松江府一带（今江苏—上海）", state: "明", sources: ["《嘉靖吴江县志》","张瀚《松窗梦语》","傅衣凌《明代江南市民经济试探》"], tags: ["市镇","资本主义萌芽论争"] }, related: ["cn--1295--s01"] },
  { id: "cn--1505--p01", track: "cn", year: 1505, yearApprox: false, dim: "politics", weight: 2, title: "武宗嗣位与边将入卫", summary: "孝宗崩，帝年少尚武，宠信内竖。", detail: { background: "1505年（弘治十八年）五月孝宗崩，皇太子朱厚照即位。", process: "1505年六月武宗立，以刘瑾、张永等「八虎」侍内，召许泰、江彬等边将入「豹房」，1506—1507年科道交章留刘健、谢迁不果。", impact: "武宗朝的逸游与近幸政治使中枢运转失序，正德年间内乱与南巡相继发生。", figures: ["朱厚照","刘瑾","刘健","谢迁"], place: "北京", state: "明", sources: ["《明武宗实录》卷一","《明史·武宗本纪》"], tags: ["正德","宦官"] }, related: ["cn--1487--p01"] },
  { id: "cn--1506--p01", track: "cn", year: 1506, yearApprox: false, dim: "politics", weight: 3, title: "刘瑾掌司礼监擅权", summary: "逐辅臣、杖言官，内廷权最盛。", detail: { background: "1506年（正德元年）十月，科道交劾马永成、刘瑾等「八虎」，武宗欲杀之，阁臣刘健、谢迁力争不果。", process: "刘瑾入掌司礼监并提督京师特务机关，矫旨逐刘健、谢迁、韩文，杨慎等伏阙哭谏被杖谪，朝士被逮者三十九人。", impact: "正德前期出现明代最严重的宦官专权局面，也是1510年宁夏之乱的直接口实。", figures: ["刘瑾","朱厚照","焦芳","杨慎"], place: "北京", state: "明", sources: ["《明史·刘瑾传》","《明武宗实录》卷二〇","《继世纪闻》"], tags: ["刘瑾","宦官专权"] }, related: ["cn--1505--p01"] },
  { id: "cn--1508--c01", track: "cn", year: 1508, yearApprox: false, dim: "culture", weight: 4, title: "龙场悟道", summary: "谪驿之中悟「圣道吾性自足」。", detail: { background: "1507年王守仁上疏救南京科道戴铣等，触怒刘瑾，廷杖四十，谪贵州龙场驿驿丞。", process: "1508年（正德三年）春至龙场（今贵州修文），无驿舍、自处洞穴，与从者仆夫共耕，日夜端居澄默，忽悟格物致知之旨，始知圣人之道不假外求。", impact: "心学由此立基，其「知行合一」在1509年贵阳书院讲出，改变明中后期思想史走向。", figures: ["王守仁","湛若水"], place: "龙场驿（今贵州贵阳修文县）", state: "明", sources: ["《王阳明全集·年谱》","《传习录》卷中","《明儒学案》卷一〇"], tags: ["心学","龙场悟道"] }, related: ["cn--1488--c01"] },
  { id: "cn--1508--p02", track: "cn", year: 1508, yearApprox: false, dim: "politics", weight: 2, title: "设内行厂刻核臣僚", summary: "刘瑾以重典绳京官，罚米充军。", detail: { background: "刘瑾惧百官不附，需有超出东西厂与锦衣卫的侦缉机关。", process: "1508年（正德三年）八月刘瑾奏设内行厂，自领之，与锦衣卫互为察访，五品以下官员多被逮治，「罚米」至数十万石者相望。", impact: "厂卫政治达到明代顶点，也激起1510年正德初的政局反弹与刘瑾覆亡。", figures: ["刘瑾","朱厚照"], place: "北京", state: "明", sources: ["《明史·刑法志》","《明武宗实录》卷四一"], tags: ["厂卫","正德"] }, related: ["cn--1506--p01"] },
  { id: "cn--1510--m01", track: "cn", year: 1510, yearApprox: false, dim: "military", weight: 3, title: "安化王之乱与刘瑾伏诛", summary: "宁夏一隅起兵，借除权阉。", detail: { background: "1510年（正德五年）四月，安化王寘鐇与宁夏诸将以「诛刘瑾」为名起兵。", process: "乱事逾月即被讨平；奉命勘狱的杨一清借太监张永入京奏对之机，历数刘瑾十七条罪，八月刘瑾被凌迟于市，抄没金银以数万计。", impact: "权阉政治被暂时打断，但宁夏、流民与南方军制问题并未随之解决。", figures: ["朱寘鐇","刘瑾","杨一清","张永"], place: "宁夏（今银川）—北京", state: "明", sources: ["《明武宗实录》卷六四","《明史·刘瑾传》","《明史纪事本末》卷四三"], tags: ["宁夏之乱","宦官"] }, related: ["cn--1508--p02"] },
  { id: "cn--1511--x01", track: "cn", year: 1511, yearApprox: false, dim: "explore", weight: 3, title: "葡萄牙人陷满剌加", summary: "马六甲易主，来告急而明未应。", detail: { background: "满剌加（马六甲）为明册封国与朝贡贸易的中转枢纽。", process: "1511年（正德六年）七月，葡萄牙印度总督阿尔布开克率舰队攻陷满剌加，焚其舟、据其城；其国遣使来告，明廷以道路阻远未应。", impact: "欧洲海权进入南海与印度洋贸易网，广东海防与走私贸易格局被改写，佛郎机之患由此而起。", figures: ["阿尔布开克"], place: "满剌加（今马六甲）", state: "明／葡萄牙", sources: ["《明史·满剌加传》","张燮《东西洋考》卷三","皮雷斯《东方志》"], tags: ["葡萄牙","马六甲"] }, related: ["cn--1517--e01"] },
  { id: "cn--1512--e01", track: "cn", year: 1512, yearApprox: false, dim: "economy", weight: 2, title: "卫所屯田大量失额", summary: "清核屯粮，诸都司减额过半。", detail: { background: "洪武、永乐以卫所屯田养兵，成化以来屯田多被军官侵占典卖。", process: "1512年（正德七年）前后户部、兵部清理天下屯田，奏报湖广、陕西、河南诸都司屯粮较原额减少三分之一至二分之一，军士逃亡十常四五。", impact: "卫所制失去经济基础，明中后期不得不以募兵与饷银替代，财政压力剧增。", figures: ["朱厚照"], place: "九边及两京卫所", state: "明", sources: ["《明史·食货志》","《明武宗实录》卷九一"], tags: ["卫所","军屯"] }, related: ["cn--1370--i01"] },
  { id: "cn--1517--e01", track: "cn", year: 1517, yearApprox: false, dim: "economy", weight: 3, title: "葡船首次通商广东", summary: "欧维士抵屯门，私市自此不绝。", detail: { background: "满剌加陷落后葡人东寻贸易口岸，广东沿海市舶已废、私舶渐盛。", process: "1517年（正德十二年）葡人别都庐、欧维士率船抵屯门，以货物易大利，请入市；1518年泊万州所，明廷始知其名而许其通商，随即有筑室立寨之渐。", impact: "欧洲势力经海路进入中国贸易圈的起点，也为三十年后的屯门之战与澳门开埠埋下因由。", figures: ["别都庐","欧维士"], place: "屯门（今广东深圳）", state: "明／葡萄牙", sources: ["《明史·佛郎机传》","《殊域周咨录》卷九","张天泽《中葡早期关系史》"], tags: ["葡萄牙","海上贸易"] }, related: ["cn--1511--x01", "cn--1521--m01"] },
  { id: "cn--1519--m01", track: "cn", year: 1519, yearApprox: false, dim: "military", weight: 4, title: "宁王之乱四十三日平", summary: "宸濠反南昌，王守仁起兵擒之。", detail: { background: "宁王朱宸濠蓄谋久，贿赂幸臣、夺江西田土，畜亡命，1519年六月闻朝廷将收其护卫。", process: "1519年（正德十四年）六月十四日起兵，杀巡抚孙燧，号众十万，东下安庆；南赣巡抚王守仁合郡县兵攻其巢，七月二十日复南昌，二十四日在樵舍火其舟，擒宸濠，前后四十三日。", impact: "一场可能分裂南方的藩王之乱速定，王守仁由此以事功证成其学，成为明代心学家的政治资本。", figures: ["王守仁","朱宸濠","孙燧"], place: "南昌—安庆（今江西—安徽）", state: "明", sources: ["《明史·宁王传》","《王阳明全集·年谱二》","《明武宗实录》卷一七八"], tags: ["藩王之乱","心学事功"] }, related: ["cn--1508--c01"] },
  { id: "cn--1521--m01", track: "cn", year: 1521, yearApprox: false, dim: "military", weight: 3, title: "屯门之役逐葡船", summary: "汪鋐围屯门，葡人弃其泊口。", detail: { background: "1517年以来葡船泊屯门私市、筑棚立寨并掠买子女，明廷屡谕不止。", process: "1521年（正德十六年）秋，广东按察使汪鋐率军围屯门，断其水泉、以火船攻其大船，葡人死者数十，旋弃屯门而去；1522年西草湾之役明军再获其船炮。", impact: "明军首次与欧洲武装海上力量交手并取胜，同时开始仿制佛郎机炮，广东海防进入火器时代。", figures: ["汪鋐"], place: "屯门—南头（今广东深圳—东莞）", state: "明／葡萄牙", sources: ["《明史·外国传·佛郎机》","汪鋐《佛郎机奏议》","《殊域周咨录》卷九"], tags: ["佛郎机","海战"] }, related: ["cn--1517--e01"] },
  { id: "cn--1521--p01", track: "cn", year: 1521, yearApprox: false, dim: "politics", weight: 4, title: "世宗入继与大礼议起", summary: "武宗无嗣，十五岁的兴献王子即位。", detail: { background: "1521年三月十四武宗崩于豹房，无子；张太后与首辅杨廷和定策，迎湖广安陆的兴献王长子朱厚熜。", process: "1521年四月二十二日世宗即位，随即以生父称「皇考」还是「皇叔考」爆发礼制之争，杨廷和等于1524年去位，史称大礼议。", impact: "一场关于名分的争论演变为皇权对文官集团的重建，嘉靖朝二十余年的专制风格由此形成。", figures: ["朱厚熜","杨廷和","张太后","张璁"], place: "北京—安陆（今湖北钟祥）", state: "明", sources: ["《明史·世宗本纪》","《明史·杨廷和传》","《明伦大典》"], tags: ["大礼议","皇位继承"] }, related: ["cn--1524--p01"] },
  { id: "cn--1523--x01", track: "cn", year: 1523, yearApprox: false, dim: "explore", weight: 3, title: "宁波争贡之乱", summary: "日本两使争勘合，杀官掠浙东。", detail: { background: "明以勘合验日本贡船，细川氏与大内氏各持正德、弘治勘合，1523年同时抵宁波。", process: "1523年（嘉靖二年）四月，大内氏使宗设谦怱攻击细川氏使宋素卿，追杀至绍兴城下，焚劫宁绍间，杀明巡检与官属，浙东大扰。", impact: "明廷以此罢废市舶、加严海禁，合法贸易被堵死，倭乱与走私集团在东南沿海迅速坐大。", figures: ["宗设谦怱","宋素卿"], place: "宁波市舶司（今浙江宁波）", state: "明／日本", sources: ["《明史·日本传》","《明世宗实录》卷二四","《藩祸考》"], tags: ["争贡","海禁"] }, related: ["cn--1374--e01"] },
  { id: "cn--1524--p01", track: "cn", year: 1524, yearApprox: false, dim: "politics", weight: 4, title: "左顺门廷杖血案", summary: "二百余员伏阙哭谏，杖死十六人。", detail: { background: "大礼议中群臣坚持为孝宗后、以武宗为兄，世宗欲尊本生父为皇考。", process: "1524年（嘉靖三年）七月，五品以下官二百五十余人伏左顺门哭谏，帝怒，逮系一百三十四人，再廷杖，死者十六人（一说十七人），杨慎谪云南永昌。", impact: "明代士大夫以礼制约束皇权的努力遭到挫败，廷杖成为嘉靖朝的常规威慑手段。", figures: ["朱厚熜","杨慎","马理","王时柯"], place: "北京左顺门", state: "明", sources: ["《明史·世宗本纪》","《明史·杨慎传》","《明世宗实录》卷四〇"], tags: ["大礼议","廷杖"] }, related: ["cn--1521--p01"] },
  { id: "cn--1529--f01", track: "cn", year: 1529, yearApprox: false, dim: "figure", weight: 4, title: "王守仁卒于青龙铺", summary: "征思田还舟中疾笃，遗言此心光明。", detail: { background: "1527—1528年王守仁总督两广，平思恩、田州之乱与断藤峡，肺病加剧。", process: "1529年（嘉靖七年十一月）归舟次大庾青龙铺（今江西大余）卒，年五十七；门人问遗言，曰「此心光明，亦复何言」；死后因桂萼劾其「伪学」被恤典削夺。", impact: "心学宗师之死未使其学衰，反而在16世纪中叶经泰州学派与讲会运动扩散至民间。", figures: ["王守仁","钱德洪","王艮"], place: "大庾青龙铺（今江西大余）", state: "明", sources: ["《王阳明全集·年谱下》","《明史·王守仁传》","《明儒学案》卷一〇"], tags: ["王阳明","心学"] }, related: ["cn--1508--c01"] },
  { id: "cn--1530--c01", track: "cn", year: 1530, yearApprox: true, dim: "culture", weight: 3, title: "王艮创泰州学派", summary: "以百姓日用为道，庶人讲学成风。", detail: { background: "王艮（1483—1541）出身安丰盐丁，木工之子，1519年入门王守仁门下。", process: "约1530年前后归乡立化民成俗之学，主张「百姓日用即道」「安身立本」，着布衣、驾小车，门徒多樵夫陶匠，其学称泰州学派。", impact: "儒学下移至庶民阶层，开明末颜钧、何心隐、李贽一系的异端色彩讲学传统。", figures: ["王艮","王襞","王守仁"], place: "安丰场—泰州（今江苏东台—泰州）", state: "明", sources: ["《王心斋先生遗集》","《明儒学案》卷三二《泰州学案》","《明史·儒林传》"], tags: ["泰州学派","庶民儒学"] }, related: ["cn--1529--f01"] },
  { id: "cn--1542--p01", track: "cn", year: 1542, yearApprox: false, dim: "politics", weight: 2, title: "壬寅宫变", summary: "十六名宫女谋缢世宗不果。", detail: { background: "世宗久居西苑炼丹，课责严酷，选幼女入宫习礼，宫人苦于役。", process: "1542年（嘉靖二十一年）十月二十一日夜，杨金英等宫女以丝带绞帝而误为死结，事觉，十六人皆凌迟于市，曹端妃、王宁嫔同日死。", impact: "此后世宗二十余年不视朝、专意斋醮，西苑修玄与内阁密疏政治成为嘉靖后期特征。", figures: ["朱厚熜","杨金英","曹端妃"], place: "北京宫城永寿宫", state: "明", sources: ["《明史·后妃传》","《明世宗实录》卷二六六","《万历野获编》"], tags: ["宫变","嘉靖"] }, related: ["cn--1547--p01"] },
  { id: "cn--1547--p01", track: "cn", year: 1547, yearApprox: false, dim: "politics", weight: 2, title: "朱纨严浙江福建海禁", summary: "刷私舶、编十家牌，海商豪户怨之。", detail: { background: "双屿港自十五世纪末成中日波斯走私巢穴，闽浙缙绅多与其分利。", process: "1547年（嘉靖二十六年）七月，朱纨以右佥都御史巡抚浙江、兼理福建海防，革渡船、严保甲、禁通番，所按问无虚日，闽浙语曰「若不去水，湖且为盗区」。", impact: "海禁执法触犯东南士绅与海商利益，激起此后二十年倭乱中的官方与地方互斗。", figures: ["朱纨"], place: "宁波—漳州—泉州", state: "明", sources: ["《明史·朱纨传》","《明世宗实录》卷三二九","《虔台续志》"], tags: ["海禁","双屿港"] }, related: ["cn--1523--x01"] },
  { id: "cn--1548--p01", track: "cn", year: 1548, yearApprox: false, dim: "politics", weight: 3, title: "焚毁双屿港", summary: "卢镗袭破海上市镇，沉其货物。", detail: { background: "双屿港（今宁波六横岛附近）中外商舶数千家，筑室立市、私市连年，号倭乱之根本。", process: "1548年（嘉靖二十七年）四月，都指挥使卢镗率舟师乘潮入港，焚其屋庐船货，沉木石填塞港道，逐出葡萄牙人；被杀与俘者以数千计。", impact: "明廷摧毁了东亚最大的走私中心，但走私随即转移至月港、烈港与日本平户，海商与倭寇合流。", figures: ["朱纨","卢镗"], place: "双屿港（今浙江宁波六横附近）", state: "明", sources: ["《明史·朱纨传》","《筹海图编》卷一","《殊域周咨录》"], tags: ["双屿","走私贸易"] }, related: ["cn--1547--p01"] },
  { id: "cn--1548--s01", track: "cn", year: 1548, yearApprox: false, dim: "science", weight: 3, title: "明军始仿鸟嘴铳", summary: "得自东南战场的火绳枪成制式装备。", detail: { background: "倭寇以鸟嘴铳（火绳枪）为利器，命中率高而装药慢。", process: "嘉靖二十七年前后，明军在东南沿海缴获鸟铳及其造法，戚继光编铳手入鸳鸯阵、批量仿造以装备京营与边军，万历间赵士桢复著《神器谱》重订图说。", impact: "火绳枪在明军中制式化，使东亚火器技术与欧洲的差距在这一时期明显缩小。", figures: ["戚继光","赵士桢"], place: "浙江—福建沿海", state: "明", sources: ["《明史·兵志》","戚继光《纪效新书·鸟铳解》","《神器谱》"], tags: ["火器","鸟铳"] }, related: ["cn--1521--m01"] },
  { id: "cn--1549--p02", track: "cn", year: 1549, yearApprox: false, dim: "politics", weight: 1, title: "朱纨被劾死", summary: "闽浙言官交攻，按治遂饮鸩。", detail: { background: "朱纨执法不避势家，闽浙籍御史与给事中交章论其「专杀」冒功。", process: "1549年（嘉靖二十八年）朝廷遣给事中杜汝贞按问，朱纨被劾去职、逮京究问，旋饮鸩死；其所立海禁章程随之罢废。", impact: "东南沿海的整肃失败，此后至十六世纪六十年代倭乱达到顶峰，明廷付出更大代价重设海防。", figures: ["朱纨","杜汝贞"], place: "杭州—福州（今浙江—福建）", state: "明", sources: ["《明史·朱纨传》","《明世宗实录》卷三五八"], tags: ["海禁","党议"] }, related: ["cn--1548--p01"] },
  { id: "cn--1550--m01", track: "cn", year: 1550, yearApprox: false, dim: "military", weight: 4, title: "庚戌之变俺答薄京师", summary: "古北口入寇，掠京畿三日而去。", detail: { background: "俺答屡求贡市不得，边备因东南倭事与京营空虚而废弛。", process: "1550年（嘉靖二十九年）八月，俺答自古北口入，焚掠密云、怀柔、顺义至通州，薄京师城下，纵掠二三日西转而去；兵部尚书丁汝夔不敢战，严嵩主抚。", impact: "暴露京营无可战之兵，明廷此后加大蓟镇防务、增筑边墙，北方军费成倍上升。", figures: ["俺答","丁汝夔","严嵩","朱厚熜"], place: "古北口—北京城下", state: "明／蒙古", sources: ["《明史·鞑靼传》","《明世宗实录》卷三六六","《北虏始末》"], tags: ["庚戌之变","九边"] }, related: ["cn--1571--p01"] },
  { id: "cn--1551--e01", track: "cn", year: 1551, yearApprox: false, dim: "economy", weight: 2, title: "宣府大同时开马市", summary: "明蒙短暂互市，旋以言官请罢。", detail: { background: "庚戌之变后俺答复请贡市，朝议不许开边衅而可权宜交易。", process: "1551年（嘉靖三十年）二月开大同、宣府马市，以绸布、锅釜易其马；俺答求久市并增市口，同年五月廷议罢之，互市中断近二十年。", impact: "明代蒙汉贸易的制度化努力失败，双方以兵戎相见的成本远高于互市，边境残破延续。", figures: ["俺答","朱厚熜"], place: "大同—宣府（今山西—河北张家口）", state: "明／蒙古", sources: ["《明史·鞑靼传》","《明世宗实录》卷三七二","《九边图说》"], tags: ["马市","边贸"] }, related: ["cn--1571--p01"] },
  { id: "cn--1555--m01", track: "cn", year: 1555, yearApprox: false, dim: "military", weight: 3, title: "倭乱极于江浙", summary: "徐海陈东合众入犯，东南数十州残破。", detail: { background: "双屿焚后海商武装转入倭伍，王直据徽王岛，徐海、陈东、麻叶分股。", process: "1555年（嘉靖三十四年）倭寇分股流劫浙江、南直隶、福建、广东，陷州县数十，杀掠官吏军民以万计；徐海、陈东合众犯嘉兴、湖州，浙中大震。", impact: "明廷被迫设总督、调土兵狼兵，东南财赋重心转为军事区，倭乱成为明代最大的内部治安危机。", figures: ["徐海","陈东","王直","胡宗宪"], place: "浙江—南直隶", state: "明", sources: ["《明史·日本传》","《筹海图编》卷九","《嘉靖东南平倭通录》"], tags: ["倭寇","东南"] }, related: ["cn--1548--p01"] },
  { id: "cn--1556--d01", track: "cn", year: 1556, yearApprox: false, dim: "disaster", weight: 4, title: "关中大地震", summary: "嘉靖三十四年华县渭南地震极烈。", detail: { background: "汾渭地堑与鄂尔多斯地块边缘断裂活动频繁，关中居民多居黄土窑洞。", process: "1556年1月23日（嘉靖三十四年十二月十一日酉时）华县、渭南一带地震，估计震级8—8.5级，山崩壅河、窑洞塌覆，《明史·五行志》载奏报死者八十三万；现代地震学者据州县人口重推死亡为十余万至数十万不等。", impact: "被认为是世界史上死亡人数最多的地震之一；灾后推行改窑建屋与赈济蠲免，但明廷财政已困。", figures: ["朱厚熜"], place: "华县、渭南（今陕西渭南—西安东部）", state: "明", sources: ["《明史·五行志》","《嘉靖陕西志》","《中国历史强震目录》"], tags: ["地震","灾害"] }, related: ["cn--1303--d01", "world--1556--d01"] },
  { id: "cn--1557--p01", track: "cn", year: 1557, yearApprox: false, dim: "politics", weight: 4, title: "葡人入居濠镜", summary: "明许其留居澳门，岁输地租。", detail: { background: "被逐出屯门、双屿的葡萄牙人转往浪白滘，1553年前后以借地曝货入居濠镜澳。", process: "约1557年（嘉靖三十六年）明廷准许葡人留居澳门，岁输地租银五百两（万历十七年定为定额），设香山县丞与澳夷议事堂并行，华夷分治。", impact: "澳门成为中西贸易与传教的枢纽，也是中国领土上第一个欧洲人长期居留并自治的港口。", figures: ["汪柏","索萨"], place: "濠镜澳（今澳门）", state: "明／葡萄牙", sources: ["《明史·佛郎机传》","《香山县志》","《澳门纪略》"], tags: ["澳门","居港"] }, related: ["cn--1521--m01", "world--1557--i01"] },
  { id: "cn--1561--m01", track: "cn", year: 1561, yearApprox: false, dim: "military", weight: 4, title: "戚继光台州九战九捷", summary: "鸳鸯阵歼倭于浙东海岸。", detail: { background: "1560年戚继光练兵于浙江，募金华、义乌矿工农人，编什伍、习鸳鸯阵与火器。", process: "1561年（嘉靖四十年）五月，倭船数百大举入浙，戚继光于新河、花街、上盘岭、长沙诸地九战皆捷，奏报斩首二千二百余级，焚溺无算，所全居民数万。", impact: "台州之胜使倭寇丧失在浙江的进攻能力，戚家军与鸳鸯阵成为明代东南防倭的样板。", figures: ["戚继光","俞大猷","胡宗宪"], place: "台州府（今浙江临海—温岭）", state: "明", sources: ["《纪效新书》","《明史·戚继光传》","《筹海图编》卷一一"], tags: ["戚家军","倭寇"] }, related: ["cn--1555--m01"] },
  { id: "cn--1562--p01", track: "cn", year: 1562, yearApprox: false, dim: "politics", weight: 3, title: "严嵩罢相徐阶入阁", summary: "权阁二十年告终，言路反攻。", detail: { background: "严嵩自1542年入阁，父子擅国，以青词得幸，贪墨结党，边事倭患交困。", process: "1562年（嘉靖四十一年）十二月，御史邹应龙劾严世蕃，术士蓝道行因扶鸾进言，严嵩削籍致仕，徐阶代为首辅；1565年世蕃以通倭罪弃市，嵩贫死里中。", impact: "嘉靖后期政治转向，徐阶引高拱、张居正入阁，为隆万大改革准备人事条件。", figures: ["严嵩","徐阶","邹应龙"], place: "北京—分宜（今江西新余）", state: "明", sources: ["《明史·严嵩传》","《明世宗实录》卷五一九","《嘉靖以来首辅传》"], tags: ["权臣","内阁"] }, related: ["cn--1542--p01"] },
  { id: "cn--1563--m01", track: "cn", year: 1563, yearApprox: false, dim: "military", weight: 3, title: "平海卫大捷", summary: "戚继光俞大猷会剿，破倭巢兴化。", detail: { background: "1562年冬倭陷兴化府城，据平海卫为巢，明廷增调浙兵入闽。", process: "1563年（嘉靖四十二年）十一月，戚继光、俞大猷、刘显三路合击平海卫，奏报斩首二千二百余级，救回被掳民三千余，兴化府城复。", impact: "福建倭乱至此基本平定，明廷随即于闽南调整卫所与府县建制以固海防。", figures: ["戚继光","俞大猷","刘显"], place: "平海卫（今福建莆田秀屿）", state: "明", sources: ["《明史·戚继光传》","《闽书》","《筹海图编》卷一〇"], tags: ["倭寇","福建"] }, related: ["cn--1561--m01"] },
  { id: "cn--1566--p01", track: "cn", year: 1566, yearApprox: false, dim: "politics", weight: 3, title: "海瑞上治安疏", summary: "户部主事直斥皇帝，下诏狱。", detail: { background: "嘉靖末年斋醮糜费、吏治贪墨，江南民情困敝；海瑞时任户部云南司主事。", process: "1566年（嘉靖四十五年）二月，海瑞上《直言天下第一事疏》，斥「天下人不直陛下久矣」，备棺诀家而入；世宗大怒下诏狱，意杀之而久未决。", impact: "1567年穆宗立后获释，海瑞成为明代清官政治的象征，其奏疏广为传抄。", figures: ["海瑞","朱厚熜"], place: "北京—琼山（今海南海口）", state: "明", sources: ["《明史·海瑞传》","《海瑞集·治安疏》","《明穆宗实录》卷六"], tags: ["清官","言路"] }, related: ["cn--1562--p01"] },
  { id: "cn--1567--p01", track: "cn", year: 1567, yearApprox: false, dim: "politics", weight: 5, title: "隆庆开关许贩东西洋", summary: "月港弛禁征税，唯不许通日本。", detail: { background: "倭乱平后闽人私贩不熄；1567年前后福建巡抚涂泽民请开海禁以杜乱本。", process: "1567年（隆庆元年）明廷于漳州月港设督饷馆，许民船贩东西二洋（日本仍禁），征水饷、陆饷、加增饷，岁入数万两。", impact: "中国半世纪的海禁政策松动，海商与白银输入合法化，全球贸易中的中国门户由此打开。", figures: ["涂泽民","朱载坖"], place: "月港（今福建漳州海澄）", state: "明", sources: ["《明史·食货志》","《东西洋考》卷五","《漳州府志》"], tags: ["隆庆开关","月港"] }, related: ["cn--1548--p01"] },
  { id: "cn--1569--p01", track: "cn", year: 1569, yearApprox: false, dim: "politics", weight: 2, title: "高拱以阁臣掌吏部", summary: "铨政权归内阁，边才选用大变。", detail: { background: "隆庆初内阁与吏部相制，督抚用人迟缓，边事需才有急。", process: "1569年（隆庆三年）十二月，高拱以大学士兼掌吏部事，亲择督抚司道，用王崇古、谭纶、戚继光、张居正分任边政与财政。", impact: "选官效率提高直接促成俺答封贡与蓟镇防务，但也加剧阁部一体的权臣风险。", figures: ["高拱","张居正","王崇古"], place: "北京", state: "明", sources: ["《明史·高拱传》","《明穆宗实录》卷四一","《国榷》卷六五"], tags: ["吏部","边政"] }, related: ["cn--1571--p01"] },
  { id: "cn--1570--m01", track: "cn", year: 1570, yearApprox: false, dim: "military", weight: 2, title: "戚继光李成梁分镇边", summary: "一人守蓟门，一人守辽左，各十余年。", detail: { background: "隆庆间以谭纶督蓟辽，边墙、车营与火器台营相继修筑。", process: "1570年前后戚继光以总兵官镇蓟州，筑敌台一千余座、练车步骑营；李成梁任辽东总兵，十余年间迭击土蛮、建州，成「辽东将门」。", impact: "晚明北边依靠二镇支撑，其军费与家丁制也埋下辽东军阀化的伏笔。", figures: ["戚继光","李成梁","谭纶"], place: "蓟州镇—辽东镇", state: "明", sources: ["《明史·戚继光传》","《明史·李成梁传》","《练兵实纪》"], tags: ["九边","将门"] }, related: ["cn--1569--p01"] },
  { id: "cn--1571--p01", track: "cn", year: 1571, yearApprox: false, dim: "politics", weight: 4, title: "俺答封贡顺义王", summary: "蒙汉和议成，北边开市十一处。", detail: { background: "1570年俺答孙把都那吉以部众降明，王崇古、张居正主以封贡互市易兵革。", process: "1571年（隆庆五年）三月封俺答为顺义王，其子弟部长六十余人授都督、指挥等职，开大同、宣府、山西等十一处市口，岁以马易绸布。", impact: "明蒙关系由对抗转入贸易，北边近半世纪较安定，蒙古畜牧经济与中原手工业互为依存。", figures: ["俺答","王崇古","张居正","朱载坖"], place: "大同—归化城（今呼和浩特）", state: "明／蒙古", sources: ["《明史·鞑靼传》","《明穆宗实录》卷五六","《万历武功录》"], tags: ["封贡","互市"] }, related: ["cn--1550--m01"] },
  { id: "cn--1572--p01", track: "cn", year: 1572, yearApprox: false, dim: "politics", weight: 4, title: "神宗立张居正秉政", summary: "十岁皇帝即位，高拱被逐出阁。", detail: { background: "1572年五月穆宗崩，太子翊钧十岁即位；内廷冯保与张居正结，外廷权臣相争。", process: "六月张居正与冯保以太后名义逐高拱回籍，次年内倚司礼监、外揽政柄，1573年改元万历，李太后与内阁共辅幼主。", impact: "张居正十年专政的起点，明代内阁权力在此达到顶点。", figures: ["朱翊钧","张居正","冯保","高拱","李太后"], place: "北京", state: "明", sources: ["《明史·张居正传》","《明神宗实录》卷二","《帝鉴图说》"], tags: ["万历","权臣"] }, related: ["cn--1569--p01"] },
  { id: "cn--1573--i01", track: "cn", year: 1573, yearApprox: false, dim: "institution", weight: 5, title: "行考成法课百司", summary: "以内阁控六科、六科控抚按，限期完销。", detail: { background: "明中后期章奏留中、有令不行，行政效率崩坏。", process: "1573年（万历元年）十一月张居正上《请稽查章奏随事考成以修实政疏》，设文簿三本，逐事立限、月有考、岁有核，抚按未完者由六科参奏，内阁复核六科。", impact: "内阁由此取得对全国行政过程的核查权，为清丈田亩与一条鞭法提供了执行机器。", figures: ["张居正"], place: "北京内阁与六科廊", state: "明", sources: ["《张太岳集》卷三八","《明史·张居正传》","《明神宗实录》卷二〇"], tags: ["考成法","行政"] }, related: ["cn--1572--p01"] },
  { id: "cn--1577--p01", track: "cn", year: 1577, yearApprox: false, dim: "politics", weight: 3, title: "张居正夺情之争", summary: "父丧不奔，四臣廷杖除名。", detail: { background: "1577年（万历五年）九月张居正父丧，依制应丁忧二十七个月；帝与太后下「夺情」留任。", process: "吴中行、赵用贤、艾穆、沈思孝上疏争之，皆廷杖除名或谪戍，张居正青衣视事而门生故吏遍朝省。", impact: "礼法与效率之争演变为道德指控，成为1582年后清算张居正的最有力口实。", figures: ["张居正","吴中行","赵用贤","朱翊钧"], place: "北京—江陵（今湖北荆州）", state: "明", sources: ["《明史·张居正传》","《明神宗实录》卷六六","《万历野获编》"], tags: ["夺情","丁忧"] }, related: ["cn--1582--p01"] },
  { id: "cn--1578--s01", track: "cn", year: 1578, yearApprox: false, dim: "science", weight: 3, title: "《本草纲目》稿定", summary: "李时珍二十七年三易其稿。", detail: { background: "李时珍（1518—1593）楚黄州医家，以旧本草名实淆乱、谬误多而重撰。", process: "1578年（万历六年）《本草纲目》稿定，五十二卷、十六部、六十类，收药一千八百九十二种，附方一万余，按「从贱至贵」立纲目，亲采并验于临床。", impact: "为传统本草学集大成之作，后传日本、欧洲，被部分西方学者视为近代博物学之前的药物志高峰。", figures: ["李时珍","王世贞"], place: "蕲州（今湖北黄冈蕲春）", state: "明", sources: ["《本草纲目》原序","《明史·方技传》","《四库全书总目·本草类》"], tags: ["本草学","医学"] }, related: ["cn--1596--s01"] },
  { id: "cn--1579--p01", track: "cn", year: 1579, yearApprox: false, dim: "politics", weight: 3, title: "诏毁天下私建书院", summary: "张居正恶讲学结党，禁别聚徒。", detail: { background: "嘉靖隆庆间讲会盛行，阳明后学聚徒议政，朝臣疑其「别立门户」。", process: "1579年（万历七年）诏毁天下私创书院，先拆京师及顺天、舒城讲舍，戒有司禁别聚徒、以虚文相眩；各处官学仍存。", impact: "讲学自由受挫，士人议政空间被压缩；张居正死后禁令渐弛，晚明书院与党议同时勃兴。", figures: ["张居正","朱翊钧"], place: "京师及各行省书院", state: "明", sources: ["《明神宗实录》卷八一","《明史·张居正传》","《东林书院志》"], tags: ["书院","思想控制"] }, related: ["cn--1530--c01"] },
  { id: "cn--1580--e01", track: "cn", year: 1580, yearApprox: false, dim: "economy", weight: 4, title: "全国清丈田亩", summary: "万历八年起核田，得额七百余万顷。", detail: { background: "豪势隐占、花分诡寄使税基流失，嘉靖隆庆间有司请清丈屡不行。", process: "1580年（万历八年）张居正主持全国清丈，以弓步量田、分则升降，至万历十年基本完成；册载田土由弘治间约四百七十万顷增至约七百余万顷，其中含隐田出额与新垦。", impact: "税基显著扩大、无地少地者的代役负担有所减轻，为一条鞭法铺路；亦引起士绅阶层强烈反弹。", figures: ["张居正","朱翊钧"], place: "两京十三省", state: "明", sources: ["《明史·食货志》","《张太岳集》卷三八","梁方仲《明代赋役制度》"], tags: ["清丈","田赋"] }, related: ["cn--1581--i01"] },
  { id: "cn--1581--i01", track: "cn", year: 1581, yearApprox: false, dim: "institution", weight: 5, title: "一条鞭法推行全国", summary: "并赋役为一，计亩征银、官为雇役。", detail: { background: "嘉靖间福建、南直隶、浙江已局部行一条鞭；里甲力役不均、有司征派百出。", process: "1581年（万历九年）张居正请以一条鞭法通行天下：总一县之赋役，量计通摊，悉并为银两，计亩出夫、官为雇役，由里甲改为纳银于官。", impact: "赋役制度的货币化定型，人身依附松弛、商品经济与市镇扩张获得制度条件，清代摊丁入亩承其余绪。", figures: ["张居正"], place: "两京十三省", state: "明", sources: ["《明史·食货志》","《大明会典·赋役》","梁方仲《明代一条鞭法》"], tags: ["一条鞭法","赋役"] }, related: ["cn--1580--e01"] },
  { id: "cn--1582--p01", track: "cn", year: 1582, yearApprox: false, dim: "politics", weight: 4, title: "张居正卒新政遭反攻", summary: "赠上柱国旋被追论，改革遗产瓦解。", detail: { background: "张居正自1577年夺情后积劳成疾，晚年服丹石求疗。", process: "1582年（万历十年）六月二十日卒于京师，赠上柱国、谥文忠；神宗亲政后言官追论其夺情、擅权、植党，1584年三月下诏抄其家，家属饿死十余人，所行考成、清丈多被罢。", impact: "十年改革的制度成果部分保留、政治遗产全毁，万历朝中枢由此失去有效率的行政核心。", figures: ["张居正","朱翊钧","李太后"], place: "北京—江陵", state: "明", sources: ["《明史·张居正传》","《明神宗实录》卷一二五","《张太岳集》"], tags: ["万历","改革"] }, related: ["cn--1573--i01"] },
  { id: "cn--1584--p01", track: "cn", year: 1584, yearApprox: false, dim: "politics", weight: 2, title: "追抄江陵张氏", summary: "锦衣按籍逼赃，举朝寒心。", detail: { background: "神宗以「贪暴无厌」罪张居正，诏削其官秩并追赃。", process: "1584年（万历十二年）三月锦衣卫官校往抄其家，封锁宅门一月逼赃，长子张敬修自经死，遗书诉刑逼；朝臣论救者多，次年稍宽其狱。", impact: "清算使士大夫对改革派集体疏离，万历后期党争与「国本」问题因此获得道德武器。", figures: ["朱翊钧","张居正","张敬修"], place: "江陵（今湖北荆州）", state: "明", sources: ["《明史·张居正传》","《明神宗实录》卷一四七"], tags: ["抄家","党争"] }, related: ["cn--1582--p01"] },
  { id: "cn--1587--i01", track: "cn", year: 1587, yearApprox: false, dim: "institution", weight: 3, title: "重修《大明会典》成", summary: "以官统事、以事隶官，二百二十八卷。", detail: { background: "弘治《大明会典》成于1502年，隆庆间诏重修以备典常。", process: "1587年（万历十五年）重修本成，凡二百二十八卷，以六部官制为纲、逐年事例为目，详载宗藩、职官、赋役、军政、礼仪诸制。", impact: "为明代行政与典章最完备的制度汇编，清《大清会典》体例即承其法。", figures: ["朱翊钧","申时行"], place: "北京", state: "明", sources: ["《大明会典》万历朝修本","《明史·艺文志》","《四库全书总目·政书类》"], tags: ["典制","会典"] }, related: ["cn--1573--i01"] },
  { id: "cn--1587--p01", track: "cn", year: 1587, yearApprox: true, dim: "politics", weight: 3, title: "神宗渐不视朝", summary: "郊庙经筵稀举，章奏多留中不发。", detail: { background: "1586—1587年「国本」之争起，帝欲立宠妃郑氏之子，与群臣对峙。", process: "约自1587年（万历十五年）后，神宗视朝、经筵、郊庙之礼渐废，章奏留中不发，六部与都察院缺员不补，廷推大僚往往不报。", impact: "中枢行政逐渐停摆，言路受抑而朋党兴起，被视为明亡的长期制度原因之一。", figures: ["朱翊钧","申时行"], place: "北京大内", state: "明", sources: ["《明史·神宗本纪》","《明神宗实录》卷一八五","黄仁宇《万历十五年》"], tags: ["万历怠政","国本"] }, related: ["cn--1584--p01"] },
  { id: "cn--1590--a01", track: "cn", year: 1590, yearApprox: false, dim: "art", weight: 3, title: "坊刻小说与戏曲全盛", summary: "建阳金陵苏州书肆竞刻传奇。", detail: { background: "万历间江南与福建刻书业商品化，读者群扩至商贾市井。", process: "约1590年代，建阳、金陵、苏州、杭州书坊大量刊行《三国》《水浒》《西游》及话本、传奇剧本，插图本与李贽、叶昼诸家评点本相继出现。", impact: "白话小说取得与诗文并立的文学地位，形成中国出版史上第一次大众阅读浪潮。", figures: ["李贽","叶昼"], place: "建阳—金陵—苏州", state: "明", sources: ["胡应麟《少室山房笔丛》","《中国古籍总目》集部","周绍斌《明代建阳书坊研究》"], tags: ["出版业","小说"] }, related: ["cn--1500--e01"] },
  { id: "cn--1590--c01", track: "cn", year: 1590, yearApprox: false, dim: "culture", weight: 4, title: "李贽《焚书》刊行", summary: "以心学异端非圣无法，旋遭禁毁。", detail: { background: "李贽（1527—1602）福建泉州人，仕至姚安知府，后寓湖北麻城芝佛院讲学。", process: "1590年（万历十八年）《焚书》刻于麻城，收杂文、书信、史论，斥「穿衣吃饭即是人伦物理」，讥假道学，自称书当焚而不后人必传。", impact: "其说震动士林，成为晚明个性解放与思想异端的标志；1602年被以「敢倡乱道」下狱。", figures: ["李贽","耿定向","周思敬"], place: "麻城芝佛院（今湖北黄冈麻城）", state: "明", sources: ["《焚书》《续焚书》","《明史·李贽传》","《续藏书》"], tags: ["异端","晚明思想"] }, related: ["cn--1579--p01"] },
  { id: "cn--1592--e01", track: "cn", year: 1592, yearApprox: false, dim: "economy", weight: 3, title: "万历三大征耗空太仓", summary: "宁夏、朝鲜、播州连年用兵。", detail: { background: "万历中叶太仓银库岁入约四百万两，而有额之外费日增。", process: "自1592年宁夏之役、1592至1598年援朝之役至1600年播州之役，《明史·食货志》与近代学者核算兵饷先后耗费约一千一二百万两，辽饷与东征兵饷皆加派于民。", impact: "三大征的军费耗竭使万历后期只能靠矿税与加派弥补，明末财政危机由此开端。", figures: ["朱翊钧"], place: "宁夏—朝鲜—播州", state: "明", sources: ["《明史·食货志》","《万历会计录》","万明《明代白银货币化研究》"], tags: ["军费","财政危机"] }, related: ["cn--1596--p01"] },
  { id: "cn--1592--m01", track: "cn", year: 1592, yearApprox: false, dim: "military", weight: 4, title: "倭军两月陷朝鲜三都", summary: "小西行长登陆釜山，宣祖奔义州。", detail: { background: "丰臣秀吉统一日本后谋「假道入明」，1592年四月发军十五六万分八道渡海。", process: "1592年（万历二十年）四月十三日倭军登陆釜山，五月三日陷汉城、六日陷平壤，宣祖李昖北奔义州遣使告急求援；六月辽东副总兵祖承训以三千骑败于平壤。", impact: "朝鲜半壁沦陷，明朝被迫以国帑与兵力卷入持久战，史称万历朝鲜之役（壬辰倭乱）。", figures: ["丰臣秀吉","小西行长","李昖","祖承训"], place: "釜山—汉城—平壤", state: "明／朝鲜／日本", sources: ["《明史·日本传》","《朝鲜王朝实录·宣祖实录》","《惩毖录》"], tags: ["壬辰倭乱","援朝"] }, related: ["cn--1593--m01"] },
  { id: "cn--1592--m02", track: "cn", year: 1592, yearApprox: false, dim: "military", weight: 3, title: "哞拜据宁夏城叛", summary: "副总兵起兵杀巡抚，围城五月。", detail: { background: "哞拜为蒙古降丁之后，任宁夏副总兵，因不堪巡抚党馨刻削军饷而起。", process: "1592年（万历二十年）二月杀巡抚党馨、据宁夏城，众号数万，陷灵州，西北震动；明以陕西、延绥诸军合围，九月决黄河水灌城，哞拜为其将所杀。", impact: "宁夏之役与东援朝鲜同时爆发，使明廷财政与兵力在1592至1598年间连续透支。", figures: ["哞拜","党馨","李如松","魏学曾"], place: "宁夏（今银川）", state: "明", sources: ["《明神宗实录》卷二四四","《明史·魏学曾传》","《平夏纪略》"], tags: ["哞拜之乱","九边"] }, related: ["cn--1592--m01"] },
  { id: "cn--1593--m01", track: "cn", year: 1593, yearApprox: false, dim: "military", weight: 4, title: "李如松克平壤", summary: "四万明军入朝，火炮摧其城。", detail: { background: "1592年十二月以宋应昌为经略、李如松为提督，募辽东、宣府、大同、山西兵四万余东渡。", process: "1593年（万历二十一年）正月二十三日薄平壤，二十四日以佛郎机、大将军炮攻城，奏报斩级千二百余，倭军夜遁，一日之内收复平壤及黄海道诸城。", impact: "扭转朝鲜战局，明、朝联军复汉城与开城；但碧蹄馆受挫后转入议和与长期对峙。", figures: ["李如松","宋应昌","小西行长","李昖"], place: "平壤（今朝鲜平壤）", state: "明／朝鲜／日本", sources: ["《明史·李如松传》","《宣祖昭敬大王实录》","《东征记》"], tags: ["平壤","援朝战争"] }, related: ["cn--1592--m01"] },
  { id: "cn--1596--p01", track: "cn", year: 1596, yearApprox: false, dim: "politics", weight: 4, title: "矿税内监四出", summary: "以开矿征税为名，缇骑遍于天下。", detail: { background: "万历中后期用兵宁夏、朝鲜致太仓匮竭，帝以商税矿利充内库。", process: "1596年（万历二十四年）起陆续派出矿监税使，陈奉行湖广、马堂行山东、梁永行陕西、高寀行福建，所至擅缚官吏、估市民财，征银入内库。", impact: "内库与太仓分立导致财政外失控，激起临清、武昌、苏州等地民变，成为晚明民怨与党争焦点。", figures: ["朱翊钧","陈奉","马堂","高寀"], place: "湖广—山东—福建—陕西", state: "明", sources: ["《明史·宦官传》","《明神宗实录》卷二九九","《万历野获编》"], tags: ["矿税","财政"] }, related: ["cn--1587--p01"] },
  { id: "cn--1596--s01", track: "cn", year: 1596, yearApprox: false, dim: "science", weight: 5, title: "《本草纲目》金陵刊行", summary: "胡承龙刻成，此后东亚药学的母本。", detail: { background: "稿成后二十年无资刻行，1593年李时珍卒，其子李建元持稿赴南京请刻。", process: "1596年（万历二十四年）胡承龙金陵刻本行世，凡五十二卷、收药一千八百九十二种、附方一万一千余、图一千一百余幅；次年李建元进呈于朝。", impact: "成为中医药学最通行的本草文本，先后东传日本、朝鲜，并被摘译入欧洲博物学文献。", figures: ["李时珍","胡承龙","王世贞"], place: "南京（今江苏南京）", state: "明", sources: ["《本草纲目》金陵本","《明史·方技传》","范行准《中国医学史略》"], tags: ["本草","出版"] }, related: ["cn--1578--s01"] },
  { id: "cn--1597--m01", track: "cn", year: 1597, yearApprox: false, dim: "military", weight: 3, title: "丁酉再乱倭复犯朝鲜", summary: "南原陷、闲山失，明再发兵援朝。", detail: { background: "1596年封贡失败（秀吉不受「日本国王」之号），翌年倭军再渡海。", process: "1597年（万历二十五年）八月陷南原，明将杨元被劾弃市；九月倭复据湖南，水军失闲山岛；明以邢玠为经略、杨镐为经理，再发兵约四万，麻贵督诸军。", impact: "战争再耗国力，明廷内部对封、战、和的争论与党争交织，边备与财政同时恶化。", figures: ["邢玠","杨镐","麻贵","丰臣秀吉"], place: "南原—闲山岛（今韩国全罗—庆尚）", state: "明／朝鲜／日本", sources: ["《明史·日本传》","《宣祖实录》","《惩毖录》"], tags: ["丁酉再乱","援朝战争"] }, related: ["cn--1593--m01", "world--1598--p01"] },
  { id: "cn--1598--m01", track: "cn", year: 1598, yearApprox: false, dim: "military", weight: 4, title: "露梁海战与李舜臣之死", summary: "中朝水军焚撤退倭船，二老将俱殁。", detail: { background: "1598年九月丰臣秀吉死，倭军自蔚山、顺天、东莱诸倭堡内撤。", process: "十一月，明水师陈璘、邓子龙与朝鲜统制使李舜臣会于露梁海（今韩国庆尚南道南海），纵火焚其舟百余；邓子龙所乘船为风所反烧，溺死，李舜臣中弹阵亡，倭军死者万余。", impact: "壬辰战争以倭军全部撤退告终，朝鲜得复国，但明朝军费耗尽与辽东空虚为此后女真崛起留下缺口。", figures: ["陈璘","邓子龙","李舜臣","岛津义弘"], place: "露梁海（今韩国南海郡）", state: "明／朝鲜／日本", sources: ["《明史·陈璘传》","《李忠武公全书》","《乱中杂录》"], tags: ["露梁","海战"] }, related: ["cn--1597--m01"] },
  { id: "cn--1600--m01", track: "cn", year: 1600, yearApprox: false, dim: "military", weight: 3, title: "平播州之役", summary: "八路分进克海龙屯，杨应龙自焚。", detail: { background: "播州杨氏自唐末据今黔北凡二十余世；杨应龙与五土司构兵，又屡抗朝命、私僭名号。", process: "1600年（万历二十八年）明以李化龙总督川湖贵军务，调八路兵约十四万分进，六月初攻破天险海龙屯，杨应龙自焚，前后四十余日。", impact: "同年分播州为遵义、平越二府，以流官代土司，西南改土归流由此开端；平播与宁夏、朝鲜之役合称万历三大征。", figures: ["李化龙","杨应龙","刘綎"], place: "播州海龙屯（今贵州遵义）", state: "明", sources: ["《明史·贵州土司传》","《平播全书》","《明神宗实录》卷三五八"], tags: ["播州之役","改土归流"] }, related: ["cn--1592--e01"] },
  { id: "cn--1601--e01", track: "cn", year: 1601, yearApprox: false, dim: "economy", weight: 3, title: "苏州织民葛成抗税", summary: "机户万人入城杀税官，自成自缚请罪。", detail: { background: "1596年后矿税使四出，苏州税监孙隆增收机税，凡织机一张纳银三钱，机户停织、佣工失食。", process: "1601年（万历二十九年）三月，葛成率机户万人入城，杀委官黄建节，孙隆遁走；事后葛成自缚赴官，请求归罪于己以救同谋，有司缓其狱，数年后得释。", impact: "矿税之征在万历末年渐次收敛，东南市民以暴动迫使朝廷退让成为先例，被后世视为明末城市力量的标志事件。", figures: ["葛成","孙隆"], place: "苏州（今江苏苏州）", state: "明", sources: ["《明史·宦官传》","《明神宗实录》卷三六〇","《定乱纪事》"], tags: ["矿税","市民暴动"] }, related: ["cn--1596--p01"] },
  { id: "cn--1602--f01", track: "cn", year: 1602, yearApprox: false, dim: "figure", weight: 3, title: "李贽下狱死", summary: "以敢倡乱道逮治，九月自经于狱。", detail: { background: "李贽居麻城、通州讲学，斥假道学、非圣无法，礼科给事中张问达交劾其惑世诬民。", process: "1602年（万历三十年）三月诏逮李贽下诏狱，并命焚其《焚书》《藏书》；贽年七十六，九月以理发取刮刀自经死；诏并逮其徒，江南讲学之士多被论劾。", impact: "晚明最具刺激性的思想一脉由朝廷出面斩断，但其书在江南坊间仍流通，清代列入禁毁反扩大其声名。", figures: ["李贽","张问达"], place: "通州—北京诏狱（今北京通州）", state: "明", sources: ["《明神宗实录》卷三七二","《明史·李贽传》","《焚书》卷首"], tags: ["异端","禁书"] }, related: ["cn--1590--c01"] },
  { id: "cn--1602--x01", track: "cn", year: 1602, yearApprox: false, dim: "explore", weight: 3, title: "坤舆万国全图刻成", summary: "中文世界地图首次刊行流布。", detail: { background: "利玛窦自1584年在肇庆作《山海舆地全图》，屡经增改，以中文注说地圆、五洲与经纬度。", process: "1602年（万历三十年）李之藻出资刻《坤舆万国全图》于北京，六大条幅合为一幅椭圆形世界图，绘四大洲、列国名，并附天文、气候、物产解说百余条。", impact: "中国人首次在印刷品上看见全球轮廓与地圆说，传统天下格局被撬开，明末士人据此重论夷夏、历算与疆域。", figures: ["利玛窦","李之藻"], place: "北京（今北京）", state: "明", sources: ["《坤舆万国全图》原图","利玛窦、金尼阁《中国札记》","《明神宗实录》卷三六九"], tags: ["世界地图","西学东渐"] }, related: ["cn--1607--s01", "world--1601--c01"] },
  { id: "cn--1604--p01", track: "cn", year: 1604, yearApprox: false, dim: "politics", weight: 4, title: "东林书院讲会起", summary: "顾宪成讲学无锡，讽议朝政裁量人物。", detail: { background: "顾宪成万历间削籍归无锡，与弟顾允成、同里高攀龙以讲学复士大夫声气。", process: "1604年（万历三十二年）重修宋杨时讲学之东林书院，定每月一大会、每旬一小会，讲习之余讽议朝政、裁量人物，远近士人响应，京朝官亦与通书问。", impact: "讲学组织与朝局清议相接，演为晚明最重要的党议网络，与廷推、京察及三案纠缠，至天启间被尽逐。", figures: ["顾宪成","高攀龙","顾允成"], place: "无锡东林书院（今江苏无锡）", state: "明", sources: ["《东林书院志》","《明史·顾宪成传》","《明神宗实录》卷四〇三"], tags: ["东林党","讲学"] }, related: [] },
  { id: "cn--1607--s01", track: "cn", year: 1607, yearApprox: false, dim: "science", weight: 4, title: "《几何原本》前六卷译刻", summary: "徐光启利玛窦合译，创点线面诸译名。", detail: { background: "利玛窦欲传欧几里得之学，先口译数条；徐光启以生员从游，请以全文为定本。", process: "1607年（万历三十五年）《几何原本》前六卷刻于北京，凡定义、公设、命题四百余则；徐光启定几何、点、线、面、平行、直角等译名，并称其用为医世之业。", impact: "中国首次系统接受演绎证明的数学方法，此后历算、测量、火器测算皆援其法，多数译名沿用至今。", figures: ["徐光启","利玛窦"], place: "北京（今北京）", state: "明", sources: ["《几何原本》徐光启跋","《徐光启集》","利玛窦、金尼阁《中国札记》"], tags: ["几何学","翻译"] }, related: ["cn--1602--x01"] },
  { id: "cn--1610--c01", track: "cn", year: 1610, yearApprox: false, dim: "culture", weight: 2, title: "利玛窦卒赐葬京师", summary: "西来传教士以宾礼入葬，士大夫会吊。", detail: { background: "利玛窦以适应策略入士林，服儒衣、通经典，1610年三月病笃于北京。", process: "1610年（万历三十八年）五月十一日利玛窦卒，年六十；诏赐葬地于阜城门外，李之藻为撰碑阴，教士龙华民主其葬仪，西洋人在京师公开营葬自此始。", impact: "士大夫以宾礼待西洋教士的窗口期至此结束，此后南京教案与百年礼争接踵而来。", figures: ["利玛窦","李之藻","龙华民"], place: "北京阜城门外（今北京）", state: "明", sources: ["《利玛窦行实》","《李之藻集》","《徐光启集》"], tags: ["耶稣会","传教"] }, related: ["cn--1616--p02"] },
  { id: "cn--1615--i01", track: "cn", year: 1615, yearApprox: false, dim: "institution", weight: 4, title: "建州定四旗之制", summary: "牛录、甲喇、固山三级编成军政。", detail: { background: "努尔哈赤自1601年编牛录出猎行军，行伍以族党为单元，规模既大则旧制不够用。", process: "1615年（万历四十三年）定三级之制：三百人为一牛录，置牛录额真；五牛录为一甲喇，五甲喇为一固山（旗），置黄、白、红、蓝四旗，统约六万五千牛录丁。", impact: "兵民合一的旗制使小邦得以齐整征调，入关后更成为八旗、旗地、俸饷诸制的母体，贯穿清代一代。", figures: ["努尔哈赤"], place: "赫图阿拉（今辽宁新宾）", state: "明／后金", sources: ["《满文老档》","《清太祖武皇帝实录》","《八旗通志》"], tags: ["八旗","牛录"] }, related: ["cn--1616--p01"] },
  { id: "cn--1616--a01", track: "cn", year: 1616, yearApprox: false, dim: "art", weight: 2, title: "汤显祖卒", summary: "四梦成后，主情词曲家谢世临川。", detail: { background: "汤显祖以《紫箫》《还魂》《南柯》《邯郸》四梦名世，主张情至而抑理拘。", process: "1616年（万历四十四年）六月十五日汤显祖卒于临川玉茗堂，年六十六；《牡丹亭》自1598年成书后已被伶人搬演于江南士大夫之宴。", impact: "其情不知所起、一往而深之说成为晚明文艺标语，临川文采派与吴江格律派之争延续至清初。", figures: ["汤显祖"], place: "临川（今江西抚州）", state: "明", sources: ["《汤显祖集》","《玉茗堂全集》","《明史·文苑传》"], tags: ["戏曲","牡丹亭"] }, related: [] },
  { id: "cn--1616--p01", track: "cn", year: 1616, yearApprox: false, dim: "politics", weight: 4, title: "努尔哈赤建后金", summary: "即汗位赫图阿拉，建元天命。", detail: { background: "努尔哈赤并建州、野人女真诸部，1603年筑城赫图阿拉，1615年定旗制，与明的属夷关系名存实亡。", process: "1616年（万历四十四年）正月，努尔哈赤称覆育列国英明汗，国号金（史称后金），建元天命，以赫图阿拉为兴京，置五大臣、议五大臣辅政之制。", impact: "东北出现与明对等的政权，此后十年明辽东全线崩溃；清代帝系与法统即追溯于此。", figures: ["努尔哈赤","费英东","额亦都"], place: "赫图阿拉（今辽宁新宾）", state: "明／后金", sources: ["《清太祖实录》","《满文老档》","《明神宗实录》卷五三七"], tags: ["后金","女真"] }, related: ["cn--1615--i01", "cn--1619--m01"] },
  { id: "cn--1616--p02", track: "cn", year: 1616, yearApprox: false, dim: "politics", weight: 2, title: "南京教案逐教士", summary: "沈㴶参大西洋人左道，教士被逮。", detail: { background: "耶稣会士在江南建会所、信众逾万，南京礼部侍郎沈㴶恶其不祀祖先、耗公帑、阴结党援。", process: "1616年（万历四十四年）八月沈㴶三疏参西洋人创为左道、诱骗良家，南京逮捕王丰肃等教士与华人信徒数十人，枷号流徙；1622年后以修历、铸炮之需陆续召回。", impact: "西学东渐遭受第一次政治中断，朝廷对西洋人的政策由士大夫私交转为制度性猜防。", figures: ["沈㴶","王丰肃","徐光启"], place: "南京—北京", state: "明", sources: ["《破邪集》","《徐光启集·辨学章疏》","《明神宗实录》卷五四七"], tags: ["教案","耶稣会"] }, related: ["cn--1610--c01"] },
  { id: "cn--1618--m01", track: "cn", year: 1618, yearApprox: false, dim: "military", weight: 3, title: "七大恨告天袭抚顺", summary: "后金誓师东向，一月两陷明堡。", detail: { background: "努尔哈赤怨明杀其祖、父于古勒山之役，又责明偏袒叶赫、越境屯种。", process: "1618年（万历四十六年）正月以七大恨告天誓师，四月十四日袭陷抚顺，守将李永芳降，明总兵张承胤战殁于清河堡；五月再陷清河、会安诸堡。", impact: "明廷被迫议加辽饷，自是岁派六百六十万两成为固定加赋，辽东将、吏、粮三重溃败自此开始。", figures: ["努尔哈赤","李永芳","张承胤"], place: "抚顺—清河（今辽宁抚顺—本溪）", state: "明／后金", sources: ["《清太祖实录》","《明神宗实录》卷五七二","《三朝辽事实录》"], tags: ["七大恨","辽东"] }, related: ["cn--1619--m01"] },
  { id: "cn--1619--m01", track: "cn", year: 1619, yearApprox: false, dim: "military", weight: 5, title: "萨尔浒之战五日三溃", summary: "明四路分进，后金并力迭破之。", detail: { background: "明以杨镐为辽东经略，合四方援兵号四十七万（实存约八至九万），分四路约期会攻赫图阿拉。", process: "1619年（万历四十七年）三月，杜松一路渡浑河在萨尔浒遭伏，一日军覆；次日马林败于尚间崖；刘綎路于阿布喇里中反间计战殁；李如柏、叶赫两路退缩而还。", impact: "此役后明在辽东由攻转守，沈阳、辽阳继陷；学界多视为明清易代的军事转折点，也是骑兵与火器会战的典型战例。", figures: ["努尔哈赤","杨镐","杜松","刘綎"], place: "萨尔浒（今辽宁抚顺东）", state: "明／后金", sources: ["《明史·杨镐传》","《清太祖实录》卷五","《三朝辽事实录》"], tags: ["萨尔浒","辽东"] }, related: ["cn--1618--m01", "cn--1621--m01"] },
  { id: "cn--1619--p01", track: "cn", year: 1619, yearApprox: false, dim: "politics", weight: 2, title: "熊廷弼经略辽东", summary: "以固守、练兵、火器三层收拾残局。", detail: { background: "萨尔浒丧师后开原、铁岭旋陷，辽人守堡之备尽弛，朝议须重臣镇之。", process: "1619年（万历四十七年）八月熊廷弼以兵部右侍郎经略辽东，主守实、练兵、间以火器，缮城郭、收溃卒、造战车火炮，辽人稍安。", impact: "明廷本可徐图恢复，然旋以王化贞为辽东抚、主战，与廷弼主守相反，将相不和直接酿成三年后的广宁之败。", figures: ["熊廷弼"], place: "辽阳—沈阳（今辽宁）", state: "明", sources: ["《明史·熊廷弼传》","《熊襄愍公集》","《明神宗实录》卷五九〇"], tags: ["辽东经略","守堡"] }, related: ["cn--1622--m01"] },
  { id: "cn--1620--p01", track: "cn", year: 1620, yearApprox: false, dim: "politics", weight: 2, title: "红丸案光宗一月而崩", summary: "李可灼进红丸，帝在位三十日。", detail: { background: "神宗、光宗皆久病；1620年七月光宗即位，郑贵妃旋进宫女，内侍崔文升以泻药进。", process: "光宗即位仅一月，八月患痢不起，鸿胪寺丞李可灼进所谓红丸，服后旋崩（九月二十六日），在位三十日；廷臣交劾郑贵妃与崔文升，是为红丸案，与梃击、移宫并称三案。", impact: "皇位继承与宫廷用药成为党争焦点，东林与齐楚浙党互攻不已，中枢的决策能力与威信被严重消耗。", figures: ["朱常洛","李可灼","杨涟"], place: "北京乾清宫、鸿胪寺", state: "明", sources: ["《明史·光宗本纪》","《明熹宗实录》卷三","《三朝野纪》"], tags: ["红丸案","三案"] }, related: ["cn--1587--p01"] },
  { id: "cn--1621--m01", track: "cn", year: 1621, yearApprox: false, dim: "military", weight: 3, title: "沈阳辽阳继陷", summary: "七日两城俱溃，辽东七十余城尽失。", detail: { background: "1620年末明以袁应泰经略辽东，抚纳蒙古各部而耗内库，城守之备渐弛。", process: "1621年（天启元年）三月十三日后金围沈阳，总兵贺世贤、尤世功战殁，城陷；十八日围辽阳，城中内应举火，袁应泰死之，将吏死者数十人，辽东七十余城俱下。", impact: "后金先后迁都辽阳、沈阳，明失辽东粮聚与铁产地；辽饷自是成为对北中国农户的固定加派。", figures: ["袁应泰","贺世贤","努尔哈赤"], place: "沈阳—辽阳（今辽宁）", state: "明／后金", sources: ["《明史·袁应泰传》","《清太祖实录》卷七","《三朝辽事实录》"], tags: ["辽沈","迁都"] }, related: ["cn--1619--m01", "cn--1622--m01"] },
  { id: "cn--1622--m01", track: "cn", year: 1622, yearApprox: false, dim: "military", weight: 3, title: "广宁之败退守山海关", summary: "抚臣临阵先走，明尽弃辽西。", detail: { background: "辽沈失后，明以王化贞主战、熊廷弼主守，二人谋议相反；化贞拥兵七万屯广宁而不用间。", process: "1622年（天启二年）正月后金渡辽河攻西平，化贞弃广宁西走，明军大溃，委弃城寨粮辎数十万；熊廷弼以残众入山海关，旋与化贞同被逮诛。", impact: "明辽东防线后撤二百余里，关外城寨尽失；广宁之败成为天启朝党狱的导火索，辽事自此不可为。", figures: ["王化贞","熊廷弼","孙承宗"], place: "广宁—山海关（今辽宁北镇—河北秦皇岛）", state: "明／后金", sources: ["《明史·熊廷弼传》","《明熹宗实录》卷二〇","《三朝辽事实录》"], tags: ["广宁","辽西"] }, related: ["cn--1621--m01", "cn--1625--m01"] },
  { id: "cn--1624--p01", track: "cn", year: 1624, yearApprox: false, dim: "politics", weight: 3, title: "《东林点将录》成", summary: "杨涟劾二十四大罪，阉党按名欲尽逐。", detail: { background: "天启初魏忠贤领司礼监兼提督东厂，与熹宗乳母客氏相结，言路日攻其弊。", process: "1624年（天启四年）六月左副都御史杨涟上疏劾魏忠贤二十四大罪，御史、给事中继起；阉党王绍徽仿《水浒传》造《东林点将录》，以一百零八人拟为天王地煞，按名以待擢用或汰逐。", impact: "清议与宦官权力的冲突公开化，为大狱提供名单；东林诸人或死诏狱、或削籍，中枢言路为之一空。", figures: ["魏忠贤","杨涟","王绍徽","左光斗"], place: "北京—无锡（今江苏）", state: "明", sources: ["《明史·宦官传》","《明熹宗实录》卷四二","《碧血录》"], tags: ["东林党","魏忠贤"] }, related: ["cn--1604--p01"] },
  { id: "cn--1624--x01", track: "cn", year: 1624, yearApprox: false, dim: "explore", weight: 3, title: "荷兰人据台湾南部", summary: "宋克筑热兰遮，明以借地互市容之。", detail: { background: "1622年荷兰东印度公司占澎湖，被明将沈有容谕退，乃转向东面之台湾。", process: "1624年（天启四年）荷兰长官宋克于大员湾筑城，明廷以借地互市默许；1626年西班牙人据鸡笼，1642年被逐，荷兰遂独据其岛，以蔗糖、鹿皮转口贸易为轴线。", impact: "台湾首次纳入欧洲—东亚转口贸易网；1662年郑成功逐荷后其地成为明郑基地，1683年入清版图。", figures: ["宋克","沈有容"], place: "大员（今台湾台南）", state: "明／荷兰", sources: ["《热兰遮城日志》","《明熹宗实录》卷四六","曹永和《台湾早期历史研究》"], tags: ["台湾","荷兰"] }, related: ["cn--1557--p01"] },
  { id: "cn--1625--m01", track: "cn", year: 1625, yearApprox: false, dim: "military", weight: 3, title: "孙承宗筑关宁锦防线", summary: "连城八堡四十七，且耕且守。", detail: { background: "广宁败后王在晋主仅守山海关，孙承宗亲履其地，以为当据宁远以蔽关。", process: "1625年（天启五年）孙承宗以大学士督师蓟辽，用袁崇焕议修复宁远，自山海关至锦州筑大城八、堡垒四十七，招流民、且耕且守，费银二百余万两。", impact: "关宁锦防线成为明末唯一足以抗后金骑兵的筑垒体系，1626年宁远、1627年宁锦之捷皆恃此线。", figures: ["孙承宗","袁崇焕","祖大寿"], place: "宁远—锦州（今辽宁兴城—锦州）", state: "明", sources: ["《明史·孙承宗传》","《明熹宗实录》卷六一","《三朝辽事实录》"], tags: ["关宁防线","屯守"] }, related: ["cn--1622--m01", "cn--1626--m01"] },
  { id: "cn--1626--d01", track: "cn", year: 1626, yearApprox: false, dim: "disaster", weight: 3, title: "北京王恭厂灾", summary: "火药局灾烈，两坊房屋尽偃。", detail: { background: "王恭厂为京师火药局所在，正德间屡灾，天启间仍贮药火数万石。", process: "1626年5月30日（天启六年五月初六巳时）王恭厂一带灾，声震京师，自宣武门以东数坊房屋尽偃，人多空身而死；《明熹宗实录》载死者以千数、伤者倍之，时抄报并记木石人畜飞堕蓟州等异。", impact: "灾后朝臣以天变示警归咎阉政，熹宗下罪己诏、减膳免朝；爆炸成因至今有火药、雷火、陨石诸说，为明代最著名的京城灾异。", figures: ["朱由校"], place: "北京城西南王恭厂（今北京西城区一带）", state: "明", sources: ["《明熹宗实录》卷七三","《天变邸抄》","《帝京景物略》"], tags: ["王恭厂","爆炸"] }, related: ["cn--1556--d01", "world--1626--d01"] },
  { id: "cn--1626--m01", track: "cn", year: 1626, yearApprox: false, dim: "military", weight: 4, title: "宁远以炮却金", summary: "红夷大炮摧攻城之众，孤城不下。", detail: { background: "1626年初高第尽撤关外守备、徙民入关，独宁远道袁崇焕不移，与满桂、祖大寿死守。", process: "正月，努尔哈赤率众围宁远（明方奏报十三万，《满文老档》所记约五六万），明以红夷大炮轰其穴城之众，二日而退；八月努尔哈赤死，诸臣重伤于炮之说遂起。", impact: "明对后金首次孤城守御成功，火器加筑城的战术得到验证；袁崇焕由此受专阃之寄，上五年复辽之议。", figures: ["袁崇焕","努尔哈赤","满桂","祖大寿"], place: "宁远（今辽宁兴城）", state: "明／后金", sources: ["《明史·袁崇焕传》","《满文老档》","《明熹宗实录》卷七三"], tags: ["宁远","红夷炮"] }, related: ["cn--1625--m01", "cn--1629--m01"] },
  { id: "cn--1627--d01", track: "cn", year: 1627, yearApprox: false, dim: "disaster", weight: 3, title: "陕北连旱起", summary: "小冰期旱蝗相仍，延安报人相食。", detail: { background: "十七世纪前半太阳活动低、东亚夏季风弱，华北自天启末连年不雨，关中、延绥尤甚。", process: "1627年（天启七年）陕西全境不雨，人畜渴死，饥民采草木、掘土以食，延安、庆阳府属县有人相食之报；同年韩城、白水饥民抢粮，有司追比钱粮益急。", impact: "旱蝗与加派并至，使陕北动乱自该年起至1644年未尝平息，饥民、驿卒、逃兵相继汇入起义军。", figures: ["朱由校"], place: "延安—庆阳（今陕西北部、甘肃东部）", state: "明", sources: ["《明史·五行志》","《陕西通志》","《明熹宗实录》卷八八"], tags: ["小冰期","旱灾"] }, related: ["cn--1628--m01"] },
  { id: "cn--1628--m01", track: "cn", year: 1628, yearApprox: false, dim: "military", weight: 3, title: "王嘉胤据府谷起事", summary: "饥民杀县吏，陕北义军始成股。", detail: { background: "天启末陕西裁驿站、加三饷，饥民与站夫无所得食，边镇兵饷又屡逋。", process: "1628年（崇祯元年）二月，王嘉胤聚众据府谷，杀县吏，旋与王二、高迎祥等合，转战陕北、山西河曲，众至数万。", impact: "陕北饥民暴动自此转为长期武装流徙，明在西北的卫所与征调同时失效，流寇遂与东虏并为崇祯朝两大病灶。", figures: ["王嘉胤","高迎祥","王二"], place: "府谷—延安（今陕西榆林—延安）", state: "明", sources: ["《明史》卷三〇九《流贼传》","《怀陵流寇始终录》","《陕西通志》"], tags: ["民变","陕北"] }, related: ["cn--1627--d01"] },
  { id: "cn--1628--p01", track: "cn", year: 1628, yearApprox: false, dim: "politics", weight: 3, title: "思宗裁除阉党", summary: "逐魏忠贤、毁《三朝要典》，起东林。", detail: { background: "1627年八月熹宗崩，思宗以信王入继；魏忠贤犹骄，言路渐起攻之。", process: "1627年十一月思宗下诏逐魏忠贤，忠贤行至阜城自缢；1628年（崇祯元年）追论《三朝要典》毁其板，起用倪元璐、东林诸遗臣，朝局为之一变。", impact: "阉党势力被清算，但清算以门户为界，东林、复社借案尽逐齐楚浙党，朝廷政争退化为派系互斥。", figures: ["朱由检","魏忠贤","崔呈秀"], place: "北京—阜城（今河北衡水阜城）", state: "明", sources: ["《明史·宦官传》","《崇祯实录》","《明季北略》"], tags: ["阉党","崇祯"] }, related: ["cn--1624--p01"] },
  { id: "cn--1629--m01", track: "cn", year: 1629, yearApprox: false, dim: "military", weight: 4, title: "己巳之变与袁崇焕之死", summary: "清军绕边入塞薄京师，崇焕磔于市。", detail: { background: "明守关宁锦，皇太极避其正面，结蒙古喀喇沁部为向导，谋从蓟镇缺口入塞。", process: "1629年（崇祯二年、后金天聪三年）十月破龙井关、大安口，十一月薄北京德胜门、广宁门；袁崇焕自山海关入卫力战，思宗以擅主和议、专杀大将等罪下之诏狱，1630年八月磔于市，祖大寿等部将士由此离心。", impact: "蓟镇防务全坏，此后清军五次入塞掠内地；明并失可用之将与可用之信，辽东与京师两线俱困。", figures: ["皇太极","袁崇焕","祖大寿","朱由检"], place: "遵化—蓟州—北京", state: "明／后金", sources: ["《明史·袁崇焕传》","《清太宗实录》卷五","《崇祯长编》"], tags: ["己巳之变","反间"] }, related: ["cn--1626--m01"] },
  { id: "cn--1629--p01", track: "cn", year: 1629, yearApprox: false, dim: "politics", weight: 3, title: "钦定逆案二百余人", summary: "以崔呈秀为首分六等，阮大铖削籍。", detail: { background: "思宗虽逐魏忠贤，但逆案范围、等级由谁划定，朝臣相持累月。", process: "1629年（崇祯二年）二月诏定逆案，自崔呈秀以下凡二百五十八人，分谋逆、奉逆、逆党、逆示诸等，已死者削职、生者定罪或削籍；《三朝要典》所翻之案一并改正。", impact: "案以其人为罪，成为党籍而非罪刑；此后东林、复社与逆案余党互控不休，崇祯朝用人始终不出门户之见。", figures: ["朱由检","崔呈秀","阮大铖"], place: "北京", state: "明", sources: ["《明史·奸臣传》","《崇祯实录》","《三朝野纪》"], tags: ["逆案","党争"] }, related: ["cn--1628--p01"] },
  { id: "cn--1629--s01", track: "cn", year: 1629, yearApprox: false, dim: "science", weight: 3, title: "开历局修《崇祯历书》", summary: "徐光启监理，以西洋算法改历。", detail: { background: "《大统历》沿用三百年，朔望、交食屡验不准；日食实测中西之法高下已见。", process: "1629年（崇祯二年）六月诏开历局于京师，以礼部侍郎徐光启监理，聘龙华民、汤若望、罗雅谷等翻译演算，专据第谷之体系改写诸表。", impact: "中国传统历法第一次整体让位于西洋算法体系；1634年前后书成百余卷，其法入清后沿用二百年。", figures: ["徐光启","汤若望","龙华民","罗雅谷"], place: "北京历局（今北京）", state: "明", sources: ["《崇祯历书》","《明史·历志》","《徐光启集》"], tags: ["历法","西学"] }, related: ["cn--1607--s01", "cn--1610--c01"] },
  { id: "cn--1633--s01", track: "cn", year: 1633, yearApprox: false, dim: "science", weight: 2, title: "徐光启卒", summary: "历书未竟而总监先逝，谥曰文定。", detail: { background: "徐光启晚年同时任历局、火器、屯田之责，与内阁不合，屡被论劾。", process: "1633年（崇祯六年）十一月初八徐光启卒于北京，年七十二；历局事由其继任李天经与汤若望等卒成，遗疏以历法、兵器、农政三事为托。", impact: "明末最通贯的一位通才退场，其历书与农政遗产主要由门人、后学接续，西学在中国的官方支持随之减弱。", figures: ["徐光启","李天经"], place: "北京—松江（今上海市）", state: "明", sources: ["《徐光启集》","《明史·徐光启传》","《崇祯历书》"], tags: ["历算","农学"] }, related: ["cn--1629--s01"] },
  { id: "cn--1635--i01", track: "cn", year: 1635, yearApprox: false, dim: "institution", weight: 2, title: "后金定族名为满洲", summary: "废诸申旧号，重定共同体之名。", detail: { background: "皇太极以诸申、女直旧号为属部之称，且部众多已杂糅蒙古、汉人。", process: "1635年（天聪九年）十月，废诸申旧称，定族名为满洲，禁人称旧号；同时以固山额真统八旗之满洲、蒙古、汉军佐领，户口、婚姻、诉讼皆归旗制。", impact: "共同体名称的重定切断了对明属夷身份的记忆，为次年称帝改元准备了名分与制度基础。", figures: ["皇太极"], place: "盛京（今辽宁沈阳）", state: "后金", sources: ["《清太宗实录》卷二五","《满文老档》","《八旗通志》"], tags: ["满洲","族名"] }, related: ["cn--1636--p01"] },
  { id: "cn--1636--m01", track: "cn", year: 1636, yearApprox: false, dim: "military", weight: 3, title: "丙子之役朝鲜臣服", summary: "围南汉山城，仁祖行城下之盟。", detail: { background: "朝鲜仁祖亲明备清，1627年丁卯之约后仍奉明正朔、修城募兵。", process: "1636年（崇德元年）十二月皇太极率众渡江，1637年正月仁祖退保南汉山城，清军围之数十日；二月仁祖出至三田渡，去明年号，以长子及再弟为质，岁贡方物。", impact: "朝鲜被迫断绝与明的宗藩关系，成为清征明的粮饷、水军与兵源供给地；1644年后仍私下奉明正朔，小中华意识由此而生。", figures: ["皇太极","李倧","金尚宪"], place: "汉阳—三田渡（今韩国首尔）", state: "清／朝鲜", sources: ["《朝鲜王朝实录·仁祖实录》","《承政院日记》","《清太宗实录》"], tags: ["丙子之役","宗藩"] }, related: ["cn--1592--m01"] },
  { id: "cn--1636--p01", track: "cn", year: 1636, yearApprox: false, dim: "politics", weight: 4, title: "皇太极称帝改元崇德", summary: "盛京祭天即皇帝位，国号大清。", detail: { background: "1635年所得传国玺被视为天命之符，诸贝勒与汉臣屡请上尊号、定国号。", process: "1636年（崇德元年）四月，皇太极祭天地宗庙即皇帝位，国号大清，改元崇德，以盛京为都，定五府、三院、六部、都察院官制，参用明制而存议政王大臣。", impact: "后金由部落联盟之汗国转为仿明的帝国体制，对明战略从抢掠转为入主，其制度班底亦为1644年接管全国做准备。", figures: ["皇太极","多尔衮","范文程"], place: "盛京（今辽宁沈阳）", state: "清", sources: ["《清太宗实录》卷二八","《大清会典》","《东华录》"], tags: ["改元","国号"] }, related: ["cn--1635--i01"] },
  { id: "cn--1637--s01", track: "cn", year: 1637, yearApprox: false, dim: "science", weight: 4, title: "《天工开物》刊行", summary: "宋应星记一百三十余目百工之法。", detail: { background: "江西奉新举人宋应星屡试不第，留心于功名进取毫不相关之技艺。", process: "1637年（崇祯十年）《天工开物》初刻，凡十八卷、一百三十余目，自谷物栽培、纺染、盐、煤、陶、冶、车船、火药、珠玉，皆记其法并附工料数量与图。", impact: "中国古代最完整的工艺百科全书；十七世纪传入日本被广泛引用，十九世纪由传教士摘译入欧洲，若干技术记述为现存唯一记录。", figures: ["宋应星"], place: "奉新—南昌（今江西宜春—南昌）", state: "明", sources: ["《天工开物》初刻本","《奉新县志》","潘吉星《天工开物校注及研究》"], tags: ["工艺","科技史"] }, related: [] },
  { id: "cn--1637--x01", track: "cn", year: 1637, yearApprox: false, dim: "explore", weight: 3, title: "徐霞客始万里远征", summary: "五年西南考察，辨江源记岩溶。", detail: { background: "徐宏祖（霞客，1587—1641）三十年间北登恒、岱，西南一侧足迹未至。", process: "1637年（崇祯十年）秋，五十岁的徐霞客由江浙入湖广，此后五年历今湘、赣、桂、黔、滇，考察石灰岩洞穴与金沙江源，所至以日记记之。", impact: "其游记纠正《禹贡》岷山导江之旧说，确认金沙江为长江正源，并对岩溶地貌作近乎近代地理学的描述；书至1767年方刻行。", figures: ["徐霞客"], place: "湖广—云南（今湖南—云南）", state: "明", sources: ["《徐霞客游记》","《滇游日记》","《晴山堂帖》"], tags: ["地理考察","岩溶"] }, related: [] },
  { id: "cn--1639--e01", track: "cn", year: 1639, yearApprox: false, dim: "economy", weight: 4, title: "加练饷七百三十万两", summary: "因兵练饷再派田赋，民力遂竭。", detail: { background: "崇祯朝辽饷九百余万、剿饷二百八十万两犹不足用，兵部尚书杨嗣昌主因兵练饷之议。", process: "1639年（崇祯十二年）九月诏加练饷，每亩加银七厘四毫六丝，全国派银七百三十万两，与辽饷、剿饷合称三饷；有司以完分数考成，追比苛急。", impact: "三饷合计超过正赋一倍以上，农户弃田逃亡相继，兵与贼皆因之得源；明末财政崩溃由此成为定局。", figures: ["朱由检","杨嗣昌"], place: "两京十三省", state: "明", sources: ["《明史·食货志》","《杨文弱公集》","《怀陵流寇始终录》"], tags: ["三饷","财政"] }, related: ["cn--1581--i01"] },
  { id: "cn--1639--s01", track: "cn", year: 1639, yearApprox: true, dim: "science", weight: 3, title: "《农政全书》订刻行世", summary: "陈子龙增订徐氏遗稿为六十卷。", detail: { background: "徐光启晚年辑中外农事，稿凡数易，1633年卒时未及釐定。", process: "约1639年前后（崇祯十二年前后）陈子龙、张溥就徐氏遗稿删订为《农政全书》六十卷，分农本、田制、水利、农器、树艺、蚕疏、占候、种植、牧养、制造、荒政十二门，引书二百二十余种。", impact: "中国传统农学的殿军之作；其荒政一门集历代救荒之方，在小冰期饥馑年代成为州县备荒手册，清初入《四库全书》。", figures: ["徐光启","陈子龙","张溥"], place: "松江—嘉兴（今上海—浙江）", state: "明", sources: ["《农政全书》平露堂刻本","《农政全书凡例》","《徐光启集》"], tags: ["农学","救荒"] }, related: ["cn--1633--s01"] },
  { id: "cn--1640--m01", track: "cn", year: 1640, yearApprox: false, dim: "military", weight: 3, title: "清始围锦州", summary: "皇太极取先夺锦宁之策，困城两年。", detail: { background: "明守关宁锦，皇太极采先夺锦州、以困宁远之策，围城断其饷道。", process: "1640年（崇祯十三年）三月清军围锦州，祖大寿困守；明廷令洪承畴督蓟辽八镇兵东援，屯于松山、杏山之间，与之相持。", impact: "围城相持两年余，明在辽西仅存的据点成为决定性赌注，亦使洪承畴所部九万人被困于粮尽之地。", figures: ["皇太极","洪承畴","祖大寿"], place: "锦州—松山（今辽宁锦州）", state: "明／清", sources: ["《清太宗实录》卷三一","《明史·洪承畴传》","《明季北略》"], tags: ["松锦","围城"] }, related: ["cn--1625--m01", "cn--1642--m01"] },
  { id: "cn--1641--d01", track: "cn", year: 1641, yearApprox: false, dim: "disaster", weight: 4, title: "崇祯大鼠疫大行", summary: "南北直隶山东三晋，十室九病。", detail: { background: "小冰期灾荒之后，华北鼠疫自然疫源地扩散，军屯、驿路、市镇人口密集而食不足。", process: "1641年（崇祯十四年）疫大行，自浙江、南直隶而北，山东、河南、北直隶、山西、陕西相继；时人记一巷百室、十室九病，朝得病夕死，崇祯末京师守垛者日不过数千，多患横痃疙瘩之症。", impact: "疫情与饥荒交攻，使明军战兵锐减、州县户役空虚，1643至1644年北中国防线几近无人可守；此为近代学者解释明亡的重要一环。", figures: ["朱由检"], place: "北直隶—山东—河南—山西", state: "明", sources: ["《明史·五行志》","《崇祯实录》","曹树基《明清鼠疫流行及其与灾荒战乱的关系》"], tags: ["鼠疫","灾荒"] }, related: ["cn--1644--p01"] },
  { id: "cn--1641--m01", track: "cn", year: 1641, yearApprox: false, dim: "military", weight: 3, title: "李自成克洛阳杀福王", summary: "取藩府金粮以赈饥，众益至数万。", detail: { background: "福王朱常洵就藩洛阳，占田数万顷、货殖累巨万，崇祯朝不肯输饷助辽。", process: "1641年（崇祯十四年）正月二十一日李自成克洛阳，杀福王常洵，发库金粮以赈饥民，应之者数万；同年四月、五月两攻开封不克，遂转下河南诸州县。", impact: "义军由陕北流徙转为夺取藩府资财的长期战争，宗藩财产自此成为饥民与溃兵的共同猎物。", figures: ["李自成","朱常洵"], place: "洛阳（今河南洛阳）", state: "明", sources: ["《明史·福王传》","《豫变纪略》","《怀陵流寇始终录》"], tags: ["李自成","藩府"] }, related: ["cn--1642--d01"] },
  { id: "cn--1642--d01", track: "cn", year: 1642, yearApprox: false, dim: "disaster", weight: 3, title: "开封黄河决城", summary: "大汛溃城，全城尽溺。", detail: { background: "1642年李自成再围开封，黄河自城北决口，与围城兵祸并发。", process: "1642年（崇祯十五年）九月黄河大汛，水自北门、曹门入城，屋庐尽没；《明史·五行志》与《豫变纪略》并载溺死者数十万，存者以数万计，周王府宫室皆圮。", impact: "决口究为明军所为抑或义军所为，明清记载互异，现代学界尚无定论；开封作为北宋故都的城市史自此中辍，城中居民多靠船筏得全。", figures: ["高名衡","李自成"], place: "开封（今河南开封）", state: "明", sources: ["《明史·五行志》","《豫变纪略》卷二","《开封府志》"], tags: ["河决","围城"] }, related: ["cn--1641--m01"] },
  { id: "cn--1642--m01", track: "cn", year: 1642, yearApprox: false, dim: "military", weight: 3, title: "松山陷洪承畴降清", summary: "城内食尽而破，关外明军主力覆。", detail: { background: "1641年洪承畴督十三万之众被围松山，清军断其饷道，诸将溃围而还。", process: "1642年（崇祯十五年）二月十八日清军借内应破松山，屠其城，斩首五千余级；洪承畴被俘后降清，祖大寿以锦州孤城旋亦出降，关外唯余山海一城。", impact: "明在辽西的将材、士卒与火器尽失，清得以全力入塞，并取朝鲜、蒙古之兵与汉军旗之炮，为1644年入关准备条件。", figures: ["洪承畴","皇太极","祖大寿"], place: "松山—锦州（今辽宁锦州）", state: "明／清", sources: ["《清太宗实录》卷三五","《明史·洪承畴传》","《明季北略》"], tags: ["松锦","降将"] }, related: ["cn--1640--m01"] },
  { id: "cn--1643--p01", track: "cn", year: 1643, yearApprox: false, dim: "politics", weight: 3, title: "李自成建政襄阳", summary: "改襄京、设六政府，称新顺王。", detail: { background: "1642至1643年义军取湖广、河南四十余州县，李自成用顾君恩先取关中为基业之策。", process: "1643年（崇祯十六年）正月改襄阳为襄京，建丞相、六政府等官，称新顺王；九月克武昌，十月入西安，改西安为长安而都之，铸钱设科。", impact: "义军由流劫转为建国，形成明、清、大顺三方对峙；其建制与追赃助饷之策，直接决定1644年北京局势的走向。", figures: ["李自成","顾君恩","牛金星"], place: "襄阳—西安（今湖北—陕西）", state: "大顺／明", sources: ["《明史》卷三〇九","《绥寇纪略》","《罪惟录》"], tags: ["大顺","建制"] }, related: ["cn--1644--p01", "world--1644--p01"] },
  { id: "cn--1643--p02", track: "cn", year: 1643, yearApprox: false, dim: "politics", weight: 3, title: "皇太极骤死多尔衮摄政", summary: "无诏而诸王相持，六岁帝即位。", detail: { background: "清以八旗共主之制未定储嗣，豪格与多尔衮各拥两黄、两白旗相持。", process: "1643年（崇德八年）八月二十三日皇太极暴亡，无遗诏；诸王议两日不得决，以立幼子福临、郑亲王济尔哈朗与多尔衮同辅政为折衷，九月六岁帝即位，改元顺治。", impact: "实权归于多尔衮一人，其1644年果断西进、定鼎燕京之策由摄政体制得以推行；豪格一系由此失势。", figures: ["皇太极","多尔衮","豪格","福临"], place: "盛京（今辽宁沈阳）", state: "清", sources: ["《清太宗实录》卷末","《清世祖实录》卷一","《东华录》"], tags: ["皇位继承","摄政"] }, related: ["cn--1636--p01"] },
];
